-- roblox/tools/install_obby_mode.lua  (GENERATED by roblox/tools/build_install_obby.py - do not edit;
-- change the repo files and re-run the generator)
-- Imports Robo Obby's code into the arcade place in one step (docs/obby-mode-plan.md). Run it in Studio, in
-- Edit mode: paste it into the command bar, or the Studio MCP's execute_luau. It creates:
--   ServerStorage.Modes.Obby.Module    (ModuleScript)  the arcade mode                 [replaced if present]
--   ServerStorage.Modes.Obby.Server    (Folder)  the course's server modules, cloned per round  [replaced]
--   ReplicatedStorage.Obby             (Folder)  Config, UiTheme, Remotes (the RemoteEvents), Views.*  [replaced]
--   ReplicatedStorage.Core.Games.Obby  (ModuleScript)  the GameRegistry entry           [replaced if present]
-- It keeps ServerStorage.Modes.Obby.Map (insert places/ObbyMap.rbxm there, made by
-- roblox/tools/prepare_obby_map.lua in Place1) and checks it: Warehouse / Backdrop / Start / Finish /
-- LobbyPad, no SpawnLocation or script inside, Persistent streaming, moved to Config.OriginZ. It disables
-- (never deletes) standalone obby scripts left over from Place1, which would open their own robot socket,
-- set Lighting and run outside the mode contract. It touches nothing else (not Lighting, not the Workshop);
-- the bay Workspace.Workshop.Bays.Bay1_Obby already names this mode ("Obby").

local ServerStorage = game:GetService("ServerStorage")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerScriptService = game:GetService("ServerScriptService")
local StarterPlayer = game:GetService("StarterPlayer")
local CollectionService = game:GetService("CollectionService")
local ChangeHistoryService = game:GetService("ChangeHistoryService")

local SERVICES = { ServerStorage = ServerStorage, ReplicatedStorage = ReplicatedStorage }
local made = {}
local problems = {}

local function problem(fmt, ...)
	table.insert(problems, string.format(fmt, ...))
end

local function folderAt(path)
	local names = string.split(path, ".")
	local node = SERVICES[names[1]]
	assert(node, "unknown service in " .. path)
	for i = 2, #names do
		local child = node:FindFirstChild(names[i])
		if not child then
			child = Instance.new("Folder")
			child.Name = names[i]
			child.Parent = node
		end
		node = child
	end
	return node
end

local function put(path, className, source)
	local parentPath, name = string.match(path, "^(.*)%.([^%.]+)$")
	local parent = folderAt(parentPath)
	local old = parent:FindFirstChild(name)
	if old then
		old:Destroy()
	end
	local inst = Instance.new(className)
	inst.Name = name
	inst.Source = source
	inst.Parent = parent
	table.insert(made, path)
	return inst
end

local function replace(path)
	local parentPath, name = string.match(path, "^(.*)%.([^%.]+)$")
	local parent = folderAt(parentPath)
	local old = parent:FindFirstChild(name)
	if old then
		print("[install_obby_mode] replacing " .. old:GetFullName())
		old:Destroy()
	end
end

pcall(function()
	ChangeHistoryService:SetWaypoint("Before installing Robo Obby")
end)

assert(ReplicatedStorage:FindFirstChild("Core") and ReplicatedStorage.Core:FindFirstChild("GameRegistry"),
	"ReplicatedStorage.Core (the roles core) is missing: install the arcade lobby first")
if not (ServerStorage:FindFirstChild("Shared") and ServerStorage.Shared:FindFirstChild("StateStore")
	and ServerStorage.Shared:FindFirstChild("Bridge")) then
	problem("ServerStorage.Shared.StateStore / Bridge are missing: every round runs solo (no robot)")
end
if not ServerScriptService:FindFirstChild("Bridge") then
	problem("ServerScriptService.Bridge (the core's robot link) is missing: every round runs solo")
end

replace("ServerStorage.Modes.Obby.Server")
replace("ServerStorage.Modes.Obby.Runtime") -- a round's clone saved by accident; Start makes a fresh one
replace("ReplicatedStorage.Obby")

local SOURCES = {}
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Module", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Module
-- Robo Obby as an arcade mode (docs/arcade-plan.md "Mode contract", docs/obby-mode-plan.md). Kushagra's
-- course (lebot_obby/, obby_planmds/) runs here unchanged in what it asks of the player: four bays (Saw Wall,
-- Void, Laser Walk, Dark Room) that the robot operator solves with real cubes while the runner crosses them.
-- The arcade requires this at server start, calls Start(players) when the Obby bay's join window closes,
-- waits for Finished (up to MaxDuration seconds, or until everyone took a Back to Lobby pad) and then calls
-- Stop().
--   Start(players)  clones the Map into Workspace as ObbyMap (baked at Config.OriginZ, far from the other
--                   games) and the Server folder as Runtime, then requires the Runtime modules in order:
--                   fresh module state every round, so nothing from the last round can fire into this one.
--                   Feed mode for the round: "live" (the real arm owns the crates) when the core robot link
--                   is up, else "solo" (the runner places blocks on the on-screen grid). Puts the runners on
--                   Map.Start facing the course, enables the Back to Lobby pad and starts the run clock.
--                   Runners play at Config.RunnerScale (1.0, the size the course was built for), not the
--                   arcade's 1.5x: Start shrinks them, every respawn during the round is shrunk again, and
--                   Stop / PlayerLeft give them back Config.ArcadeScale (CharacterScale's 1.5).
--   the run         reach Map.Finish (past bay 4's exit door, bay 4 solved) before the clock
--                   (Config.FullRunSeconds) runs out: won = true. A runner who dies comes back at the
--                   approach to the furthest bay they reached, rebuilt fresh. When every runner has finished
--                   or gone, or the clock hits 0, the result shows for Config.ResultSeconds and
--                   Finished:Fire({ { player = p, won = ... }, ... }) goes out exactly once, one entry per
--                   player passed to Start (won = true for everyone who reached the finish, false otherwise).
--   IsDecided()     true once a runner has finished or the clock ran out. The arcade asks before a Back to
--                   Lobby pad: decided, the player keeps the result this mode reports; not decided, a pad
--                   is a loss.
--   PlayerLeft(p)   the arcade took p out through the Back to Lobby pad (Map.LobbyPad, tagged
--                   LobbyTeleporter; Enabled before the runner enters bay 1, and from the moment the round
--                   is decided): p keeps a finish, otherwise loses; nobody left ends the round right away.
--   Stop()          stops every module (their tracked connections and threads), clears the HUDs, destroys
--                   the map and the Runtime clone. Start works again afterwards.
-- The robot role has no character, so the arcade never passes it to Start: it gets Views.RobotView (the
-- overseer camera) through ReplicatedStorage.Core.Games.Obby, which ServerScriptService.ArcadeActiveGame
-- makes the active game while the bay runs. Nothing here opens a socket or touches Lighting.

local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local StarterPlayer = game:GetService("StarterPlayer")

local folder = script.Parent
local Obby = ReplicatedStorage:WaitForChild("Obby")
local Config = require(Obby:WaitForChild("Config"))
local mapTemplate = folder:WaitForChild("Map")
local serverTemplate = folder:WaitForChild("Server")

local Roles = nil
do
	local core = ReplicatedStorage:FindFirstChild("Core")
	local module = core and core:FindFirstChild("Roles")
	if module then
		local ok, result = pcall(require, module)
		Roles = ok and result or nil
	end
end

-- The arcade's handle on the core robot link (never a socket of our own). Missing in a bare test place.
local function sharedBridge()
	local shared = ServerStorage:FindFirstChild("Shared")
	local module = shared and shared:FindFirstChild("Bridge")
	if not module then
		return nil
	end
	local ok, result = pcall(require, module)
	return ok and result or nil
end

local REMOTES = {
	"Objective", "CellEdit", "CellsUpdated", "DebugHotkey", "GhostToggle", "DebugCommand", "Status", "BayCells",
	"CameraFace", "Toast",
}
-- Runtime modules in the order they are required. The former Scripts do their work at require time.
local LOAD_ORDER = { "BlockSync", "SkyArm", "HazardManager", "Status", "BridgeFeed", "DebugMode", "ActiveBayTracker" }
local DEBUG_ORDER = { "DebugMenu", "GhostMode" } -- only with Config.ArcadeDebug
local POLL = 0.25         -- seconds between finish / leaver / clock checks
local START_SPACING = 5   -- studs between runners on the start (fits 1.5x characters)
local MAP_NAME = "ObbyMap"
local LOBBY_TAG = "LobbyTeleporter"

local Mode = {}
Mode.DisplayName = "Robo Obby"
Mode.Tip = "Shout the cells, the robot builds your way through!"
Mode.WinsToUnlock = 0
Mode.Finished = Instance.new("BindableEvent")
Mode.MaxDuration = 500 -- seconds from Start to Finished, at most: the run clock (480) + result screen + slack

local function getOrCreate(parent, className, name)
	local child = parent:FindFirstChild(name)
	if not child then
		child = Instance.new(className)
		child.Name = name
		child.Parent = parent
	end
	return child
end

local remotes = getOrCreate(Obby, "Folder", "Remotes")
for _, name in ipairs(REMOTES) do
	getOrCreate(remotes, "RemoteEvent", name)
end
local objective = remotes.Objective

local function log(fmt, ...)
	print("[Obby] " .. string.format(fmt, ...))
end

local session = nil -- the running round, nil between Stop and Start

local function rootOf(player)
	local character = player.Character
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	local hum = character and character:FindFirstChildOfClass("Humanoid")
	if hrp and hum and hum.Health > 0 then
		return hrp
	end
	return nil
end

-- Is a world position inside a part's box (any rotation)?
local function inside(part, position)
	local p = part.CFrame:PointToObjectSpace(position)
	local half = part.Size / 2
	return math.abs(p.X) <= half.X and math.abs(p.Y) <= half.Y and math.abs(p.Z) <= half.Z
end

-- Scales a runner's character to `scale` (Model:ScaleTo is absolute) and keeps the feet where they were:
-- ScaleTo scales about the pivot (the root), so growing would sink the legs into the floor and shrinking
-- would leave them in the air. Walk speed and jump height go back to StarterPlayer's, because ScaleTo
-- scales those too (the arcade's CharacterScale does the same after its 1.5x). Returns true if it scaled.
local function setScale(player, scale)
	local character = player.Character
	local hum = character and character:FindFirstChildOfClass("Humanoid")
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	if not (hum and hrp) or hum.Health <= 0 or math.abs(character:GetScale() - scale) < 1e-3 then
		return false
	end
	local function standHeight() -- the root's height over what the character stands on
		if hum.RigType == Enum.HumanoidRigType.R15 then
			return hum.HipHeight + hrp.Size.Y / 2
		end
		return hrp.Size.Y * 1.5 -- R6: legs as tall as the torso
	end
	local before = standHeight()
	character:ScaleTo(scale)
	character:PivotTo(character:GetPivot() + Vector3.new(0, standHeight() - before, 0))
	hum.WalkSpeed = StarterPlayer.CharacterWalkSpeed
	hum.JumpHeight = StarterPlayer.CharacterJumpHeight
	return true
end

-- Every runner at the course's size. Run every POLL as well as on Start and respawn, because the arcade's
-- CharacterScale grows a new character only once its appearance has loaded (up to 5 s after it spawns), so
-- a respawned runner can be grown back to 1.5x after we placed them.
local function enforceScale(s)
	for _, p in ipairs(s.runners) do
		setScale(p, Config.RunnerScale or 1)
	end
end

-- Which bay a course Z belongs to, counting the catwalk after a bay as the next one (ActiveBayTracker's rule).
local function bayAtCourseZ(z)
	if z < 0 then
		return 1
	end
	local i = math.floor(z / Config.BayPitch) + 1
	if z - (i - 1) * Config.BayPitch > Config.BayDepth then
		i += 1
	end
	return math.clamp(i, 1, Config.NumBays)
end

-- Decided: a runner has reached the finish, or the round is over (the clock ran out, or everyone left).
local function decided(s)
	return s.done or next(s.finishedAt) ~= nil
end

local function setPad(s, on)
	if s.lobbyPad then
		s.lobbyPad:SetAttribute("Enabled", on)
	end
end

local function refreshRunners(s)
	table.clear(s.runners)
	for _, p in ipairs(s.list) do
		if p.Parent ~= nil and not s.left[p] then
			table.insert(s.runners, p)
		end
	end
end

-- Shows `payload` to a player on the objective HUD, holding it there (HazardManager's bays stay off it).
local function hold(s, player, payload)
	s.hudHeld[player] = true
	objective:FireClient(player, payload)
end

local function fireFinished(s)
	if session ~= s or s.firedFinished then
		return
	end
	s.firedFinished = true
	local results = {}
	for _, p in ipairs(s.list) do
		-- a finish counts even for a runner who then took the pad: the round was decided (IsDecided)
		table.insert(results, { player = p, won = s.finishedAt[p] ~= nil })
	end
	Mode.Finished:Fire(results)
end

-- Ends the round once: the result screen, then Finished. why: "finished" / "time" / "everyone left".
-- immediate: Finished right away, no result screen (nobody is left to see it, and the arcade only waits
-- a moment for a mode whose last player left).
local function endRound(s, why, immediate)
	if s.done then
		return
	end
	s.done = true
	local anyWon = next(s.finishedAt) ~= nil
	Obby:SetAttribute("RunState", anyWon and "Won" or "Lost")
	setPad(s, true) -- the round is decided: taking the pad now costs nothing
	s.hudHeld.all = true
	for _, p in ipairs(s.runners) do
		local won = s.finishedAt[p] ~= nil
		objective:FireClient(p, {
			title = won and "COURSE CLEAR!" or (why == "time" and "TIME'S UP" or "RUN OVER"),
			task = won and string.format("You beat the Robo Obby in %d:%02d", s.finishedAt[p] // 60, s.finishedAt[p] % 60)
				or "The course wins this time.",
			hint = "Heading back to the workshop...",
			tone = won and "ok" or "danger",
		})
	end
	for _, r in ipairs(s.robots()) do
		objective:FireClient(r, {
			title = anyWon and "COURSE CLEAR!" or (why == "time" and "TIME'S UP" or "RUN OVER"),
			task = anyWon and "Your runner made it through." or "The runner didn't make it this time.",
			hint = "Heading back to the workshop...",
			tone = anyWon and "ok" or "danger",
		})
	end
	local names = {}
	for _, p in ipairs(s.list) do
		table.insert(names, p.Name .. "=" .. (s.finishedAt[p] and "WIN" or "LOSE"))
	end
	log("round over (%s): %s", why, #names > 0 and table.concat(names, " ") or "no players")

	if immediate then
		fireFinished(s)
		return
	end
	s.spawn(function()
		task.wait(Config.ResultSeconds or 4)
		fireFinished(s)
	end)
end

-- One check (every POLL seconds): leavers, the run starting, furthest bays, the finish, the clock.
local function tick(s)
	if s.done then
		return
	end
	refreshRunners(s)
	if #s.runners == 0 then
		endRound(s, "everyone left", true)
		return
	end
	local RunControl = s.RunControl
	local now = workspace:GetServerTimeNow()
	local lastBay = RunControl.bayState and RunControl.bayState(Config.NumBays)
	local allDone = true
	for _, p in ipairs(s.runners) do
		local hrp = rootOf(p)
		if hrp then
			local z = RunControl.courseZ(hrp.Position.Z)
			if s.phase == "Ready" and z >= 0 then
				-- into bay 1: the run is on, and the pad goes dark until the round is decided
				s.phase = "Running"
				Obby:SetAttribute("RunState", "Running")
				setPad(s, false)
				log("%s started the course", p.Name)
			end
			s.furthest[p] = math.max(s.furthest[p] or 1, bayAtCourseZ(z))
			if not s.finishedAt[p] and s.finish and inside(s.finish, hrp.Position) and lastBay and lastBay.solved then
				s.finishedAt[p] = math.floor(now - s.startedAt)
				log("%s reached the finish in %d s", p.Name, s.finishedAt[p])
				setPad(s, true) -- decided: a pad now keeps the result (IsDecided)
				hold(s, p, {
					title = "COURSE CLEAR!",
					task = #s.runners > 1 and "Waiting for the others..." or "You made it!",
					tone = "ok",
				})
			end
		end
		if not s.finishedAt[p] then
			allDone = false
		end
	end
	if allDone then
		endRound(s, "finished")
	elseif now >= s.endsAt then
		endRound(s, "time")
	end
end

-- A runner's new character (they died): back to the approach of the furthest bay they reached, that bay
-- rebuilt fresh so a sealed gate or a half-closed saw wall can't lock them out.
local function onRespawn(s, player)
	local respawnedAt = os.clock()
	task.wait(Config.RespawnSettleSeconds or 0.6) -- let the new character settle (Humanoid, root) first
	if session ~= s or s.done or s.left[player] or not rootOf(player) then
		return
	end
	if (s.placedAt[player] or -math.huge) >= respawnedAt then
		return -- a debug command (LoadCharacter + teleport) already placed this character
	end
	setScale(player, Config.RunnerScale or 1) -- the arcade grew the new character to 1.5x
	local RunControl = s.RunControl
	local i = s.furthest[player] or 1
	if s.phase == "Ready" then
		RunControl.placeCharacter(player, RunControl.startCFrame())
		return
	end
	-- Rebuild only if no other living runner is in that bay right now (it would reset under their feet).
	local busy = false
	for _, other in ipairs(s.runners) do
		local hrp = other ~= player and rootOf(other)
		if hrp and bayAtCourseZ(RunControl.courseZ(hrp.Position.Z)) == i then
			busy = true
		end
	end
	if not busy and RunControl.rebuildBay then
		RunControl.rebuildBay(i)
	end
	RunControl.placeCharacter(player, RunControl.approachCFrame(i))
	log("%s respawned at bay %d%s", player.Name, i, busy and " (bay kept: another runner is in it)" or "")
end

-- players: the arcade's list of Players with characters.
function Mode.Start(players)
	if session then
		Mode.Stop()
	end
	local debug = Config.ArcadeDebug == true or folder:GetAttribute("ArcadeDebug") == true

	local map = mapTemplate:Clone()
	map.Name = MAP_NAME
	map.Parent = workspace
	local runtime = serverTemplate:Clone()
	runtime.Name = "Runtime"
	runtime.Parent = folder -- parented before requiring: the modules find their siblings through script.Parent

	local s = {
		map = map, warehouse = map:WaitForChild("Warehouse"), runtime = runtime, debug = debug,
		list = {}, inGame = {}, left = {}, runners = {}, finishedAt = {}, furthest = {}, hudHeld = {}, placedAt = {},
		conns = {}, threads = {}, modules = {}, alive = true, done = false, phase = "Ready",
	}
	function s.track(connection)
		table.insert(s.conns, connection)
		return connection
	end
	function s.spawn(fn, ...)
		local thread = task.spawn(fn, ...)
		table.insert(s.threads, thread)
		return thread
	end
	function s.isRunner(player)
		return table.find(s.runners, player) ~= nil
	end
	function s.robots()
		local list = {}
		if Roles then
			for _, p in ipairs(Players:GetPlayers()) do
				if Roles.of(p) == Roles.ROBOT then
					table.insert(list, p)
				end
			end
		end
		return list
	end
	for _, p in ipairs(players or {}) do
		if not s.inGame[p] then
			s.inGame[p] = true
			table.insert(s.list, p)
		end
	end
	refreshRunners(s)
	session = s

	s.finish = map:FindFirstChild("Finish")
	s.lobbyPad = map:FindFirstChild("LobbyPad")
	if s.lobbyPad and not CollectionService:HasTag(s.lobbyPad, LOBBY_TAG) then
		CollectionService:AddTag(s.lobbyPad, LOBBY_TAG)
	end
	if not s.finish then
		warn("[Obby] Map.Finish is missing: nobody can win this round (see docs/obby-mode-plan.md)")
	end

	local bridge = sharedBridge()
	local feedMode = (bridge and bridge.isOnline()) and "live" or "solo"
	Obby:SetAttribute("ArcadeDebug", debug)
	Obby:SetAttribute("FeedMode", feedMode)
	Obby:SetAttribute("RunSeconds", Config.FullRunSeconds)
	Obby:SetAttribute("RunState", "Ready")
	s.startedAt = workspace:GetServerTimeNow()
	s.endsAt = s.startedAt + Config.FullRunSeconds
	Obby:SetAttribute("RunEndsAt", s.endsAt)

	local RunControl = require(runtime:WaitForChild("RunControl"))
	s.RunControl = RunControl
	RunControl.session = s
	RunControl.feedMode = feedMode
	RunControl.setActiveBay(1)
	for _, name in ipairs(LOAD_ORDER) do
		s.modules[name] = require(runtime:WaitForChild(name))
	end
	if debug then
		for _, name in ipairs(DEBUG_ORDER) do
			s.modules[name] = require(runtime:WaitForChild(name))
		end
	end

	-- The runners at the course's size, on the start, side by side across it, facing down the course.
	enforceScale(s)
	local start = RunControl.startCFrame()
	for i, p in ipairs(s.runners) do
		local k = i - 1
		local side = (k % 2 == 0 and 1 or -1) * math.ceil(k / 2) -- 0, -1, +1, -2, +2 ...
		RunControl.placeCharacter(p, start + start.RightVector * side * START_SPACING)
		s.track(p.CharacterAdded:Connect(function()
			s.spawn(onRespawn, s, p)
		end))
	end
	setPad(s, true)

	s.spawn(function()
		while session == s and s.alive do
			task.wait(POLL)
			if session == s and s.alive then
				enforceScale(s) -- until Stop, result screen included
				tick(s)
			end
		end
	end)
	log("started: %d runner%s, %s mode, %d s on the clock%s", #s.runners, #s.runners == 1 and "" or "s", feedMode,
		Config.FullRunSeconds, debug and ", ARCADE DEBUG ON" or "")
	return s
end

-- The arcade took `player` out through the Back to Lobby pad: they lose, and the round ends when every
-- runner has left or gone.
function Mode.PlayerLeft(player)
	local s = session
	if not s or not s.inGame[player] or s.left[player] then
		return
	end
	s.left[player] = true
	s.hudHeld[player] = true
	objective:FireClient(player, nil)
	refreshRunners(s)
	setScale(player, Config.ArcadeScale or 1.5) -- back to the arcade's size, already in the Workshop
	log("%s went back to the lobby%s", player.Name, s.finishedAt[player] and " (keeps the finish)" or "")
	if #s.runners == 0 then
		endRound(s, "everyone left", true)
	end
end

-- The arcade asks this before a Back to Lobby pad: once a runner has finished or the clock ran out, the
-- player keeps the result reported in Finished (a finish is a win, anything else a loss).
function Mode.IsDecided()
	local s = session
	return s ~= nil and decided(s)
end

function Mode.Stop()
	local s = session
	if not s then
		return
	end
	session = nil
	s.alive = false
	s.hudHeld.all = true
	for name, module in pairs(s.modules) do
		if type(module) == "table" and type(module.stop) == "function" then
			local ok, err = pcall(module.stop)
			if not ok then
				warn("[Obby] " .. name .. ".stop failed: " .. tostring(err))
			end
		end
	end
	for _, connection in ipairs(s.conns) do
		connection:Disconnect()
	end
	table.clear(s.conns)
	for _, thread in ipairs(s.threads) do
		if thread ~= coroutine.running() and coroutine.status(thread) ~= "dead" then
			task.cancel(thread)
		end
	end
	table.clear(s.threads)
	for _, p in ipairs(s.list) do
		if p.Parent then
			objective:FireClient(p, nil)
			if not s.left[p] then
				setScale(p, Config.ArcadeScale or 1.5) -- (pad leavers were given it back in PlayerLeft)
			end
		end
	end
	for _, r in ipairs(s.robots()) do
		objective:FireClient(r, nil)
	end
	if s.RunControl then
		s.RunControl.session = nil
	end
	for _, name in ipairs({ "RunState", "RunEndsAt", "FeedMode" }) do
		Obby:SetAttribute(name, nil)
	end
	s.map:Destroy()
	s.runtime:Destroy()
	log("stopped")
end

return Mode
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.RunControl", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.RunControl (ModuleScript)
-- RunControl -- who owns the crates right now, which bay is live, and the ROUND every other module
-- belongs to.
--
-- Two scripts need to agree on this and neither should depend on the other: HazardManager owns
-- bay rebuilding, DebugMenu drives it, and BridgeFeed and DebugMode each need to know whether
-- they are the live crate source this minute. A tiny shared module is the seam -- HazardManager
-- fills in the rebuild hooks on startup, everyone else calls them.
--
-- THE ROUND (arcade mode, docs/obby-mode-plan.md). ServerStorage.Modes.Obby.Module clones the whole
-- Server folder fresh for every round and requires the clones, so every module here -- this one
-- included -- starts with fresh state and fresh BindableEvents; a listener left over from the last
-- round hangs on an event nothing fires any more. Module sets RunControl.session BEFORE requiring
-- anything else, and the other modules read it at require time:
--
--   session.map          Workspace.ObbyMap (the clone of Modes.Obby.Map)
--   session.warehouse    session.map.Warehouse (Bay01..Bay04, Shell, SkyRails, ...)
--   session.runners      the players in this round who are still running (an array, kept current)
--   session.debug        Config.ArcadeDebug, or the ArcadeDebug attribute on Modes.Obby
--   session.alive        false once Stop has begun: every loop that is not `while folder.Parent`
--                        checks it
--   session.track(conn)  -> conn; disconnected by Stop. Use it for EVERY connection to a signal that
--                        outlives the round: RunService.*, Players.*, a Player or Character signal,
--                        and OnServerEvent on ReplicatedStorage.Obby.Remotes
--   session.spawn(fn, ...) -> thread; task.spawn that Stop cancels if it is still running
--   session.isRunner(player), session.robots() (players whose Role is "robot")
--
-- FEED MODES. Exactly one source may own the crates, which is the whole reason this exists:
--
--   "solo"  one player doing both jobs: the on-screen 4x3 grid places blocks and the Sky Arm
--           carries them in, so you are the operator as well as the runner.
--   "live"  the real SO-101 through the core's robot link. Nothing else may place a block.
--
-- In the arcade Module sets the mode once at Start (live when the core link is up, else solo). The
-- debug menu can still flip it mid-round (Config.ArcadeDebug), which RESETS THE WORLD -- every bay
-- rebuilt, every crate cleared, because the two modes disagree about who owns the crates.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))

local RunControl = {}

RunControl.MODES = {"solo", "live"}

RunControl.feedMode = (Config.FeedMode == "live") and "live" or "solo"

-- The round. Set by Module before any other Server module is required; nil only between rounds.
RunControl.session = nil

function RunControl.warehouse()
	local s = RunControl.session
	return s and s.warehouse
end

local feedChanged = Instance.new("BindableEvent")
RunControl.FeedModeChanged = feedChanged.Event

-- WHICH BAY THE MAT MAPS TO. One physical 4x3 grid serves every bay, so every crate source
-- has to agree on which one is live right now -- and so does Mapping, whose ORIGIN is derived
-- from that bay's Cell_0_0 anchor. ActiveBayTracker drives it from the runner's position.
RunControl.activeBay = Config.LiveBay or 1

local bayChanged = Instance.new("BindableEvent")
RunControl.ActiveBayChanged = bayChanged.Event

function RunControl.bayModel(i)
	local warehouse = RunControl.warehouse()
	return warehouse and warehouse:FindFirstChild(("Bay%02d"):format(i))
end

function RunControl.activeBayModel()
	return RunControl.bayModel(RunControl.activeBay)
end

function RunControl.setActiveBay(i)
	i = math.clamp(math.floor(tonumber(i) or 1), 1, Config.NumBays)
	local previous = RunControl.activeBay
	RunControl.activeBay = i
	local bay = RunControl.activeBayModel()
	if bay then
		require(script.Parent:WaitForChild("Mapping")).setActiveBay(bay)
	end
	if i ~= previous then
		bayChanged:Fire(i, previous)
	end
	return i
end

----------------------------------------------------------------
-- World positions. The course was built with bay 1 at Z = 0; the arcade bakes it Config.OriginZ
-- down +Z, and X is untouched. Everything that turns a bay index into a Z goes through here.
----------------------------------------------------------------
function RunControl.bayZStart(i)
	return Config.OriginZ + (i - 1) * Config.BayPitch
end

-- Course Z (bay 1's entrance = 0) of a world position.
function RunControl.courseZ(worldZ)
	return worldZ - Config.OriginZ
end

-- FACING MATTERS. An identity-rotated CFrame looks along -Z and the course runs toward +Z, so
-- every placement is built looking down the course explicitly.
local function lookDownCourse(pos)
	return CFrame.lookAt(pos, pos + Vector3.new(0, 0, 1))
end

-- Just outside bay i's entrance, centred, so the player walks in through the doorway.
function RunControl.approachCFrame(i)
	return lookDownCourse(Vector3.new(Config.BayWidth / 2, 4, RunControl.bayZStart(i) - 4))
end

-- The course start: the map's Start part (the obby's old SpawnLocation, made a plain part so the
-- arcade never spawns anyone into the obby). Never a SpawnLocation lookup: in the arcade that finds
-- the Workshop's.
function RunControl.startCFrame()
	local s = RunControl.session
	local start = s and s.map and s.map:FindFirstChild("Start")
	if start and start:IsA("BasePart") then
		return lookDownCourse(start.Position + Vector3.new(0, start.Size.Y / 2 + 3.5, 0))
	end
	return lookDownCourse(Vector3.new(Config.BayWidth / 2, 4, Config.OriginZ - (Config.EntranceBuffer or 10) + 4))
end

-- Puts a character at cf, still. Turning the BODY does not turn the CAMERA (the default camera owns
-- its yaw on the client), so the client's CameraPolish is told which way to look.
function RunControl.placeCharacter(player, cf)
	local character = player and player.Character
	local hrp = character and character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return false
	end
	character:PivotTo(cf)
	hrp.AssemblyLinearVelocity = Vector3.zero
	-- When, so Module's respawn checkpoint can tell that something else (a debug command) already put
	-- this new character somewhere and leave it there.
	local s = RunControl.session
	if s and s.placedAt then
		s.placedAt[player] = os.clock()
	end
	local remotes = ReplicatedStorage.Obby:FindFirstChild("Remotes")
	local cameraFace = remotes and remotes:FindFirstChild("CameraFace")
	if cameraFace then
		cameraFace:FireClient(player, cf.LookVector)
	end
	return true
end

-- Filled in by HazardManager once it has built the bays. Nothing else may assign these.
RunControl.rebuildBay = nil      -- (bayIndex) -> state; full teardown and rebuild
RunControl.bayState = nil        -- (bayIndex) -> state, for reading `solved`

local readyEvent = Instance.new("BindableEvent")
RunControl.Ready = readyEvent.Event
RunControl.isReady = false

function RunControl.markReady()
	RunControl.isReady = true
	readyEvent:Fire()
end

-- Block until HazardManager has published its hooks. Script execution order is not guaranteed,
-- and a debug menu that silently does nothing because it loaded first is a miserable thing to
-- diagnose.
function RunControl.waitForReady(timeout)
	local deadline = os.clock() + (timeout or 10)
	while not RunControl.isReady and os.clock() < deadline do
		task.wait(0.05)
	end
	return RunControl.isReady
end

function RunControl.isValidMode(mode)
	for _, m in ipairs(RunControl.MODES) do
		if m == mode then
			return true
		end
	end
	return false
end

function RunControl.setFeedMode(mode)
	if not RunControl.isValidMode(mode) or mode == RunControl.feedMode then
		return RunControl.feedMode
	end
	local previous = RunControl.feedMode
	RunControl.feedMode = mode
	ReplicatedStorage.Obby:SetAttribute("FeedMode", mode)
	print(("[RunControl] crate source: %s -> %s"):format(previous, mode))
	feedChanged:Fire(mode, previous)
	return mode
end

-- Is a real second player driving the arm, as opposed to me clicking a grid?
function RunControl.hasOverseer()
	return RunControl.feedMode == "live"
end

-- Set by HazardManager alongside rebuildBay; used to wipe the world on a mode change.
RunControl.rebuildAll = nil

-- Fired with the bay index after a bay has been rebuilt and its crates cleared.
--
-- Anything holding its own idea of what is in that bay has to drop it here. DebugMode keeps
-- per-bay cell state, and BlockSync.clearBay resets the diff baseline -- so a cell the editor
-- still believes in would be re-delivered on the very next edit, and a crate nobody placed in
-- this run would walk back into a freshly reset bay.
local bayReset = Instance.new("BindableEvent")
RunControl.BayReset = bayReset.Event

function RunControl.notifyBayReset(i)
	bayReset:Fire(i)
end

return RunControl
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.BlockSync", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.BlockSync (ModuleScript)
-- BlockSync (Section 7, 10.2 steps 1, 3 & 8) -- nothing else hard-codes world positions;
-- cellToWorld reads the Cell_c_r anchor parts baked into each bay prefab.
--
-- TWO INPUT PATHS, never both at once:
--
--   applyCells(bay, cells)   the solo/DebugMode path. Diffs `cells` snapshots and hands crate
--                            delivery to SkyArm, which animates a reach into the cell.
--   applyBlocks(bay, blocks) the LIVE path (robot-link.md). One crate per real cube, tracked
--                            by block id and positioned every frame. No delivery animation:
--                            player 2's real carry motion already is one.
--
-- Both end at the same cellsChangedEvent, so HazardManager cannot tell them apart and the
-- placement guards work for either.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local Debris = game:GetService("Debris")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local Mapping = require(script.Parent:WaitForChild("Mapping"))
local RunControl = require(script.Parent:WaitForChild("RunControl"))
local SkyArm = require(script.Parent:WaitForChild("SkyArm"))

local BlockSync = {}

-- Fired after every applied snapshot with (bayModel, cellsList). HazardManager listens to this
-- to decide whether a bay's obstacle has been solved. One-directional: HazardManager depends
-- on BlockSync, never the other way round.
local cellsChangedEvent = Instance.new("BindableEvent")
BlockSync.CellsChanged = cellsChangedEvent.Event

-- Fired when a crate has physically SEATED in its cell. Deliberately distinct from
-- CellsChanged, which fires as soon as the snapshot changes -- at that point the arm still has
-- ~5s of carry to do, and the crate may not arrive at all, because a placement guard can
-- refuse it. Anything whose timing or safety depends on the crate actually BEING there has to
-- listen to this one: bay 3 starts its cooldown from it, and treating the snapshot as arrival
-- there marked a refused cell safe to stand on.
local cratePlacedEvent = Instance.new("BindableEvent")
BlockSync.CratePlaced = cratePlacedEvent.Event

local COLOR_RGB = {
	red = Color3.fromRGB(210, 50, 50),
	blue = Color3.fromRGB(60, 150, 220),
	yellow = Color3.fromRGB(225, 200, 50),
	green = Color3.fromRGB(70, 190, 90),
	orange = Color3.fromRGB(230, 130, 30),
	purple = Color3.fromRGB(150, 80, 200),
	teal = Color3.fromRGB(50, 190, 180),
}

-- How far a bay sinks its crates below the floor plane.
--
-- Normally a crate rests ON the floor: you climb it, and its top is a cube above where you
-- walk. In a bay where the crates ARE the floor -- the void -- that is wrong: the bridge ends
-- up a cube proud of the walkway, so crossing means hopping up onto every slab and back down.
-- Such a bay sets CrateSink on its model and the crates drop to sit flush.
local function sinkFor(bayModel)
	return tonumber(bayModel and bayModel:GetAttribute("CrateSink")) or 0
end

function BlockSync.cellToWorld(bayModel, col, row)
	local anchorsFolder = bayModel:FindFirstChild("CrateAnchors")
	if not anchorsFolder then
		error(string.format("BlockSync.cellToWorld: %s has no CrateAnchors folder", bayModel:GetFullName()))
	end

	local anchorName = string.format("Cell_%d_%d", col, row)
	local anchor = anchorsFolder:FindFirstChild(anchorName)
	if not anchor then
		error(string.format("BlockSync.cellToWorld: missing anchor %s under %s", anchorName, bayModel:GetFullName()))
	end

	return anchor.CFrame * CFrame.new(0, -sinkFor(bayModel), 0)
end

----------------------------------------------------------------
-- Crate spawning / removal (Section 3.2, 5.2)
----------------------------------------------------------------
local lastAppliedByBay = setmetatable({}, {__mode = "k"})
local liveCratesByBay = setmetatable({}, {__mode = "k"})

local function keyFor(c)
	return c.col .. "," .. c.row
end

local function spawnShockwave(bayModel, worldCFrame, level, color)
	local ring = Instance.new("Part")
	ring.Name = "Shockwave"
	ring.Shape = Enum.PartType.Cylinder
	ring.Anchored = true
	ring.CanCollide = false
	ring.CanQuery = false
	ring.Material = Enum.Material.Neon
	ring.Color = COLOR_RGB[color] or Color3.fromRGB(255, 255, 255)
	ring.Transparency = 0.2
	ring.Size = Vector3.new(0.2, 1, 1)
	ring.CFrame = worldCFrame * CFrame.Angles(0, 0, math.rad(90))
	ring.Parent = bayModel

	local targetRadius = (level == 2) and 18 or 8
	local tween = TweenService:Create(ring, TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		Size = Vector3.new(0.2, targetRadius, targetRadius),
		Transparency = 1,
	})
	tween:Play()
	Debris:AddItem(ring, 0.5)
end

-- ONE crate size for both paths.
--
-- This built a 4 stud Base with a 3 stud Topper, from when a crate was a prop rather than a
-- cube. The live path builds real 6.72 stud cubes (Mapping.cubeStuds, from the 48 mm cube at
-- the mat-to-bay scale), and bay 1's lever gate is tuned to those heights -- so solo play had
-- crates topping out at 4.00 and 7.00 against a gate wanting 6.72 and 13.44. Lever A squeaked
-- through on tolerance and **Lever B could never be thrown at all**: the bay was unsolvable
-- unless the real robot was driving it.
--
-- A level-2 crate is now two identical cubes, which is what the real table has.
local function buildCrateModel(color, level)
	local w = Mapping.cubeStuds()
	local model = Instance.new("Model")
	model.Name = "Crate"

	local base = Instance.new("Part")
	base.Name = "Base"
	base.Anchored = true
	base.CanCollide = true
	base.Material = Enum.Material.CorrodedMetal
	base.Color = COLOR_RGB[color] or Color3.fromRGB(200, 200, 200)
	base.Size = Vector3.new(w, w, w)
	base.Parent = model
	base:SetAttribute("IsCrate", true)
	model.PrimaryPart = base

	local stripe = Instance.new("Part")
	stripe.Name = "Stripe"
	stripe.Anchored = true
	stripe.CanCollide = false
	stripe.CanQuery = false
	stripe.Material = Enum.Material.Neon
	stripe.Color = COLOR_RGB[color] or Color3.fromRGB(255, 255, 255)
	stripe.Size = Vector3.new(w * 1.01, w * 0.09, w * 1.01)
	stripe.Parent = model

	local gui = Instance.new("SurfaceGui")
	gui.Face = Enum.NormalId.Front
	gui.LightInfluence = 0
	gui.Parent = base
	local label = Instance.new("TextLabel")
	label.Size = UDim2.new(1, 0, 1, 0)
	label.BackgroundTransparency = 1
	label.Text = color:upper()
	label.TextColor3 = Color3.fromRGB(255, 255, 255)
	label.Font = Enum.Font.SourceSansBold
	label.TextScaled = true
	label.Parent = gui

	if level == 2 then
		local topper = Instance.new("Part")
		topper.Name = "Topper"
		topper.Anchored = true
		topper.CanCollide = true
		topper.Material = Enum.Material.CorrodedMetal
		topper.Color = COLOR_RGB[color] or Color3.fromRGB(200, 200, 200)
		-- the same cube again, not a smaller cap: two cubes stacked is what level 2 means
		topper.Size = Vector3.new(w, w, w)
		topper.Parent = model
		topper:SetAttribute("IsCrate", true)

		local topperStripe = stripe:Clone()
		topperStripe.Name = "TopperStripe"
		topperStripe.Size = Vector3.new(w * 1.01, w * 0.08, w * 1.01)
		topperStripe.Parent = model
	end

	return model
end

local function positionCrate(crateModel, worldCFrame, level)
	-- A rapid colour/level change destroys the old crate while an arm job may still hold a
	-- reference to it, so every late callback has to tolerate a dead model.
	local base = crateModel and crateModel.Parent and crateModel:FindFirstChild("Base")
	if not base then
		return
	end
	base.CFrame = worldCFrame * CFrame.new(0, base.Size.Y / 2, 0)
	local stripe = crateModel:FindFirstChild("Stripe")
	if stripe then
		stripe.CFrame = base.CFrame * CFrame.new(0, base.Size.Y / 2 + 0.05, 0)
	end

	if level == 2 then
		local topper = crateModel:FindFirstChild("Topper")
		if topper then
			topper.CFrame = base.CFrame * CFrame.new(0, base.Size.Y / 2 + topper.Size.Y / 2, 0)
			local topperStripe = crateModel:FindFirstChild("TopperStripe")
			if topperStripe then
				topperStripe.CFrame = topper.CFrame * CFrame.new(0, topper.Size.Y / 2 + 0.05, 0)
			end
		end
	end
end

----------------------------------------------------------------
-- Placement guards
--
-- An obstacle can refuse deliveries into its own bay -- the saw wall turns away crates dropped
-- in front of live blades, because stalling the wall is meant to be a reward for killing them
-- first. HazardManager registers the guard, so the dependency still only points one way.
--
-- A refusal is not a discard: the operator's cube is still sitting on the real table, so the
-- game owes them that crate the moment the guard changes its mind. Rejects are parked per bay
-- and retryRejected() delivers them.
----------------------------------------------------------------
local placementGuards = setmetatable({}, {__mode = "k"})
local rejectedByBay = setmetatable({}, {__mode = "k"})

local rejectedEvent = Instance.new("BindableEvent")
BlockSync.PlacementRejected = rejectedEvent.Event

function BlockSync.setPlacementGuard(bayModel, fn)
	placementGuards[bayModel] = fn
end

local function allowed(bayModel, cell)
	local guard = placementGuards[bayModel]
	if not guard then
		return true
	end
	return guard(cell)
end

local function liveTableFor(bayModel)
	local live = liveCratesByBay[bayModel]
	if not live then
		live = {}
		liveCratesByBay[bayModel] = live
	end
	return live
end

-- VIRTUAL CRATES. In some bays the cube is a TOKEN, not an object.
--
-- The laser walk is the case: the operator moves a real cube across the real mat and what
-- that does in here is disarm the matching tile. The player walks on the floor -- the pad is
-- the authoritative killer, and a safe pad does not kill -- so a crate standing in the cell
-- was never load-bearing. It was scenery, and scenery that reads as "climb me" in a bay where
-- climbing is not the point.
--
-- The cell bookkeeping is unchanged: CellsChanged and CratePlaced still fire, so solve
-- detection and the cooldown that lets you walk to the next tile work exactly as before.
local function deliver(bayModel, live, key, cell)
	local worldCFrame = BlockSync.cellToWorld(bayModel, cell.col, cell.row)

	if bayModel:GetAttribute("VirtualCrates") then
		live[key] = nil
		spawnShockwave(bayModel, worldCFrame, cell.level, cell.color)
		-- no arm trip and no model: nothing is carried in, the tile just goes quiet
		task.defer(function()
			cratePlacedEvent:Fire(bayModel, cell)
		end)
		return
	end

	local crateModel = buildCrateModel(cell.color, cell.level)
	live[key] = crateModel
	SkyArm.reachAndPlace(bayModel, worldCFrame, crateModel, cell.level, function()
		if not crateModel.Parent then
			return -- superseded by a newer edit while the arm was in flight
		end
		positionCrate(crateModel, worldCFrame, cell.level)
		spawnShockwave(bayModel, worldCFrame, cell.level, cell.color)
		cratePlacedEvent:Fire(bayModel, cell)
	end)
end

-- Re-offer everything a guard turned away earlier, for whichever cells it now accepts.
function BlockSync.retryRejected(bayModel)
	local rej = rejectedByBay[bayModel]
	if not rej then
		return
	end
	local live = liveTableFor(bayModel)
	for key, cell in pairs(rej) do
		if allowed(bayModel, cell) then
			rej[key] = nil
			deliver(bayModel, live, key, cell)
		end
	end
end

----------------------------------------------------------------
-- Public: diff + apply a new `cells` snapshot for a given bay (Section 5.2)
----------------------------------------------------------------
function BlockSync.applyCells(bayModel, newCellsList)
	local last = lastAppliedByBay[bayModel] or {}
	local live = liveTableFor(bayModel)

	local newByKey = {}
	for _, c in ipairs(newCellsList) do
		newByKey[keyFor(c)] = c
	end

	-- Removed cells: wait 0.4s, then have the arm lift the crate out (Section 5.2.3)
	for key, oldCell in pairs(last) do
		if not newByKey[key] then
			local crateModel = live[key]
			live[key] = nil
			-- lifting the cube off the table voids any rejection parked for that cell
			local rej = rejectedByBay[bayModel]
			if rej then
				rej[key] = nil
			end
			task.delay(Config.CrateRemoveDelay, function()
				-- the round may have ended (and the map gone) inside the delay
				if crateModel and crateModel.Parent and bayModel.Parent then
					local worldCFrame = BlockSync.cellToWorld(bayModel, oldCell.col, oldCell.row)
					SkyArm.reachAndRemove(bayModel, worldCFrame, crateModel)
				end
			end)
		end
	end

	-- Added / changed cells: wait 0.2s, then have the arm deliver (or swap) the crate (Section 5.2.2, 5.2.4)
	for key, newCell in pairs(newByKey) do
		local oldCell = last[key]
		local isNew = not oldCell
		local isChanged = oldCell and (oldCell.level ~= newCell.level or oldCell.color ~= newCell.color)
		if isNew or isChanged then
			task.delay(Config.CrateConfirmDelay, function()
				if not bayModel.Parent then
					return -- the round ended inside the delay; the bay is gone
				end
				local existing = live[key]
				if existing then
					-- A crate still waiting its turn in the arm queue has no Parent yet, so
					-- `.Parent` cannot tell "not placed yet" from "already destroyed" -- and
					-- the old check skipped exactly the queued ones, so fast colour cycling
					-- left several crates stacked in one cell. Flag it instead and let
					-- whichever side reaches it first do the cleanup.
					existing:SetAttribute("Superseded", true)
					if existing.Parent then
						existing:Destroy()
					end
				end

				local ok, reason = allowed(bayModel, newCell)
				if not ok then
					-- park it; the cube is still on the real table, so this is deferred
					local rej = rejectedByBay[bayModel]
					if not rej then
						rej = {}
						rejectedByBay[bayModel] = rej
					end
					rej[key] = newCell
					live[key] = nil
					rejectedEvent:Fire(bayModel, newCell, reason)
					return
				end

				deliver(bayModel, live, key, newCell)
			end)
		end
	end

	lastAppliedByBay[bayModel] = newByKey
	cellsChangedEvent:Fire(bayModel, newCellsList)
end

----------------------------------------------------------------
-- The live path: one crate per real cube (robot-link.md)
--
-- The wire carries `blocks`, not `cells`: one entry per physical cube, with a stable id, a
-- stack `level` that is 0 on the paper, and `held` while it is in the jaw. Cells are a derived
-- view, computed here so HazardManager's solve logic is untouched.
--
-- Nothing here animates a delivery. The obby's SkyArm exists to *simulate* an operator; there
-- is a real one now, and re-enacting a reach they already made with their hands is the one
-- thing that must never happen. The carry animation comes free instead: a held cube follows
-- the jaw, so the operator's real motion is the crate's flight path.
----------------------------------------------------------------

-- The perception palette has nine names against the obby's seven, and identity comes from
-- `id`, not colour -- PROTOCOL.md is explicit that a wrong colour is cosmetic. Collapse the
-- two strays onto their nearest obby colour rather than dropping the cube: a crate of the
-- wrong colour is still footing, which is what Bay 1 actually needs.
local COLOR_ALIAS = {
	["light blue"] = "blue",   -- hue 250 vs blue's 268; the kit's own near-miss
	pink = "red",
	grey = "grey",             -- what a held cube reports; see PROTOCOL.md
}

local GREY = Color3.fromRGB(154, 164, 178)
local LOST_TRANSPARENCY = 0.6     -- the camera cannot see this cube right now

local function obbyColor(name)
	name = tostring(name or "grey")
	return COLOR_ALIAS[name] or name
end

-- One cube, as one welded assembly so a constraint can carry it with a player aboard.
--
-- Named Base because HazardManager's reach gating raycasts for a part called Base or Topper;
-- it also carries an IsCrate attribute so that check can stop depending on names. Every live
-- cube is identical, so there is no Topper here -- a stack is two cubes, which is what the
-- real table has, and lifting the top one drops the stack to L1 with no special case.
-- Where the live cubes' Goal attachments live. They used to sit in workspace.Terrain, which is
-- world-anchored but outside the round: in the arcade nothing may outlive the map, so they hang
-- off one anchored, invisible part inside it instead, and go with it when the round ends.
local goalHolder = nil

local function goalParent()
	if goalHolder and goalHolder.Parent then
		return goalHolder
	end
	goalHolder = Instance.new("Part")
	goalHolder.Name = "CrateGoals"
	goalHolder.Anchored = true
	goalHolder.CanCollide = false
	goalHolder.CanQuery = false
	goalHolder.CanTouch = false
	goalHolder.Transparency = 1
	goalHolder.Size = Vector3.new(1, 1, 1)
	goalHolder.CFrame = CFrame.new()
	goalHolder.Parent = RunControl.session.map
	return goalHolder
end

local function buildCube(colorName)
	local w = Mapping.cubeStuds()
	local model = Instance.new("Model")
	model.Name = "Crate"

	local base = Instance.new("Part")
	base.Name = "Base"
	base.Anchored = true
	base.CanCollide = true
	base.Material = Enum.Material.CorrodedMetal
	base.Color = COLOR_RGB[obbyColor(colorName)] or GREY
	base.Size = Vector3.new(w, w, w)
	base.CustomPhysicalProperties = PhysicalProperties.new(0.7, 1.0, 0, 100, 100) -- grippy underfoot
	base.Parent = model
	base:SetAttribute("IsCrate", true)
	model.PrimaryPart = base

	-- The stripe must NOT be anchored in its own right. A WeldConstraint makes these two parts
	-- one assembly, and an assembly containing any anchored part has infinite mass -- so
	-- unanchoring the base for a carry still left the cube immovable and AlignPosition drove it
	-- nowhere, with the goal sitting correctly at the jaw the whole time. Anchoring the base
	-- alone is what holds the pair still while it rests.
	local stripe = Instance.new("Part")
	stripe.Name = "Stripe"
	stripe.Anchored = false
	stripe.CanCollide = false
	stripe.CanQuery = false
	stripe.Massless = true           -- decoration; it must not change how the cube carries
	stripe.Material = Enum.Material.Neon
	stripe.Color = base.Color
	stripe.Size = Vector3.new(w * 1.01, w * 0.09, w * 1.01)
	stripe.CFrame = base.CFrame      -- a band round the cube's equator; set before the weld,
	stripe.Parent = model            -- because the weld freezes whatever offset it finds

	local weld = Instance.new("WeldConstraint")
	weld.Part0 = base
	weld.Part1 = stripe
	weld.Parent = base

	local att = Instance.new("Attachment")
	att.Name = "Drive"
	att.Parent = base

	local goal = Instance.new("Attachment")
	goal.Name = "Goal"
	goal.Parent = goalParent()           -- world-anchored, so there is something to drive toward

	-- AlignPosition.MaxForce defaults to 10000. A 6.7 stud cube at density 0.7 weighs far more
	-- than that under default gravity, and an under-powered constraint cannot hold the part up
	-- at all: it sags, and a carried one sinks through the world until the engine destroys it
	-- at FallenPartsDestroyHeight, losing the cube for the session. The rider speed cap lives
	-- in MaxVelocity, where it belongs, so raising these costs nothing in safety.
	local pos = Instance.new("AlignPosition")
	pos.Attachment0, pos.Attachment1 = att, goal
	pos.MaxForce, pos.MaxVelocity, pos.Responsiveness = 1e8, 60, 40
	pos.ApplyAtCenterOfMass = true
	pos.Parent = base

	local rot = Instance.new("AlignOrientation")
	rot.Attachment0, rot.Attachment1 = att, goal
	rot.MaxTorque, rot.Responsiveness = 1e8, 40
	rot.Parent = base

	return {model = model, base = base, stripe = stripe, goal = goal}
end

local liveBlocksByBay = setmetatable({}, {__mode = "k"})
local refusedByBay = setmetatable({}, {__mode = "k"})
local lastLiveSignature = setmetatable({}, {__mode = "k"})
-- held-last flags for virtual bays, which have no cube entry to hang them on
local entryHeldLast = {}

local function destroyCube(entry)
	entry.goal:Destroy()
	entry.model:Destroy()
end

-- Group cubes into the one-colour-per-cell view the solve logic wants. A cell's colour is the
-- BOTTOM cube's: the obby's model is one colour per cell and the wire's is one entry per cube,
-- so a mixed-colour stack is simply not representable. Level is the tallest cube in the cell,
-- +1 because the wire counts from 0 and the obby counts from 1, clamped at 2 because the real
-- table only has two cubes of a colour and three-high does not exist.
local function cellsFromBlocks(placed)
	local byCell = {}
	for _, p in ipairs(placed) do
		local key = p.col .. "," .. p.row
		local cell = byCell[key]
		if not cell then
			byCell[key] = {col = p.col, row = p.row, color = p.color, level = p.level + 1,
				bottom = p.level}
		else
			if p.level < cell.bottom then
				cell.bottom, cell.color = p.level, p.color
			end
			cell.level = math.max(cell.level, p.level + 1)
		end
	end
	local list = {}
	for _, cell in pairs(byCell) do
		cell.level = math.min(cell.level, 2)
		cell.bottom = nil
		table.insert(list, cell)
	end
	table.sort(list, function(a, b)
		if a.col == b.col then return a.row < b.row end
		return a.col < b.col
	end)
	return list
end

-- Wipe every crate out of a bay and forget all per-bay bookkeeping, so the next snapshot from
-- either path starts from nothing. This is what "fresh state" means for crates: without it a
-- rebuilt bay keeps the crates of the run before it, and the diff state still believes they
-- are there, so re-placing the same cube is a no-op and the bay looks broken.
function BlockSync.clearBay(bayModel)
	local live = liveBlocksByBay[bayModel]
	if live then
		for id, entry in pairs(live) do
			destroyCube(entry)
			live[id] = nil
		end
	end
	local crates = liveCratesByBay[bayModel]
	if crates then
		for key, model in pairs(crates) do
			if model and model.Parent then
				model:Destroy()
			end
			crates[key] = nil
		end
	end
	-- Anything the arm is still carrying belongs to the run that just ended.
	for _, child in ipairs(bayModel:GetChildren()) do
		if child:IsA("Model") and child.Name == "Crate" then
			child:Destroy()
		end
	end
	lastAppliedByBay[bayModel] = nil
	lastLiveSignature[bayModel] = nil
	rejectedByBay[bayModel] = nil
	refusedByBay[bayModel] = nil
	cellsChangedEvent:Fire(bayModel, {})
end

-- Apply one `blocks` frame to a bay. Safe to call at the wire's 30 Hz: everything is a
-- position update after the first frame.
function BlockSync.applyBlocks(bayModel, blocks)
	if type(blocks) ~= "table" then
		return
	end
	local live = liveBlocksByBay[bayModel]
	if not live then
		live = {}
		liveBlocksByBay[bayModel] = live
	end
	local refused = refusedByBay[bayModel]
	if not refused then
		refused = {}
		refusedByBay[bayModel] = refused
	end

	local w = Mapping.cubeStuds()
	local seen, placed = {}, {}

	for _, b in ipairs(blocks) do
		local col, row = Mapping.cellOf(b.x, b.y)
		local level = b.level or 0

		-- A cube in the tray, or on the bare mat, is not in the bay. A held one is, wherever
		-- the jaw has got to.
		local wanted = b.held or (col ~= nil)

		-- Guards refuse a *placement*, never a carry: the saw wall turns away a crate dropped
		-- in front of live blades, but the operator may still fly one over. Re-checked every
		-- frame, so a parked cube materialises the instant the guard relents -- the live path
		-- needs no retryRejected, it self-heals at 30 Hz.
		local refusalReason = nil
		if wanted and not b.held then
			local ok, reason = allowed(bayModel, {col = col, row = row,
				color = obbyColor(b.color), level = math.min(level + 1, 2)})
			if not ok then
				wanted, refusalReason = false, reason
			end
		end

		-- Edge-triggered, or the HUD would flash the refusal 30 times a second.
		if refusalReason and not refused[b.id] then
			rejectedEvent:Fire(bayModel, {col = col, row = row,
				color = obbyColor(b.color), level = level + 1}, refusalReason)
		end
		refused[b.id] = refusalReason ~= nil or nil

		if not wanted then
			if live[b.id] then
				destroyCube(live[b.id])
				live[b.id] = nil
			end
		else
			-- A virtual-crate bay tracks the cell but never builds the cube (see deliver).
			if bayModel:GetAttribute("VirtualCrates") then
				if live[b.id] then
					destroyCube(live[b.id])
					live[b.id] = nil
				end
				seen[b.id] = true
				if not b.held then
					table.insert(placed, {col = col, row = row,
						color = obbyColor(b.color), level = level})
					if entryHeldLast[b.id] then
						cratePlacedEvent:Fire(bayModel, {col = col, row = row,
							color = obbyColor(b.color), level = math.min(level + 1, 2)})
					end
				end
				entryHeldLast[b.id] = b.held and true or nil
				continue
			end

			seen[b.id] = true
			local entry, fresh = live[b.id], false
			-- Rebuild a cube whose part has left the tree, or one lost cube is permanent:
			-- `seen` keeps the cleanup below from clearing it and it is never recreated.
			if entry == nil or entry.base.Parent == nil then
				if entry then
					destroyCube(entry)
				end
				entry = buildCube(b.color)
				entry.model.Parent = bayModel
				live[b.id] = entry
				fresh = true
			end

			local target
			if b.held then
				-- The real carry height is the whole point, so use the measured pose.
				target = CFrame.new(Mapping.blockPosition(b)) * Mapping.blockOrientation(b)
			else
				-- Resting cubes come off the BAKED anchor, not a scaled millimetre position:
				-- the anchors are the single source of truth for where a cell is, and the
				-- robot has already snapped the cube to its cell centre.
				target = BlockSync.cellToWorld(bayModel, col, row)
					* CFrame.new(0, level * w + w / 2, 0)
			end
			entry.goal.WorldCFrame = target     -- world space, whatever the holder part does
			if fresh then
				-- A cube built mid-carry would otherwise start at the origin and be hauled
				-- across the map by the constraint. Place it where it already is first.
				entry.base.CFrame = target
			end

			-- Anchored while resting, unanchored while carried.
			--
			-- A resting cube should be exactly where the robot says it is, full stop. Left
			-- unanchored, two stacked cubes are two constraint-driven rigid bodies pressing on
			-- each other and the smallest overlap topples the top one -- a stack that is
			-- perfectly stable on the real table falls over here.
			--
			-- A carried cube is why the part is unanchored at all: an anchored part moved by
			-- CFrame does not carry a player standing on it, and being carried IS the lift.
			-- The goal is kept in sync either way, so the hand-off never jumps.
			-- A cube that was being carried and is now resting has just SEATED. Bay 3 starts
			-- its safe-cell cooldown from this, so the live path has to fire it too -- the
			-- applyCells path fires it from deliver(), and without this a bay timing off
			-- CratePlaced would simply never tick once the real arm is the source.
			local wasHeld = entry.heldLast
			entry.heldLast = b.held and true or nil

			if b.held then
				if entry.base.Anchored then
					-- Start the carry from where the cube already is, so the constraint eases
					-- it off the table instead of dragging it across the map from wherever the
					-- part happened to be built.
					entry.base.Anchored = false
					-- The server must own a carried cube or the rider's own client fights the
					-- server over where it is. Errors on an anchored part, hence the ordering.
					pcall(function()
						entry.base:SetNetworkOwner(nil)
					end)
				end
			else
				entry.base.Anchored = true
				entry.base.CFrame = target
			end

			-- A held cube stays solid: riding it is the whole feature, and the speed cap in
			-- MaxVelocity is what keeps the rider safe, not loss of collision.
			entry.base.CanCollide = true
			entry.base.Transparency = (b.visible or b.held) and 0 or LOST_TRANSPARENCY
			entry.stripe.Transparency = entry.base.Transparency

			-- Colour is refreshed every frame, not just at create: a cube reports grey while in
			-- the jaw and its own colour again on release, so a part coloured once would keep
			-- whatever it was when it first appeared.
			local c = COLOR_RGB[obbyColor(b.color)] or GREY
			entry.base.Color, entry.stripe.Color = c, c

			if not b.held then
				table.insert(placed, {col = col, row = row,
					color = obbyColor(b.color), level = level})
				if wasHeld then
					cratePlacedEvent:Fire(bayModel, {col = col, row = row,
						color = obbyColor(b.color), level = math.min(level + 1, 2)})
				end
			end
		end
	end

	-- A cube taken off the table stops being a crate. The tracker only drops an id after it has
	-- been gone for seconds, so this is never a dropped camera frame.
	for id, entry in pairs(live) do
		if not seen[id] then
			destroyCube(entry)
			live[id] = nil
			refused[id] = nil
		end
	end

	local cells = cellsFromBlocks(placed)

	-- Positions update at the wire's 30 Hz, but the *cell* view changes only when a cube is
	-- set down or lifted. Firing every frame would re-run every bay's solve check thirty times
	-- a second and strobe the labels HazardManager drives off it, so fire on change only.
	local sig = {}
	for _, c in ipairs(cells) do
		table.insert(sig, ("%d,%d,%s,%d"):format(c.col, c.row, c.color, c.level))
	end
	sig = table.concat(sig, ";")
	if sig ~= lastLiveSignature[bayModel] then
		lastLiveSignature[bayModel] = sig
		lastAppliedByBay[bayModel] = nil     -- the two paths must not share diff state
		cellsChangedEvent:Fire(bayModel, cells)
	end
	return cells
end

return BlockSync
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.SkyArm", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.SkyArm (ModuleScript)
-- SkyArm (Section 2.1, 7, 10.2 step 8 pulled forward) -- a giant SO-101-style arm hanging from
-- the ceiling gantry rails that physically carries crates into place. Idle motion and the
-- reach/grip/carry/release sequence both run through the same forward-kinematics rig, so
-- swapping the fake idle driver for the real robot feed later (Section 9) only changes where
-- target angles come from, not how the rig renders.
-- Not a true 6-DOF solver: the IK below is a simplified 2-link-planar-arm-plus-azimuth solve,
-- enough to reach convincingly into any of the 12 cells while keeping real-robot-style joint
-- names/conventions (shoulder_pan, shoulder_lift, elbow_flex, wrist_flex, wrist_roll, gripper).
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local Mapping = require(script.Parent:WaitForChild("Mapping"))
local RunControl = require(script.Parent:WaitForChild("RunControl"))

local session = RunControl.session

local SkyArm = {}

-- Proportions come from the real SO-101 teleop arm in the repo
-- (BROKER-2-so-101-teleop-arm-2.3mf, orobot.io). Real part dims, in mm:
--   Upper_arm_SO101            142.46 x 67.54 x 24.67
--   Under_arm_SO101            130.70 x 64.40 x 24.00
--   Rotation_Pitch_SO101        46.00 x 84.20 x 59.80
--   Wrist_Roll_SO101            42.85 x 52.00 x 65.20
--   Wrist_Roll_Follower_SO101  105.43 x 52.00 x 65.20
--   Moving_Jaw_SO101            49.34 x 94.57 x 20.00
--   Base_SO101                 110.92 x 72.00 x 87.00
--   Motor_holder_SO101_Base     55.08 x 38.10 x 28.00
-- The leader-only Handle_SO101/Trigger_SO101 are deliberately omitted -- the Sky Arm is the
-- follower, not the thing the operator holds.
-- Link lengths are sized to the actual working envelope, not blown up to full scale: the arm
-- only ever needs ~15.9 studs of reach (far corner cell, 14.4 across and 6.6 down), and links
-- much longer than that force a huge elbow bend that folds up through the roofline.
-- The trolley slides in X to sit above the target column, like a real gantry crane, so the arm
-- only ever spans the row offset (<= 8 studs) instead of half the bay width. That's what lets
-- these links be ~35% shorter than a fixed centre-mounted arm would need.
local L1 = 6.2    -- Upper_arm_SO101
local L2 = 5.69   -- Under_arm_SO101 (L2/L1 = 0.918, matching the real 130.70/142.46)
local MM = L1 / 142.46 -- studs per mm, derived so every other part scales off the real model

-- Wrist stack is deliberately shorter than true scale (real Wrist_Roll_Follower is 105mm);
-- at full proportion the gripper alone would eat most of the shoulder-to-floor drop.
local WRIST_LEN = 2.0 -- Wrist_Roll_SO101
local BODY_LEN = 1.9  -- Wrist_Roll_Follower_SO101 (gripper body)
local JAW_LEN = 1.9   -- Moving_Jaw_SO101

-- wrist_flex is solved to keep the wrist/gripper pointing straight down, so this much extra
-- drop always happens past the forearm tip.
local GRIP_REACH = WRIST_LEN + BODY_LEN + JAW_LEN * 0.6

-- Where the shoulder PITCH axis sits below the carriage. solveIK and applyFK must agree on
-- this or the gripper lands short.
local MOUNT_Y = 0.6
local BASE_H = 1.6
local YOKE_H = 1.7
local SHOULDER_OFFSET = MOUNT_Y + BASE_H + YOKE_H

-- Every reach aims at the crate's TOP face rather than the floor, because the gripper takes it
-- from above. Cube-derived rather than the old flat 4.2, so it follows the mat scale.
-- MIN_TARGET_Y is a hard floor so the jaw tips can never punch through the map even if a
-- caller asks for something lower.

local MIN_TARGET_Y = JAW_LEN * 0.4 + 0.3

local function gripHeight()
	return Mapping.cubeStuds() + 0.2
end

-- Trolley travel limits: it rides the two rail beams, so it stays between the outer columns.
local TROLLEY_MIN_X = Config.CellSize / 2
local TROLLEY_MAX_X = Config.BayWidth - Config.CellSize / 2

local UPPER_W, UPPER_T = 67.54 * MM, 24.67 * MM
local FORE_W, FORE_T = 64.40 * MM, 24.00 * MM

local WHITE = Color3.fromRGB(242, 242, 240) -- printed PLA
local SERVO = Color3.fromRGB(30, 30, 32)    -- Feetech STS3215 bodies

local carriageY = Config.GantryHeight

----------------------------------------------------------------
-- Build the rig once per round, INSIDE the round's map (never Workspace), so it goes when the
-- map does. Idempotent: a rig already in the map is replaced, not doubled.
----------------------------------------------------------------
local rigFolder = session.map:FindFirstChild("SkyArmRig")
if rigFolder then
	rigFolder:Destroy()
end
rigFolder = Instance.new("Folder")
rigFolder.Name = "SkyArmRig"
rigFolder.Parent = session.map

local function newPart(name, size, color, material)
	local part = Instance.new("Part")
	part.Name = name
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.Material = material or Enum.Material.SmoothPlastic
	part.Color = color or WHITE
	part.Size = size
	part.Parent = rigFolder
	return part
end

-- Gantry bridge: spans the bay between the two rail beams and carries the trolley
local bridge = newPart("Bridge", Vector3.new(Config.BayWidth, 1.2, 2), Color3.fromRGB(70, 75, 85), Enum.Material.Metal)

local carriage = newPart("Carriage", Vector3.new(4, 1.5, 3.4), Color3.fromRGB(60, 60, 68), Enum.Material.Metal)
-- over the middle of bay 1 (bayZStart adds the map's Config.OriginZ)
carriage.CFrame = CFrame.new(Config.BayWidth / 2, carriageY, RunControl.bayZStart(1) + Config.BayDepth / 2)

-- Base_SO101 + its motor holder, mounted upside down under the gantry carriage
local baseHousing = newPart("BaseHousing", Vector3.new(110.92 * MM, BASE_H, 87.00 * MM), WHITE)
local panServo = newPart("PanServo", Vector3.new(55.08 * MM, 38.10 * MM, 28.00 * MM), SERVO)

-- Rotation_Pitch_SO101: the chunky shoulder yoke that carries the pitch axis
local shoulderYoke = newPart("ShoulderYoke", Vector3.new(46.00 * MM, YOKE_H, 59.80 * MM), WHITE)
local shoulderServo = newPart("ShoulderServo", Vector3.new(55.08 * MM, 38.10 * MM, 28.00 * MM), SERVO)

-- The arm links are flat plates on the real robot, not rods: thin across the pitch axis (X),
-- tall in the swing plane (Y), long down the chain (Z).
local upperArm = newPart("UpperArm", Vector3.new(UPPER_T, UPPER_W, L1), WHITE)
local elbowServo = newPart("ElbowServo", Vector3.new(55.08 * MM, 38.10 * MM, 28.00 * MM), SERVO)
local forearm = newPart("Forearm", Vector3.new(FORE_T, FORE_W, L2), WHITE)
local wristServo = newPart("WristServo", Vector3.new(56.39 * MM, 36.90 * MM, 28.00 * MM), SERVO)

local wristRoll = newPart("WristRoll", Vector3.new(42.85 * MM, 52.00 * MM, WRIST_LEN), WHITE)
local gripperBody = newPart("GripperBody", Vector3.new(42.85 * MM, 52.00 * MM, BODY_LEN), WHITE)
local jawStatic = newPart("JawStatic", Vector3.new(20.00 * MM, 49.34 * MM, JAW_LEN), WHITE)
local jawMoving = newPart("JawMoving", Vector3.new(20.00 * MM, 49.34 * MM, JAW_LEN), WHITE)

----------------------------------------------------------------
-- Forward kinematics -- given joint angles (degrees), place every segment.
-- shoulder_pan = azimuth around Y. shoulder_lift = pitch below horizontal (0 = reach straight
-- out, 90 = straight down). elbow_flex = relative bend at the elbow (0 = forearm continues
-- straight from the upper arm). Every angle compounds through the chain like a real robot's
-- joint-local convention.
----------------------------------------------------------------
local gripperTipWorld = carriage.Position

local function applyFK(angles)
	-- the bridge rides the rails at the trolley's Z, spanning the full bay width
	bridge.CFrame = CFrame.new(Config.BayWidth / 2, carriageY + 1.35, carriage.Position.Z)

	local mountTop = carriage.CFrame * CFrame.new(0, -MOUNT_Y, 0)
	baseHousing.CFrame = mountTop * CFrame.new(0, -BASE_H / 2, 0)

	-- shoulder_pan turns the whole arm about the vertical axis
	local panPivot = mountTop * CFrame.new(0, -BASE_H, 0) * CFrame.Angles(0, math.rad(angles.shoulder_pan), 0)
	panServo.CFrame = panPivot * CFrame.new(0, 0.5, 0)
	shoulderYoke.CFrame = panPivot * CFrame.new(0, -YOKE_H / 2, 0)

	-- shoulder pitch -- this point must match solveIK's base (SHOULDER_OFFSET below the carriage)
	local upperArmJoint = panPivot * CFrame.new(0, -YOKE_H, 0)
		* CFrame.Angles(-math.rad(angles.shoulder_lift), 0, 0)
	shoulderServo.CFrame = upperArmJoint
	upperArm.CFrame = upperArmJoint * CFrame.new(0, 0, -L1 / 2)

	local elbowJoint = upperArmJoint * CFrame.new(0, 0, -L1) * CFrame.Angles(-math.rad(angles.elbow_flex), 0, 0)
	elbowServo.CFrame = elbowJoint
	forearm.CFrame = elbowJoint * CFrame.new(0, 0, -L2 / 2)

	local wristJoint = elbowJoint * CFrame.new(0, 0, -L2)
		* CFrame.Angles(-math.rad(angles.wrist_flex), 0, 0)
		* CFrame.Angles(0, 0, math.rad(angles.wrist_roll))
	wristServo.CFrame = wristJoint
	wristRoll.CFrame = wristJoint * CFrame.new(0, 0, -WRIST_LEN / 2)
	gripperBody.CFrame = wristJoint * CFrame.new(0, 0, -WRIST_LEN - BODY_LEN / 2)

	-- Parallel jaws: Moving_Jaw rides in, the fixed jaw mirrors it
	local jawRoot = wristJoint * CFrame.new(0, 0, -WRIST_LEN - BODY_LEN)
	-- Closed hugs the cube rather than clipping through it; open clears it. This was a flat
	-- 2.05, sized by hand for the old 4-stud crate -- against a real 6.72-stud cube the jaws
	-- closed INSIDE it. Derived from the cube now, so it follows the mat scale automatically.
	local half = Mapping.cubeStuds() / 2
	local openAmount = (half + 0.15) + (1 - angles.gripper / 100) * (half * 0.45)
	jawStatic.CFrame = jawRoot * CFrame.new(openAmount, 0, -JAW_LEN / 2)
	jawMoving.CFrame = jawRoot * CFrame.new(-openAmount, 0, -JAW_LEN / 2)

	gripperTipWorld = (jawRoot * CFrame.new(0, 0, -JAW_LEN * 0.6)).Position
end

----------------------------------------------------------------
-- Inverse kinematics -- simplified 2-link planar solve + azimuth, aimed at a world position.
----------------------------------------------------------------
local function solveIK(targetWorldPos)
	-- never let a caller drive the gripper through the floor
	if targetWorldPos.Y < MIN_TARGET_Y then
		targetWorldPos = Vector3.new(targetWorldPos.X, MIN_TARGET_Y, targetWorldPos.Z)
	end

	local base = (carriage.CFrame * CFrame.new(0, -SHOULDER_OFFSET, 0)).Position
	local delta = targetWorldPos - base
	local azimuth = math.deg(math.atan2(-delta.X, -delta.Z))

	local horizontalDist = math.sqrt(delta.X ^ 2 + delta.Z ^ 2)
	local drop = -delta.Y - GRIP_REACH -- positive when target is below the base; shortened because
	-- the gripper itself covers the last GRIP_REACH studs pointing straight down

	local reach = math.sqrt(horizontalDist ^ 2 + drop ^ 2)
	reach = math.clamp(reach, math.abs(L1 - L2) + 0.5, L1 + L2 - 0.5)

	local cosElbow = (reach ^ 2 - L1 ^ 2 - L2 ^ 2) / (2 * L1 * L2)
	local elbow = math.deg(math.acos(math.clamp(cosElbow, -1, 1)))

	local alpha = math.atan2(drop, horizontalDist)
	local beta = math.atan2(L2 * math.sin(math.rad(elbow)), L1 + L2 * math.cos(math.rad(elbow)))
	local shoulderLift = math.deg(alpha - beta)

	return {
		shoulder_pan = azimuth,
		shoulder_lift = shoulderLift,
		elbow_flex = elbow,
		wrist_flex = -(shoulderLift + elbow) + 90,
		wrist_roll = 0,
	}
end

local function solveIKWithGripper(pos, gripperVal)
	local angles = solveIK(pos)
	angles.gripper = gripperVal
	return angles
end

-- Debug helpers (Section 10.1 spirit -- quick numeric verification instead of guessing from
-- screenshots). Safe to leave in; harmless if never called.
function SkyArm.debugGripperPos()
	return gripperTipWorld
end

function SkyArm.debugSolve(pos)
	return solveIK(pos)
end

----------------------------------------------------------------
-- Angle interpolation / idle loop
----------------------------------------------------------------
-- Park pose is solved rather than hand-tuned, so it stays correct if the link lengths change.
-- Gripper parks ~7 studs below and ~7 ahead of the shoulder, well clear of the floor.
local function copyAngles(a)
	return {
		shoulder_pan = a.shoulder_pan, shoulder_lift = a.shoulder_lift, elbow_flex = a.elbow_flex,
		wrist_flex = a.wrist_flex, wrist_roll = a.wrist_roll, gripper = a.gripper,
	}
end

local IDLE_ANGLES = solveIKWithGripper(
	carriage.Position + Vector3.new(0, -SHOULDER_OFFSET - 7.05, -8),
	20
)

local current = copyAngles(IDLE_ANGLES)
local target = copyAngles(IDLE_ANGLES)

-- Place the whole rig before the first frame renders. Without this every part sits at the
-- world origin for one frame and the arm visibly flashes through the floor on spawn.
applyFK(current)

local busy = false
local heldCrate = nil

-- LIVE MODE -- the real arm steers this rig instead of its own job queue.
--
-- The gantry crane is the look we want: it hangs from the rails, slides along the roof between
-- bays, and its links were deliberately kept short because the trolley moves, so it fits the
-- room. A literal joint-for-joint mirror of the SO-101 does not fit the room -- it is a 43
-- stud tower. So the real arm drives this rig by its TIP: wherever the real jaw is, this jaw
-- goes, solved through the IK already here. The pose is not identical, but it reaches where
-- the real arm reaches, which is what reads as mirroring.
local liveMode = false
local liveTrolleyX = nil

function SkyArm.setLiveMode(on)
	liveMode = on and true or false
	if not liveMode then
		liveTrolleyX = nil
	end
end

function SkyArm.isLive()
	return liveMode
end

-- Point the jaw at a world position. Called every frame off the wire, so nothing here may
-- yield -- moveTrolleyTo tweens and waits, which is right for a queued job and wrong here.
function SkyArm.followTip(worldPos, gripperPct)
	if not liveMode or typeof(worldPos) ~= "Vector3" then
		return
	end
	-- Keep the jaw below its own shoulder. The real arm lifts higher than this room allows,
	-- and an arm reaching above its mount points straight through the roof.
	local ceiling = carriageY - SHOULDER_OFFSET - 1
	local y = math.clamp(worldPos.Y, MIN_TARGET_Y, ceiling)
	local clamped = Vector3.new(worldPos.X, y, worldPos.Z)

	liveTrolleyX = math.clamp(worldPos.X, TROLLEY_MIN_X, TROLLEY_MAX_X)

	local angles = solveIKWithGripper(clamped, tonumber(gripperPct) or 50)
	for key, v in pairs(angles) do
		target[key] = v
	end
end

session.track(RunService.Heartbeat:Connect(function(dt)
	-- The trolley tracks the arm instead of being tweened to a stop, so it slides continuously
	-- as the operator works across the mat.
	if liveMode and liveTrolleyX then
		local x = carriage.Position.X
		local step = math.clamp(dt * 6.0, 0, 1)
		carriage.CFrame = CFrame.new(x + (liveTrolleyX - x) * step,
			carriageY, carriage.Position.Z)
	end

	local alpha = math.clamp(dt * 4.0, 0, 1)
	for key in pairs(current) do
		current[key] += (target[key] - current[key]) * alpha
	end
	applyFK(current)

	if heldCrate and heldCrate.Parent and heldCrate:FindFirstChild("Base") then
		local base = heldCrate.Base
		base.CFrame = CFrame.new(gripperTipWorld - Vector3.new(0, base.Size.Y / 2 + 0.5, 0))
		local stripe = heldCrate:FindFirstChild("Stripe")
		if stripe then
			stripe.CFrame = base.CFrame * CFrame.new(0, base.Size.Y / 2 + 0.05, 0)
		end
		local topper = heldCrate:FindFirstChild("Topper")
		if topper then
			topper.CFrame = base.CFrame * CFrame.new(0, base.Size.Y / 2 + topper.Size.Y / 2, 0)
			local topperStripe = heldCrate:FindFirstChild("TopperStripe")
			if topperStripe then
				topperStripe.CFrame = topper.CFrame * CFrame.new(0, topper.Size.Y / 2 + 0.05, 0)
			end
		end
	end

	if not busy then
		local t = os.clock()
		target.shoulder_pan = math.sin(t * 0.15) * 15
		target.shoulder_lift = IDLE_ANGLES.shoulder_lift + math.sin(t * 0.2 + 1) * 6
		target.elbow_flex = IDLE_ANGLES.elbow_flex + math.sin(t * 0.18 + 2) * 8
		target.wrist_flex = IDLE_ANGLES.wrist_flex + math.sin(t * 0.25) * 5
		target.wrist_roll = math.sin(t * 0.1) * 20
		target.gripper = IDLE_ANGLES.gripper
	end
end))

local function angleError(a, b)
	local sum = 0
	for key in pairs(a) do
		sum += math.abs(a[key] - b[key])
	end
	return sum
end

local function moveTo(angles, timeout)
	for key, v in pairs(angles) do
		target[key] = v
	end
	local elapsed = 0
	while angleError(current, target) > 1.5 and elapsed < (timeout or 1.5) do
		task.wait(0.03)
		elapsed += 0.03
	end
end

----------------------------------------------------------------
-- Job queue -- serializes every reach/place/remove so concurrent cell edits can't fight over
-- the one shared arm.
----------------------------------------------------------------
local jobQueue = {}
local processing = false

local function processQueue()
	if processing then
		return
	end
	processing = true
	-- session.spawn: a job still running when the round ends is cancelled with it
	session.spawn(function()
		while #jobQueue > 0 do
			local job = table.remove(jobQueue, 1)
			job()
		end
		processing = false
	end)
end

local function enqueue(job)
	table.insert(jobQueue, job)
	processQueue()
end

----------------------------------------------------------------
-- Public API
----------------------------------------------------------------
function SkyArm.setActiveBay(bayModel)
	if not bayModel then
		return
	end
	-- Centre on the middle ROW ANCHOR, not on the Floor part. An obstacle may legitimately
	-- cut the floor about -- bay 2's Void removes it over rows 0-1 entirely -- which leaves
	-- Floor.Position sitting over whatever slab survived, and parked the crane 8 studs off
	-- the bay. The Cell_c_r anchors are baked and never modified, which is why everything
	-- else positional already reads from them.
	local anchors = bayModel:FindFirstChild("CrateAnchors")
	local mid = anchors and anchors:FindFirstChild("Cell_0_1")
	local z = mid and mid.Position.Z
	if not z then
		local floor = bayModel:FindFirstChild("Floor")
		z = floor and floor.Position.Z
	end
	if not z then
		return
	end
	local goal = CFrame.new(carriage.Position.X, carriageY, z)
	local tween = TweenService:Create(carriage, TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {CFrame = goal})
	tween:Play()
end

-- Slides the trolley along the bridge so it sits above the target column before reaching.
local function moveTrolleyTo(x)
	local clamped = math.clamp(x, TROLLEY_MIN_X, TROLLEY_MAX_X)
	local travel = math.abs(clamped - carriage.Position.X)
	if travel < 0.05 then
		return
	end
	local duration = math.clamp(travel / 14, 0.25, 1.0)
	local goal = CFrame.new(clamped, carriageY, carriage.Position.Z)
	TweenService:Create(carriage, TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {CFrame = goal}):Play()
	task.wait(duration)
end

-- Crates stay hidden until they're actually in the gripper, otherwise they flash at the world
-- origin for a frame before the held-crate tracking positions them.
local function setCrateVisible(crateModel, visible)
	for _, d in ipairs(crateModel:GetDescendants()) do
		if d:IsA("BasePart") then
			d.Transparency = visible and 0 or 1
		elseif d:IsA("SurfaceGui") then
			d.Enabled = visible
		end
	end
end

-- Reaches to `worldCFrame`, "grips" the already-built (but staged) crateModel, carries it down,
-- and calls onArrive right as it seats -- the caller snaps the crate's final CFrame and plays
-- its own impact effect (shockwave) from inside that callback.
function SkyArm.reachAndPlace(bayModel, worldCFrame, crateModel, level, onArrive)
	enqueue(function()
		-- a newer edit can replace this crate while it is still sitting in the queue
		if crateModel:GetAttribute("Superseded") then
			crateModel:Destroy()
			return
		end
		busy = true
		local cellPos = worldCFrame.Position
		local grip = Vector3.new(cellPos.X, cellPos.Y + gripHeight(), cellPos.Z)
		local hoverPos = grip + Vector3.new(0, 7, 0)

		crateModel.Parent = bayModel
		setCrateVisible(crateModel, false)

		moveTrolleyTo(cellPos.X)
		moveTo(solveIKWithGripper(hoverPos, 0), 1.2)

		-- take hold first, let one frame place it at the gripper, then reveal
		heldCrate = crateModel
		task.wait()
		setCrateVisible(crateModel, true)
		moveTo(solveIKWithGripper(hoverPos, 100), 0.4)

		moveTo(solveIKWithGripper(grip + Vector3.new(0, 2, 0), 100), 1.0)
		moveTo(solveIKWithGripper(grip, 100), 0.5)

		heldCrate = nil
		if onArrive then
			onArrive()
		end

		moveTo(solveIKWithGripper(hoverPos, 0), 0.8)
		moveTo(IDLE_ANGLES, 1.0)
		busy = false
	end)
end

-- Reaches to the existing crate at `worldCFrame`, grips and lifts it clear (calling onLifted),
-- carries it off, then destroys it.
function SkyArm.reachAndRemove(bayModel, worldCFrame, crateModel, onLifted)
	enqueue(function()
		busy = true
		local cellPos = worldCFrame.Position
		local grip = Vector3.new(cellPos.X, cellPos.Y + gripHeight(), cellPos.Z)
		local hoverPos = grip + Vector3.new(0, 7, 0)

		moveTrolleyTo(cellPos.X)
		moveTo(solveIKWithGripper(grip, 0), 1.0)
		moveTo(solveIKWithGripper(grip, 100), 0.4)
		heldCrate = crateModel

		moveTo(solveIKWithGripper(hoverPos, 100), 1.0)
		if onLifted then
			onLifted()
		end

		local disposePos = hoverPos + Vector3.new(0, 0, -6)
		moveTo(solveIKWithGripper(disposePos, 100), 0.8)
		heldCrate = nil
		if crateModel.Parent then
			crateModel:Destroy()
		end

		moveTo(IDLE_ANGLES, 1.0)
		busy = false
	end)
end

return SkyArm
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.ArmMirror", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.ArmMirror (ModuleScript)
-- ArmMirror -- the giant arm that IS player 2. Adapted from the bridge branch's SkyArm.
--
-- Renamed from SkyArm on purpose: the sibling Server.SkyArm is the obby's own IK rig, which
-- *simulates* an operator by animating a crate delivery. There is a real operator now, so the
-- two cannot both drive the same bay -- an animated reach would re-enact something player 2
-- already did with their hands. SkyArm stays as the solo/DebugMode path; this is the live one,
-- and only one is visible at a time (see setVisible).
--
-- Python sends the arm as a stick figure of *world points* in sheet mm (one per joint centre,
-- base to tip), not as raw joint angles. That is why this file is short: no link lengths, no
-- Motor6D rig to assemble, and no per-joint sign or offset to discover by wiggling one real
-- joint at a time. Segment i is simply the part spanning points i and i+1. The real kinematics
-- already ran in Python against the arm's own URDF and its fitted calibration, so the geometry
-- is right by construction.
--
--   local ArmMirror = require(script.Parent.ArmMirror)
--   local arm = ArmMirror.new(RunControl.session.map)   -- inside the round's map, never Workspace
--   -- on every core state update (BridgeFeed): local s = core.get(); arm:update(s.arm, s.arm_age)
--
-- Shape of the thing, which is not what Config.GantryHeight expects: the real SO-101's pan
-- axis is 69 mm off the paper and its wrist reaches 306 mm, so at the mat-to-bay scale this is
-- a 43-stud arm whose shoulder sits 9.7 studs up. It is a table arm reaching up and over, not
-- a gantry arm hanging down. Mapping puts its base at the bay's centre column, 9.3 studs
-- *before* the entrance edge, so it stands on the catwalk and towers over the bay.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local Mapping = require(script.Parent:WaitForChild("Mapping"))

local ArmMirror = {}
ArmMirror.__index = ArmMirror

local SEGMENT_COLOR = Color3.fromRGB(242, 242, 240)   -- printed PLA, as SkyArm uses
local JOINT_COLOR = Color3.fromRGB(30, 30, 32)        -- Feetech STS3215 servo bodies
local TIP_COLOR = Color3.fromRGB(77, 163, 255)
local STALE_COLOR = Color3.fromRGB(96, 98, 104)

-- Cross-section of the real links: Upper_arm_SO101 is 67.54 x 24.67 mm. Expressed in mm so it
-- tracks the mat scale automatically instead of being a stud constant that rots when the scale
-- is retuned.
local LINK_W_MM, LINK_D_MM = 67.54, 24.67

local function part(parent, name, color, size)
	local p = Instance.new("Part")
	p.Name = name
	p.Anchored = true
	p.CanCollide = false          -- scenery: the player never stands on the arm itself
	p.CanQuery = false            -- and must never be picked up by a reach-gating raycast
	p.CastShadow = true
	p.Material = Enum.Material.SmoothPlastic
	p.Color = color
	p.Size = size
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Parent = parent
	return p
end

function ArmMirror.new(parent, opts)
	local self = setmetatable({}, ArmMirror)
	opts = opts or {}
	self.linkWmm = opts.linkWmm or LINK_W_MM
	self.linkDmm = opts.linkDmm or LINK_D_MM
	self.model = Instance.new("Model")
	self.model.Name = "ArmMirror"
	self.model.Parent = parent
	self.parent = parent              -- where setVisible puts it back (the round's map)
	self.segments = {}
	self.joints = {}
	self.points = {}
	self.stale = false
	self.visible = true

	-- The pan axis sits ~9.7 studs above the floor, so without something underneath it the arm
	-- reads as floating. A plinth is also honest: the real arm is bolted to the table beside
	-- the mat, not hanging from anything.
	self.plinth = part(self.model, "Plinth", Color3.fromRGB(46, 48, 54), Vector3.new(1, 1, 1))
	self.plinth.Material = Enum.Material.DiamondPlate
	return self
end

function ArmMirror.setVisible(self, visible)
	self.visible = visible
	self.model.Parent = visible and self.parent or nil
end

-- One segment positioned to span a -> b. A Part's CFrame is its centre and CFrame.lookAt
-- points the local Z axis down the span, so size.Z is the length.
function ArmMirror.setSegment(self, i, a, b)
	local seg = self.segments[i]
	if not seg then
		seg = part(self.model, "Segment" .. i, SEGMENT_COLOR, Vector3.new(1, 1, 1))
		self.segments[i] = seg
	end
	local span = (b - a).Magnitude
	if span < 0.01 then
		seg.Transparency = 1
		return
	end
	local s = Mapping.STUDS_PER_MM
	seg.Transparency = 0
	seg.Color = self.stale and STALE_COLOR or SEGMENT_COLOR
	seg.Size = Vector3.new(self.linkWmm * s, self.linkDmm * s, span)
	seg.CFrame = CFrame.lookAt((a + b) / 2, b)
end

function ArmMirror.update(self, arm, age)
	if arm == nil or arm.points == nil then
		return
	end

	-- A stale pose is worse than no pose: the arm sits confidently in a position the real one
	-- left seconds ago. Blocks update slower than the arm (perception ~10 Hz vs 30 Hz) and both
	-- ages climb on a servo-bus dropout, which robot/teleop_monitored.py documents happening
	-- 37-220 s into sustained motion. So grey out rather than lie.
	self.stale = (tonumber(age) or 0) > (Config.StaleAfterSeconds or 2)

	local pts = {}
	for i, p in arm.points do
		pts[i] = Mapping.point(p)
	end
	self.points = pts
	if #pts == 0 then
		return
	end

	for i = 1, #pts - 1 do
		self:setSegment(i, pts[i], pts[i + 1])
	end
	for i = #pts, #self.segments do
		if self.segments[i] then
			self.segments[i].Transparency = 1
		end
	end

	local s = Mapping.STUDS_PER_MM
	for i, p in pts do
		local j = self.joints[i]
		if not j then
			local last = i == #pts
			local d = self.linkWmm * s * (last and 0.75 or 0.6)
			j = part(self.model, "Joint" .. i, last and TIP_COLOR or JOINT_COLOR,
				Vector3.new(d, d, d))
			j.Shape = Enum.PartType.Ball
			self.joints[i] = j
		end
		j.Color = self.stale and STALE_COLOR or (i == #pts and TIP_COLOR or JOINT_COLOR)
		j.CFrame = CFrame.new(p)
	end

	-- Plinth: from the bay floor up to the pan axis, under the base point.
	local base = pts[1]
	local floorY = Mapping.ORIGIN.Y
	local h = math.max(0.2, base.Y - floorY)
	local w = self.linkWmm * s * 1.4
	self.plinth.Size = Vector3.new(w, h, w)
	self.plinth.CFrame = CFrame.new(base.X, floorY + h / 2, base.Z)
end

-- Where the jaw tips are. The held-block platform hangs here, and this is the hook the 1v1
-- arena grab tests against.
function ArmMirror.tip(self)
	return self.points[#self.points]
end

-- Anchored, CFrame-driven parts do not fire Touched reliably, so overlap is checked on the
-- server each Heartbeat instead.
function ArmMirror.partsTouching(self, params)
	local hits, seen = {}, {}
	for _, seg in self.segments do
		if seg.Transparency < 1 then
			for _, hit in workspace:GetPartsInPart(seg, params) do
				if not seen[hit] then
					seen[hit] = true
					table.insert(hits, hit)
				end
			end
		end
	end
	return hits
end

return ArmMirror
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.HazardManager", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.HazardManager (ModuleScript)
-- HazardManager -- one obstacle per bay (4x3). Each obstacle owns its whole bay, is lethal
-- while unsolved, and resolves when the required blocks land in its solveCells.
--
-- Design rule throughout: the blocks that SOLVE an obstacle are also the player's safe footing.
-- Nothing may kill the player while they're standing on the thing that solved it.
--
-- ARCADE (docs/obby-mode-plan.md). This was a Script; it is a ModuleScript now, required once per
-- round by Modes.Obby.Module after RunControl.session is set. The body still runs at require time
-- -- it builds every bay and publishes RunControl's rebuild hooks -- and the clone of Server/ is
-- fresh each round, so so is everything in here. Every loop is `while folder.Parent do`, and the
-- map (with every Obstacle folder in it) is destroyed at Stop, which is what ends them.
-- Returns `HazardManager` ({states = bay model -> state}); Module reads solves through
-- RunControl.bayState.
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local Workspace = game:GetService("Workspace")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Debris = game:GetService("Debris")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local BayData = require(script.Parent:WaitForChild("BayData"))
local BlockSync = require(script.Parent:WaitForChild("BlockSync"))
local Mapping = require(script.Parent:WaitForChild("Mapping"))
local RunControl = require(script.Parent:WaitForChild("RunControl"))

local session = RunControl.session
assert(session, "[HazardManager] required before RunControl.session was set")

local Ui = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("UiTheme"))

local Remotes = ReplicatedStorage.Obby:WaitForChild("Remotes")
local ObjectiveEvent = Remotes:WaitForChild("Objective")
-- The direct popup channel. ObjectiveHud turns these into a toast, or into a full-screen
-- stamp when `big` is set. Kept separate from the objective payload because an EVENT ("that
-- block was refused") and a STATE ("this bay wants two blocks") want different lifetimes --
-- a state persists in every later push, which is why a flash has to be edge-detected.
local ToastEvent = Remotes:FindFirstChild("Toast")
if not ToastEvent then
	ToastEvent = Instance.new("RemoteEvent")
	ToastEvent.Name = "Toast"
	ToastEvent.Parent = Remotes
end

local HazardManager = {}

local CELL = Config.CellSize

-- The arcade bakes the course Config.OriginZ down +Z, so bay 1 no longer starts at Z = 0. Kept
-- identical to RunControl.bayZStart: every Z in this file is derived from this, cellCenter or
-- bayCenter, or read off a part.
local function bayZStart(i)
	return RunControl.bayZStart(i)
end

local function cellCenter(i, col, row)
	return Vector3.new(col * CELL + CELL / 2, 0, bayZStart(i) + row * CELL + CELL / 2)
end

local function bayCenter(i)
	return Vector3.new(Config.BayWidth / 2, 0, bayZStart(i) + Config.BayDepth / 2)
end

-- Blocks are INTERCHANGEABLE. An obstacle cares how many cubes are in a cell -- the stack
-- height -- and never what colour they are, because the operator grabs whichever cube is to
-- hand on the real table. So a requirement only ever reads "a block here" or "a stack of N",
-- and every colour test has been stripped out of the solve path. Crates still SPAWN in their
-- colours; that is appearance, and the debug editor still picks one.
local function blockReq(level)
	return ((level or 1) > 1) and string.format("STACK x%d", level) or "BLOCK"
end

local function newPart(name, size, pos, color, material, parent, props)
	local p = Instance.new("Part")
	p.Name = name
	p.Anchored = true
	p.CanCollide = false
	p.Size = size
	p.CFrame = CFrame.new(pos)
	p.Color = color or Color3.fromRGB(150, 150, 150)
	p.Material = material or Enum.Material.SmoothPlastic
	if props then
		for k, v in pairs(props) do
			p[k] = v
		end
	end
	p.Parent = parent
	return p
end

-- An in-world label, styled as a brass plate bolted to the machine.
--
-- TWO THINGS CHANGED AND BOTH MATTER. It used to be `AlwaysOnTop = true`, so every label in
-- the course drew THROUGH the walls -- the dark room's "POWER BOX" plate was legible from
-- outside the sealed room, and labels from bays you were nowhere near floated over the
-- scenery. Now it occludes like anything else, and `MaxDistance` fades it out rather than
-- letting the whole course shout at you at once.
--
-- It still returns the TextLabel, because every caller drives it by writing `.Text` and
-- `.TextColor3` and none of them should have to care that the frame around it changed.
local function addLabel(parent, text, pos, color)
	local anchor = newPart("Label", Vector3.new(0.2, 0.2, 0.2), pos, nil, nil, parent,
		{Transparency = 1, CanQuery = false})
	local b = Instance.new("BillboardGui")
	b.Size = UDim2.fromOffset(168, 32)
	b.AlwaysOnTop = false
	-- 55 studs is chosen, not arbitrary: it is close enough to read from anywhere inside the
	-- bay you are standing in, and short enough that the OVERSEER -- parked 62 studs up --
	-- never sees them at all. Player 2 has the mat card and the numbered floor pads for the
	-- same information, and in the top-down view these plates stacked on top of each other.
	b.MaxDistance = 55
	b.LightInfluence = 0
	b.Parent = anchor

	local plate = Instance.new("Frame")
	plate.Size = UDim2.fromScale(1, 1)
	plate.BackgroundColor3 = Ui.C.ironDark
	plate.BackgroundTransparency = 0.12
	plate.BorderSizePixel = 0
	plate.Parent = b
	Ui.corner(plate, 4)
	Ui.stroke(plate, Ui.C.brass, 2)
	Ui.sheen(plate, 0.3)
	-- rivets at the corners: the detail that makes it read as bolted on rather than drawn on
	for _, a in ipairs({Vector2.new(0, 0), Vector2.new(1, 0), Vector2.new(0, 1), Vector2.new(1, 1)}) do
		Ui.rivet(plate, Vector2.new(0.5, 0.5),
			UDim2.new(a.X, a.X == 0 and 7 or -7, a.Y, a.Y == 0 and 7 or -7))
	end

	local l = Instance.new("TextLabel")
	l.AnchorPoint = Vector2.new(0.5, 0.5)
	l.Position = UDim2.fromScale(0.5, 0.5)
	l.Size = UDim2.new(1, -18, 1, -12)
	l.BackgroundTransparency = 1
	l.TextColor3 = color or Ui.C.amber
	l.Font = Ui.F.title
	l.TextScaled = true
	l.TextWrapped = true
	l.Text = text
	l.ZIndex = 3
	l.Parent = plate
	return l
end

-- The bay nameplate, on the physical sign that was already standing beside every bay doing
-- nothing. Two SurfaceGuis, one per face, because the sign's facing is baked geometry and
-- guessing wrong leaves the plate pointing into the wall. The returned proxy forwards
-- `.Text` and `.TextColor3` to both, so callers write to it exactly like a TextLabel.
local function baySignPlate(bay, text, color)
	local sign = bay and bay:FindFirstChild("Sign")
	if not sign then
		return nil
	end
	local labels = {}
	for _, face in ipairs({Enum.NormalId.Front, Enum.NormalId.Back}) do
		local old = sign:FindFirstChild("UiPlate" .. face.Name)
		if old then
			old:Destroy()
		end
		local made = Ui.plate(sign, {text = text, colour = color, face = face,
			maxDistance = 120, ppu = 36})
		made.gui.Name = "UiPlate" .. face.Name
		table.insert(labels, made.label)
	end
	return setmetatable({}, {
		__newindex = function(_, k, v)
			for _, l in ipairs(labels) do
				l[k] = v
			end
		end,
		__index = function(_, k)
			return labels[1] and labels[1][k]
		end,
	})
end

-- Debug ghost mode (Q) makes a character untouchable by every obstacle.
local function isGhost(character)
	return character ~= nil and character:GetAttribute("Ghost") == true
end

local function characterFrom(hit)
	local model = hit and hit:FindFirstAncestorOfClass("Model")
	if not model then
		return nil
	end
	local hum = model:FindFirstChildOfClass("Humanoid")
	if hum and Players:GetPlayerFromCharacter(model) and not isGhost(model) then
		return model, hum
	end
	return nil
end

-- Who is standing in bay `i` right now. `pad` widens the test toward the entrance, so a bay
-- can put its objective on screen while the player is still on the approach catwalk sizing the
-- obstacle up. The y floor drops a player who has already fallen out of the world, which for a
-- void bay is most of them. Only this round's runners count: in the arcade the server also holds
-- the Workshop, the other cabinets and the robot role.
local function occupantsOf(i, pad)
	local zStart = bayZStart(i)
	local zEnd = zStart + Config.BayDepth
	local found = {}
	for _, pl in ipairs(session.runners) do
		local ch = pl.Character
		local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if hrp and hum and hum.Health > 0 and not isGhost(ch) then
			local p = hrp.Position
			if p.Z > zStart - (pad or 0) and p.Z < zEnd + 2
				and p.X > -2 and p.X < Config.BayWidth + 2 and p.Y > -8 then
				table.insert(found, {character = ch, humanoid = hum, position = p})
			end
		end
	end
	return found
end

-- Bays whose goal is an ACTION rather than a placement own state.solved themselves, and
-- checkSolved must not overwrite it from the cells list. Bay 1 throws levers; bay 3 walks a
-- generated route. Their solveCells, if any, degrade to an advisory hint.
local function ownsItsSolve(info)
	return info.solveMode == "switches" or info.solveMode == "action"
end

-- Objective HUD arbitration. Remotes.Objective is ONE channel, but every bay has an opinion
-- about what belongs on it. While bay 1 was the only driver, broadcasting was fine; the moment
-- a second bay started publishing, bay 1's loop -- which broadcasts a clear every 0.2s whenever
-- its own bay is empty -- began wiping the callout of the bay the player was actually standing
-- in, and bay 2's HUD only ever appeared in the gaps between those clears.
--
-- So no bay broadcasts any more. A bay addresses only the players inside it, and clears only a
-- player it was itself last showing something to. That also makes each bay's own stated intent
-- true -- "a player standing outside the bay isn't told to do anything" -- which broadcasting
-- never actually delivered.
local hudShownBy = setmetatable({}, {__mode = "k"})

-- Which single bay owns a player's HUD. Containment alone is not enough: a bay wants its
-- callout up while the player is still on the approach catwalk, but the gap between bays is
-- only Config.BayGap studs and the pad is a whole cell, so two neighbours' padded windows
-- overlap and both would claim anyone standing between them. Standing at z=57 (course Z, so
-- Config.OriginZ + 57 in the arcade) showed bay 2's callout while walking into bay 3.
--
-- So: the bay whose body you are actually inside always wins. Outside every body, the bay you
-- are walking TOWARDS wins over the one you just left, which is the direction the game runs.
local function hudBayFor(pos, pad)
	local approach, approachDist = nil, math.huge
	local trailing, trailingDist = nil, math.huge
	for idx = 1, Config.NumBays do
		local zStart = bayZStart(idx)
		local zEnd = zStart + Config.BayDepth
		if pos.Z >= zStart and pos.Z <= zEnd then
			return idx
		elseif pos.Z < zStart then
			local d = zStart - pos.Z
			if d <= pad and d < approachDist then
				approach, approachDist = idx, d
			end
		else
			local d = pos.Z - zEnd
			if d <= pad and d < trailingDist then
				trailing, trailingDist = idx, d
			end
		end
	end
	return approach or trailing
end

-- A refused placement has to be visible to the PLAYER, not just printed on the server.
--
-- The saw wall flashed its own refusals; every other bay was silent, so bay 3 turning away a
-- block that was not the next cell on its route looked exactly like the block never arriving.
-- You place, nothing happens, nothing says why. Held centrally so a bay gets this for free
-- rather than each builder reinventing it.
local flashText, flashUntil, flashBay = nil, 0, nil
local FLASH_SECONDS = 2.6

BlockSync.PlacementRejected:Connect(function(bayModel, cell, reason)
	local idx = tonumber(tostring(bayModel.Name):match("Bay(%d+)"))
	flashBay = idx
	flashUntil = os.clock() + FLASH_SECONDS
	flashText = reason and tostring(reason)
		or ("CANNOT PLACE AT (%s,%s)"):format(tostring(cell and cell.col), tostring(cell and cell.row))
end)

-- ARCADE. Only this round's runners are addressed, never the whole server. The robot role has no
-- character, so it is never "inside" a bay, but the operator has to read the same callout the
-- runner is reading: whatever a runner is shown (or the clear when this bay retracts it) is
-- copied to every session.robots() player, with the same arbitration -- robotHudShownBy
-- remembers which bay last showed a robot something, so an EMPTY bay's clear cannot wipe the
-- payload of the bay the runner is actually in.
--
-- Module shows its own result screens (finish / time up) on this same remote. While
-- session.hudHeld[player] is true nothing is sent to that player, payload or clear, and while
-- session.hudHeld.all is true nothing is sent to anyone, runner or robot. A missing hudHeld
-- table counts as empty.
local robotHudShownBy = setmetatable({}, {__mode = "k"})

local function publishObjective(i, payload, pad)
	local held = session.hudHeld or {}
	if held.all == true then
		return
	end
	-- merge in any refusal this bay just made, unless the bay set its own
	if payload and flashBay == i and os.clock() < flashUntil and payload.flash == nil then
		payload.flash = flashText
	end
	local inside = {}
	for _, pl in ipairs(session.runners) do
		local ch = pl.Character
		local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if hrp and hum and hum.Health > 0 and not isGhost(ch) then
			local pos = hrp.Position
			if pos.X > -2 and pos.X < Config.BayWidth + 2 and pos.Y > -8
				and hudBayFor(pos, pad or 0) == i then
				inside[pl] = true
			end
		end
	end

	local shownToRunner = false
	for _, pl in ipairs(session.runners) do
		if held[pl] == true then
			-- Module's result screen owns this player's HUD
		elseif inside[pl] and payload then
			hudShownBy[pl] = i
			shownToRunner = true
			ObjectiveEvent:FireClient(pl, payload)
		elseif hudShownBy[pl] == i then
			-- only ever retract what this bay put up
			hudShownBy[pl] = nil
			ObjectiveEvent:FireClient(pl, nil)
		end
	end

	for _, pl in ipairs(session.robots()) do
		if held[pl] == true then
			-- held, as above
		elseif shownToRunner then
			robotHudShownBy[pl] = i
			ObjectiveEvent:FireClient(pl, payload)
		elseif robotHudShownBy[pl] == i then
			robotHudShownBy[pl] = nil
			ObjectiveEvent:FireClient(pl, nil)
		end
	end
end

-- Per-part lethality, for obstacles made of many independently-switchable pieces (the laser
-- grid). The part carries its own "Live" attribute instead of reading the bay's solved flag.
local function makeLethalPart(part)
	part:SetAttribute("Live", true)
	part.CanTouch = true
	part.Touched:Connect(function(hit)
		if part:GetAttribute("Live") ~= true then
			return
		end
		local _, hum = characterFrom(hit)
		if hum and hum.Health > 0 then
			hum.Health = 0
		end
	end)
end

-- Lethal touch that respects the solved flag, so solved obstacles stop killing.
local function makeLethal(part, state)
	part.CanTouch = true
	part.Touched:Connect(function(hit)
		if state.solved then
			return
		end
		local _, hum = characterFrom(hit)
		if hum and hum.Health > 0 then
			hum.Health = 0
		end
	end)
end

----------------------------------------------------------------
-- Obstacle builders. Each returns a `state` table with .solved and :setSolved(bool)
----------------------------------------------------------------
local BUILDERS = {}

-- SAW WALL: the bay seals behind you and a wall of chainsaws closes in from the FAR end. It
-- starts by the exit and comes toward the entrance, so walking in is never blocked and the wall
-- itself is the only thing between you and the way out. Two levers, mounted too high to reach
-- from the floor, are the escape: the crates are a LADDER to the answer rather than the answer
-- itself. Lever A kills the blades and arms Lever B; Lever B halts the wall and sinks it into
-- the floor, and that IS the exit -- there is no separate gate. The closing wall is the clock,
-- which makes Config.SawWallSeconds the one knob for this bay's difficulty.
--
-- Stalling the wall is a REWARD for killing the blades, never a way to skip that step:
--   blades live -> the wall cuts straight through a crate without slowing, and a crate cannot
--                  even be placed within Config.SawWallNoPlaceBand of the blades
--   blades dead -> nothing cuts, so the first crate in the path jams the wall, but only for
--                  Config.SawWallStallSeconds -- a crate buys a reprieve, never a permanent
--                  shield, and each crate's stall is spent once
-- A crate is never destroyed, because the real cube is still on the operator's table and the
-- game has to mirror it. That also makes the Lever B stack a shield once A is thrown, so the
-- player is never killed standing on the block that saved them.
BUILDERS.Saw = function(i, folder, info, state)
	local z0 = bayZStart(i)
	local zEnd = z0 + Config.BayDepth
	local midX = Config.BayWidth / 2

	-- Closes from the far end toward the entrance. A first version started the wall two studs
	-- inside the door, spanning the full width with CanCollide on, which blocked the player
	-- from entering the bay at all.
	local WALL_START = zEnd - 2
	local WALL_END = z0 + 2.5
	-- Tall enough that it cannot be jumped. A default jump clears about 12.8 studs of head
	-- height, so a 7.4 stud wall was a hurdle, not a wall -- the only way past is to sink it.
	local WALL_H = 16
	local WALL_Y = WALL_H / 2

	-- The wall runs in side channels rather than spanning the bay edge to edge, which is what
	-- keeps it clear of the wall-mounted levers: it sweeps PAST them instead of through them.
	local SIDE_T = 1.0                       -- side wall thickness
	local SIDE_FACE = SIDE_T / 2             -- inner face of the left side wall
	local WALL_X0 = SIDE_FACE + 0.6
	local WALL_X1 = Config.BayWidth - SIDE_FACE - 0.6
	local WALL_W = WALL_X1 - WALL_X0
	local TICK = 0.05
	-- Advance off measured elapsed time, not tick count: task.wait(0.05) actually sleeps a bit
	-- longer, which made a nominal 30s traverse take about 34s. The wall is this bay's clock,
	-- so SawWallSeconds has to mean real seconds.
	local studsPerSecond = (WALL_START - WALL_END) / Config.SawWallSeconds
	local lastTick = os.clock()

	-- paint the sweep lane, so the operator can see where a brake crate actually intercepts
	newPart("SweepLane", Vector3.new(Config.BayWidth - 1, 0.08, Config.BayDepth - 1),
		Vector3.new(midX, 0.06, z0 + Config.BayDepth / 2), Color3.fromRGB(120, 92, 22),
		Enum.Material.SmoothPlastic, folder, {Transparency = 0.6, CanQuery = false})

	----------------------------------------------------------------
	-- entry gate only. There is deliberately no exit gate: the saw wall is the exit barrier,
	-- and Lever B lowering it is what opens the way through.
	----------------------------------------------------------------
	local GATE_H = 14
	local entryGate = newPart("EntryGate", Vector3.new(Config.BayWidth, GATE_H, 1),
		Vector3.new(midX, -GATE_H / 2, z0), Color3.fromRGB(72, 68, 62),
		Enum.Material.DiamondPlate, folder, {CanCollide = true})

	local function slideGate(gate, up)
		TweenService:Create(gate, TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
			{CFrame = CFrame.new(gate.Position.X, up and GATE_H / 2 or -GATE_H / 2, gate.Position.Z)}):Play()
	end

	----------------------------------------------------------------
	-- the wall
	----------------------------------------------------------------
	-- Side channels. The bay had no side walls at all -- Border.Left/Right are 0.25 stud floor
	-- stripes you can walk straight over -- which is why the levers used to need a mount block
	-- jutting into the bay: there was nothing to bolt them to.
	for _, side in ipairs({{"Left", 0}, {"Right", Config.BayWidth}}) do
		newPart("SideWall" .. side[1], Vector3.new(SIDE_T, WALL_H, Config.BayDepth),
			Vector3.new(side[2], WALL_H / 2, z0 + Config.BayDepth / 2),
			Color3.fromRGB(64, 62, 60), Enum.Material.DiamondPlate, folder,
			{CanCollide = true})
		newPart("SideRail" .. side[1], Vector3.new(SIDE_T + 0.3, 0.5, Config.BayDepth),
			Vector3.new(side[2], WALL_H - 0.5, z0 + Config.BayDepth / 2),
			Color3.fromRGB(230, 170, 40), Enum.Material.Neon, folder, {CanQuery = false})
	end

	local frame = newPart("WallFrame", Vector3.new(WALL_W, WALL_H, 1.2),
		Vector3.new((WALL_X0 + WALL_X1) / 2, WALL_Y, WALL_START), Color3.fromRGB(58, 54, 50),
		Enum.Material.DiamondPlate, folder, {CanCollide = true})

	-- Two rows of blades now that there is a wall's worth of height to fill. The lower row is
	-- what you meet standing on the floor; the upper row is what you meet standing on a stack,
	-- so climbing never takes you above the danger.
	local blades = {}
	for col = 0, Config.BayCols - 1 do
		local bx = col * CELL + CELL / 2
		for row, by in ipairs({WALL_H * 0.28, WALL_H * 0.72}) do
			-- a Cylinder's flat faces point along X, so this is a vertical disc facing
			-- sideways and it spins about its own axis rather than tumbling
			local blade = newPart(("WallBlade%d_%d"):format(col, row),
				Vector3.new(0.4, 6.4, 6.4), Vector3.new(bx, by, WALL_START),
				Color3.fromRGB(208, 210, 216), Enum.Material.Metal, folder,
				{Shape = Enum.PartType.Cylinder})
			makeLethalPart(blade)
			table.insert(blades, {part = blade, x = bx, y = by})
		end
	end

	local sparks = newPart("Sparks", Vector3.new(Config.BayWidth - 2, 0.5, 0.5),
		Vector3.new(midX, 1.2, WALL_START), Color3.fromRGB(255, 200, 70),
		Enum.Material.Neon, folder, {Transparency = 1, CanQuery = false})

	local wallZ, spin, bladesLive = WALL_START, 0, true
	local sunk = false
	-- declared up here, not down with the run/reset helpers, because the placement guard below
	-- closes over it; left further down it resolved to a nil global and the guard allowed
	-- everything through
	local running = false
	-- a stall is spent per crate, so the wall cannot sit on the same one forever
	local stallSpent, stallCrate, stallStart = {}, nil, 0
	local flashText, flashUntil = "", 0

	local function placeWall(z)
		if sunk then
			return -- the lowering tween owns the CFrames now
		end
		frame.CFrame = CFrame.new(midX, WALL_Y, z)
		for _, b in ipairs(blades) do
			b.part.CFrame = CFrame.new(b.x, WALL_Y - 0.4, z) * CFrame.Angles(spin, 0, 0)
		end
		-- sparks sit on the near face, the side the player is on
		sparks.CFrame = CFrame.new(midX, 1.2, z - 1.2)
	end

	local function setBladesLive(live)
		bladesLive = live
		for _, b in ipairs(blades) do
			b.part:SetAttribute("Live", live)
			b.part.Color = live and Color3.fromRGB(208, 210, 216) or Color3.fromRGB(96, 98, 104)
		end
	end

	-- Lever B's payoff: the wall drops into the floor and you continue out over it. Collision
	-- is cleared once it is low enough to step across.
	local function sinkWall()
		sunk = true
		-- deep enough that a WALL_H wall's top ends below the floor, not just its middle
		local downY = -(WALL_H / 2) - 1.5
		local info = TweenInfo.new(1.6, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
		TweenService:Create(frame, info, {CFrame = CFrame.new(midX, downY, wallZ)}):Play()
		for _, b in ipairs(blades) do
			TweenService:Create(b.part, info,
				{CFrame = CFrame.new(b.x, downY - 0.4, wallZ) * CFrame.Angles(spin, 0, 0)}):Play()
		end
		task.delay(0.9, function()
			frame.CanCollide = false
		end)
	end

	-- Nearest crate the wall is about to meet. It travels toward -Z, so the next thing it
	-- meets is whatever sits just in front of its near face.
	local function crateInPath(z)
		if not Config.SawWallBrakeEnabled then
			return nil
		end
		for _, c in ipairs(folder.Parent:GetChildren()) do
			if c.Name == "Crate" then
				local b = c:FindFirstChild("Base")
				if b and b.Position.Z < z and z - b.Position.Z < 3.1 then
					return b
				end
			end
		end
		return nil
	end

	-- Refuse deliveries that would stall the wall before the blades are dead. The band is
	-- measured from the blades, so a crate placed early -- while the wall is still far away --
	-- is fine; it is only dropping one just in front of live blades that is turned away.
	-- Rejections are parked by BlockSync and re-offered when Lever A changes the answer.
	local showNotice
	BlockSync.setPlacementGuard(folder.Parent, function(cell)
		if not running or not bladesLive then
			return true
		end
		local cellZ = cellCenter(i, cell.col, cell.row).Z
		if cellZ > wallZ - Config.SawWallNoPlaceBand then
			if showNotice then
				showNotice("BLADES LIVE - CANNOT DROP THERE")
			end
			return false, "blades live"
		end
		return true
	end)

	----------------------------------------------------------------
	-- levers. Colour code is deliberate: green means "this is your target right now" and
	-- nothing else is ever green, so a thrown lever goes cold blue instead of staying green.
	----------------------------------------------------------------
	local DORMANT, ARMED, THROWN = 0, 1, 2
	local HANDLE_LEN = 2.4

	-- A lever only responds if the player is standing on a crate tall enough for it. Gating on
	-- the support, rather than mounting the lever out of jump range, keeps the cube requirement
	-- exact -- Lever A needs any crate, Lever B needs a stacked pair. Without this check a
	-- default jump from the floor reaches roughly 12.8 studs of head height and clears both.
	local function supportHeight(character)
		local hrp = character:FindFirstChild("HumanoidRootPart")
		if not hrp then
			return 0
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = {character}
		local hit = Workspace:Raycast(hrp.Position, Vector3.new(0, -9, 0), params)
		-- Live cubes carry an IsCrate attribute; the DebugMode path's crates are still matched
		-- by name. Keying on the attribute means the live path does not have to name a cube
		-- sitting on top of a stack "Topper" just to satisfy a string compare.
		if not hit then
			return 0
		end
		local inst = hit.Instance
		if not inst:GetAttribute("IsCrate")
			and inst.Name ~= "Base" and inst.Name ~= "Topper" then
			return 0
		end
		return inst.Position.Y + inst.Size.Y / 2
	end

	-- A lever belongs to ONE stack height, not to a minimum.
	--
	-- `standLevel` is how many crates you stand on to work it: 1 for A, 2 for B. The height and
	-- the gate are both derived from that, so they cannot drift apart, and they follow the real
	-- cube size automatically. Standing higher than the lever no longer works -- a 2-stack
	-- cannot reach down and flip A -- which is what makes each lever cost its own cubes.
	local CUBE = Mapping.cubeStuds()
	local LEVEL_TOLERANCE = CUBE * 0.45       -- comfortably inside one cube either way

	local function standTopFor(level)
		return level * CUBE
	end

	local function buildLever(spec)
		local inward = (spec.side == "left") and 1 or -1
		local level = spec.standLevel or 1
		local standTop = standTopFor(level)
		-- chest height above the crate you are standing on
		local y = standTop + 2.4
		-- flush against the side wall's inner face, not on a block jutting into the bay
		local face = (spec.side == "left") and SIDE_FACE or (Config.BayWidth - SIDE_FACE)
		local x = face + inward * 0.18
		local z = cellCenter(i, spec.cell[1], spec.cell[2]).Z

		local lv = {id = spec.id, phase = DORMANT, level = level, standTop = standTop}

		-- A backplate bolted to the wall, 0.36 studs proud of it -- the wall is the housing now.
		lv.mount = newPart("Lever" .. spec.id .. "Plate", Vector3.new(0.36, 3.2, 3.2),
			Vector3.new(x, y, z), Color3.fromRGB(40, 40, 46), Enum.Material.DiamondPlate, folder)
		lv.beacon = newPart("Lever" .. spec.id .. "Beacon", Vector3.new(0.5, 0.5, 2.8),
			Vector3.new(x + inward * 0.2, y + 2.1, z), Color3.fromRGB(34, 34, 38),
			Enum.Material.Neon, folder, {CanQuery = false})

		-- A painted band on the wall at the height you have to be standing at, so the level a
		-- lever wants is readable from across the bay instead of guessed at.
		lv.stripe = newPart("Lever" .. spec.id .. "Level", Vector3.new(0.14, 0.35, 5.5),
			Vector3.new(face + inward * 0.1, standTop + 0.2, z),
			Color3.fromRGB(120, 120, 130), Enum.Material.Neon, folder, {CanQuery = false})

		lv.pivot = Vector3.new(x + inward * 0.45, y - 1.0, z)
		lv.handle = newPart("Lever" .. spec.id .. "Handle", Vector3.new(0.45, HANDLE_LEN, 0.45),
			lv.pivot, Color3.fromRGB(190, 58, 52), Enum.Material.Metal, folder)
		lv.knob = newPart("Lever" .. spec.id .. "Knob", Vector3.new(0.85, 0.85, 0.85),
			lv.pivot, Color3.fromRGB(235, 80, 68), Enum.Material.SmoothPlastic, folder,
			{Shape = Enum.PartType.Ball})

		-- Swing the handle out into the bay, not along it. Rotating about X tipped the lever
		-- down the lane, which is why the levers looked like they were aimed at nothing in
		-- particular -- a wall lever has to flip toward whoever is standing in front of it.
		-- About Z, +Y turns toward -X, so the left wall (inward = +1) needs the negative.
		function lv.setAngle(deg)
			local base = CFrame.new(lv.pivot) * CFrame.Angles(0, 0, math.rad(-inward * deg))
			lv.handle.CFrame = base * CFrame.new(0, HANDLE_LEN / 2, 0)
			lv.knob.CFrame = base * CFrame.new(0, HANDLE_LEN, 0)
		end
		lv.setAngle(0)

		lv.light = Instance.new("PointLight")
		lv.light.Range = 18
		lv.light.Brightness = 0
		lv.light.Color = Color3.fromRGB(90, 255, 130)
		lv.light.Parent = lv.mount

		lv.levelText = ("LEVEL %d  (%s)"):format(level,
			level == 1 and "1 crate" or (level .. " crates stacked"))
		lv.label = addLabel(folder, ("LEVER %s  -  %s"):format(spec.id, lv.levelText),
			Vector3.new(x + inward * 1.2, y + 3.6, z), Color3.fromRGB(130, 130, 140))

		-- A real wall lever: climb to it and hold E. ProximityPrompt gives the hold-to-act UI
		-- and the key binding for free, and brushing past no longer throws anything -- the old
		-- Touched version fired the moment any body part grazed the housing.
		local prompt = Instance.new("ProximityPrompt")
		prompt.ActionText = "Flip Lever"
		prompt.ObjectText = "Lever " .. spec.id
		prompt.KeyboardKeyCode = Enum.KeyCode.E
		prompt.HoldDuration = Config.SawLeverHoldSeconds
		prompt.MaxActivationDistance = 9
		prompt.RequiresLineOfSight = false
		prompt.Enabled = false
		prompt.Parent = lv.mount
		lv.prompt = prompt

		prompt.Triggered:Connect(function(player)
			local ch = player.Character
			local hum = ch and ch:FindFirstChildOfClass("Humanoid")
			if not hum or hum.Health <= 0 or isGhost(ch) or lv.phase ~= ARMED then
				return
			end
			-- Same level, not "at least this high". Standing on a taller stack is as wrong as
			-- standing on the floor: each lever costs its own crates, and that is the whole
			-- cube budget argument this bay is built on.
			if math.abs(supportHeight(ch) - lv.standTop) > LEVEL_TOLERANCE then
				return
			end
			if lv.onThrow then
				lv.onThrow()
			end
		end)
		return lv
	end

	local levers = {}
	for _, spec in ipairs(info.levers or {}) do
		levers[spec.id] = buildLever(spec)
	end
	local leverA, leverB = levers.A, levers.B

	local function setPhase(lv, phase)
		if not lv then
			return
		end
		lv.phase = phase
		if lv.prompt then
			lv.prompt.Enabled = (phase == ARMED)
		end
		if phase == DORMANT then
			lv.mount.Color = Color3.fromRGB(40, 40, 46)
			lv.beacon.Color = Color3.fromRGB(34, 34, 38)
			lv.light.Brightness = 0
			lv.label.Text = "LEVER " .. lv.id .. "  -  LOCKED"
			lv.label.TextColor3 = Color3.fromRGB(125, 125, 135)
			lv.setAngle(0)
		elseif phase == ARMED then
			lv.mount.Color = Color3.fromRGB(46, 72, 50)
			lv.label.Text = "LEVER " .. lv.id .. "  -  LIVE"
			lv.label.TextColor3 = Color3.fromRGB(120, 255, 150)
		else
			lv.light.Color = Color3.fromRGB(110, 180, 255)
			lv.light.Brightness = 1.3
			lv.mount.Color = Color3.fromRGB(48, 60, 76)
			lv.beacon.Color = Color3.fromRGB(90, 170, 255)
			lv.label.Text = "LEVER " .. lv.id .. "  -  THROWN"
			lv.label.TextColor3 = Color3.fromRGB(130, 200, 255)
			task.spawn(function()
				for d = 0, 70, 7 do
					lv.setAngle(d)
					task.wait(0.02)
				end
			end)
		end
	end

	----------------------------------------------------------------
	-- On-screen objective. Pushed whenever the state changes, and a few times a second while
	-- the wall is moving so the countdown stays live. Sending nil clears the HUD, so a player
	-- standing outside the bay isn't told to do anything.
	----------------------------------------------------------------
	local lastPush = 0

	local function pushObjective()
		lastPush = os.clock()
		if not running and not state.solved then
			publishObjective(i, nil, 0)
			return
		end

		local p = {title = "BAY 1  -  SAW WALL"}

		-- A checklist, not a single line. Both levers are always shown with their state and
		-- the level each one wants, so the plan is readable at a glance instead of being
		-- revealed one step at a time.
		local function leverLine(lv, label)
			if not lv then
				return nil
			end
			local mark = (lv.phase == THROWN) and "[x]"
				or (lv.phase == ARMED) and "[ ]" or "[-]"
			local statusText = (lv.phase == THROWN) and "done"
				or (lv.phase == ARMED) and "ready" or "locked"
			return ("%s  LEVER %s  -  %s  -  %s"):format(mark, lv.id, label, statusText)
		end
		p.steps = {
			leverLine(leverA, "stand on 1 crate, kill the blades"),
			leverLine(leverB, "stand on 2 stacked, drop the wall"),
		}

		if state.solved then
			p.task = "CLEARED"
			p.hint = "The wall is down -- walk out over it."
			p.tone = "ok"
		elseif bladesLive then
			p.task = "LEVER A  -  KILL THE BLADES"
			p.hint = "Left wall, middle row. Stand on ONE crate -- not two -- and hold E."
			p.tone = "danger"
		else
			p.task = "LEVER B  -  STOP THE WALL"
			p.hint = "Right wall by the entrance. Stand on the stacked PAIR and hold E."
			p.tone = "warn"
		end
		p.note = bladesLive
			and "Blades live: crates cannot be dropped in front of them, and the wall cuts straight through."
			or "Blades dead: the next crate in the lane jams the wall, once, for "
				.. Config.SawWallStallSeconds .. "s."

		if running and not state.solved then
			if stallCrate then
				p.timerLabel = "STALLED"
				p.timer = math.max(0, Config.SawWallStallSeconds - (os.clock() - stallStart))
				p.timerTone = "ok"
			else
				p.timerLabel = "WALL REACHES YOU IN"
				p.timer = math.max(0, (wallZ - WALL_END) / studsPerSecond)
			end
		end

		if os.clock() < flashUntil then
			p.flash = flashText
		end
		publishObjective(i, p, 0)
	end

	----------------------------------------------------------------
	-- run / reset. The obstacle stays dormant until someone is actually inside, which also
	-- gives the reset for free: when the bay empties unsolved, everything goes back.
	-- (`running` is declared further up, with the wall state.)
	----------------------------------------------------------------
	local function playersInBay()
		local found = {}
		for _, pl in ipairs(session.runners) do
			local ch = pl.Character
			local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
			local hum = ch and ch:FindFirstChildOfClass("Humanoid")
			if hrp and hum and hum.Health > 0 and not isGhost(ch) then
				local p = hrp.Position
				if p.Z > z0 and p.Z < zEnd and p.X > -2 and p.X < Config.BayWidth + 2 and p.Y > -8 then
					table.insert(found, {character = ch, humanoid = hum, position = p})
				end
			end
		end
		return found
	end

	local function armRun()
		running = true
		sunk = false
		frame.CanCollide = true
		wallZ = WALL_START
		spin = 0
		lastTick = os.clock()
		setBladesLive(true)
		placeWall(wallZ)
		slideGate(entryGate, true)
		setPhase(leverA, ARMED)
		setPhase(leverB, DORMANT)
		pushObjective()
	end

	local function resetRun()
		running = false
		sunk = false
		stallSpent, stallCrate, stallStart = {}, nil, 0
		frame.CanCollide = true
		wallZ = WALL_START
		setBladesLive(true)
		placeWall(wallZ)
		sparks.Transparency = 1
		slideGate(entryGate, false)
		setPhase(leverA, DORMANT)
		setPhase(leverB, DORMANT)
		pushObjective()
	end

	-- Debug/GameState reset. A switch-driven bay cannot be un-solved by clearing cells, since
	-- its CellsChanged handler returns early, so without this hook the bay stays open for the
	-- rest of the session and the demo is a one-shot.
	function state.reset()
		resetRun()
	end

	if leverA then
		function leverA.onThrow()
			setPhase(leverA, THROWN)
			setBladesLive(false)
			setPhase(leverB, ARMED)
			-- the operator may already have a cube down that the guard turned away; with the
			-- blades dead it is allowed now, so the game owes them that crate
			BlockSync.retryRejected(folder.Parent)
			pushObjective()
			print("[HazardManager] saw wall: Lever A thrown, blades dead")
		end
	end

	if leverB then
		function leverB.onThrow()
			setPhase(leverB, THROWN)
			running = false
			sparks.Transparency = 1
			sinkWall()
			print("[HazardManager] saw wall: Lever B thrown, wall halted and lowering")
			if state.setSolved then
				state.setSolved(true)
			end
			pushObjective()
		end
	end

	-- No floating notice part any more: `flashText` already rides the next objective push and
	-- the HUD raises it as a toast, which is the same information somewhere you are actually
	-- looking. The billboard was a second copy of it hanging in the air above the saws.
	function showNotice(text)
		flashText, flashUntil = text, os.clock() + 2.5
	end

	placeWall(WALL_START)
	setPhase(leverA, DORMANT)
	setPhase(leverB, DORMANT)

	task.spawn(function()
		while folder.Parent do
			local occupants = playersInBay()

			if state.solved then
				-- cleared for good; leave the exit open and the wall where it stopped
			elseif not running then
				if #occupants > 0 then
					armRun()
				end
			elseif #occupants == 0 then
				resetRun()
			else
				local now = os.clock()
				-- clamp, so a hitch or a resumed session can't teleport the wall forward
				local dt = math.min(now - lastTick, 0.25)
				lastTick = now

				if bladesLive then
					spin += math.rad(520) * dt
				end

				local blocker = crateInPath(wallZ)
				local advance = studsPerSecond * dt
				if blocker and not bladesLive and not stallSpent[blocker] then
					if stallCrate ~= blocker then
						stallCrate, stallStart = blocker, now
					end
					local left = Config.SawWallStallSeconds - (now - stallStart)
					if left > 0 then
						advance = 0 -- jammed: no spinning blade left to cut with
						showNotice(string.format("WALL STALLED - %ds", math.ceil(left)))
					else
						-- that crate's reprieve is used up; the wall grinds past it
						stallSpent[blocker] = true
						stallCrate = nil
					end
				end
				-- sparks while live blades are cutting through a crate they cannot stop on
				sparks.Transparency = (blocker and bladesLive) and (0.25 + math.random() * 0.5) or 1

				wallZ = math.max(wallZ - advance, WALL_END)
				placeWall(wallZ)

				for _, o in ipairs(occupants) do
					-- past the near face (tunnelled through), or pinned on the entry gate
					if o.position.Z > wallZ + 0.8 or wallZ <= WALL_END + 0.05 then
						o.humanoid.Health = 0
					end
				end
			end

			-- pulse whichever lever is the live target, and tell a player who is standing
			-- near it on too short a stack why nothing is happening. Lever B is deliberately
			-- mounted high enough that a single crate cannot even make contact, so without
			-- this hint the obstacle just reads as broken.
			for _, lv in pairs(levers) do
				if lv.phase == ARMED then
					local k = 0.5 + 0.5 * math.sin(os.clock() * 4)
					lv.light.Brightness = 1.2 + k * 2.2
					lv.beacon.Color = Color3.fromRGB(40 + 90 * k, 150 + 105 * k, 60 + 70 * k)

					-- Say WHICH WAY you are wrong. "Stack higher" was a lie half the time:
					-- standing on a 2-stack at lever A now fails, and being told to stack
					-- higher would send you the wrong direction entirely.
					local verdict = nil
					for _, o in ipairs(occupants) do
						if (o.position - lv.mount.Position).Magnitude < 8 then
							local h = supportHeight(o.character)
							local d = h - lv.standTop
							if d < -LEVEL_TOLERANCE then
								verdict = (h < 0.5) and "NEED " .. lv.level
									.. (lv.level == 1 and " CRATE" or " CRATES")
									or "STACK HIGHER"
							elseif d > LEVEL_TOLERANCE then
								verdict = "TOO HIGH  -  STAND ONE LOWER"
							end
						end
					end
					if verdict then
						lv.label.Text = "LEVER " .. lv.id .. "  -  " .. verdict
						lv.label.TextColor3 = Color3.fromRGB(255, 150, 90)
					else
						lv.label.Text = "LEVER " .. lv.id .. "  -  LIVE  (HOLD E)"
						lv.label.TextColor3 = Color3.fromRGB(120, 255, 150)
					end
				end
			end

			-- (the notice used to be expired here; it is a HUD toast now and expires itself)
			if os.clock() - lastPush > 0.2 then
				pushObjective()
			end

			task.wait(TICK)
		end
	end)

	function state.onSolved() end
end

-- VOID: the floor is gone over `coverRows`, and the gap is deliberately wider than a jump --
-- so the crates are not a shortcut across, they ARE the bridge. The arithmetic that makes that
-- true: stock JumpHeight 7.2 and WalkSpeed 16 under Gravity 196.2 give 0.54s of air and 8.67
-- studs of flat travel, while the uncovered rows span 16. Mounting the far side higher, or
-- widening the gap further, would both be redundant -- one cell of void is already unjumpable.
--
-- Nothing in this bay is lethal except the drop, which satisfies the safe-footing rule for
-- free: the bridge you built is the only place there is to stand.
BUILDERS.Void = function(i, folder, info, state)
	local bay = RunControl.warehouse():FindFirstChild(string.format("Bay%02d", i))
	local floor = bay and bay:FindFirstChild("Floor")
	local rows = info.coverRows or {0, 1, 2}

	local z0 = bayZStart(i)
	local wholeBay = #rows >= Config.BayRows
	-- The near lip is the bay entrance; the far lip is wherever solid ground resumes. Both are
	-- derived from `coverRows`, so changing that one field moves the geometry with it.
	local nearZ = z0
	local farZ = wholeBay and (z0 + Config.BayDepth)
		or (z0 + (math.max(table.unpack(rows)) + 1) * CELL)
	local span = farZ - nearZ
	local midZ = (nearZ + farZ) / 2
	local W = Config.BayWidth
	local depth = Config.VoidShaftDepth

	local AMBER = Color3.fromRGB(255, 176, 40)
	local GREEN = Color3.fromRGB(120, 240, 140)
	local SHAFT = Color3.fromRGB(14, 14, 18)

	-- The crates here ARE the floor, so they sit flush with it rather than on top of it. One
	-- cube of sink: without it the bridge stands a full cube proud of the walkway and crossing
	-- the gap means hopping up onto every slab and back down again, which is not what "the
	-- blocks are the bridge" means.
	bay:SetAttribute("CrateSink", Mapping.cubeStuds())

	----------------------------------------------------------------
	-- Cut the baked floor back so only the rows outside `coverRows` keep solid ground.
	-- Absolute rather than relative, so re-running the builder is idempotent.
	----------------------------------------------------------------
	if floor then
		if wholeBay then
			floor.Transparency = 1
			floor.CanCollide = false
			floor.CanTouch = false
		else
			local keptDepth = Config.BayDepth - span
			floor.Size = Vector3.new(W, 1, keptDepth)
			floor.CFrame = CFrame.new(W / 2, -0.5, farZ + keptDepth / 2)
		end
	end

	----------------------------------------------------------------
	-- The shaft. Purely presentational: the drop has to read as a drop from floor level, or
	-- the bay looks like a texture glitch rather than somewhere you can die. Every piece here
	-- is CanCollide = false so nothing catches a falling player half way down.
	----------------------------------------------------------------
	local function shaftWall(name, size, pos)
		newPart(name, size, pos, SHAFT, Enum.Material.Slate, folder, {CanQuery = false})
	end
	shaftWall("ShaftLeft", Vector3.new(0.5, depth, span), Vector3.new(0.25, -depth / 2, midZ))
	shaftWall("ShaftRight", Vector3.new(0.5, depth, span), Vector3.new(W - 0.25, -depth / 2, midZ))
	shaftWall("ShaftFar", Vector3.new(W, depth, 0.5), Vector3.new(W / 2, -depth / 2, farZ - 0.25))
	shaftWall("ShaftNear", Vector3.new(W, depth, 0.5), Vector3.new(W / 2, -depth / 2, nearZ + 0.25))
	shaftWall("ShaftFloor", Vector3.new(W, 0.5, span), Vector3.new(W / 2, -depth, midZ))

	-- Cut-edge fascia: shows the thickness of the slab you are standing on, at both lips.
	local function fascia(name, size, pos)
		newPart(name, size, pos, Color3.fromRGB(78, 80, 88), Enum.Material.Metal, folder,
			{CanQuery = false})
	end
	fascia("EdgeNear", Vector3.new(W, 1.4, 0.7), Vector3.new(W / 2, -0.7, nearZ + 0.35))
	if not wholeBay then
		fascia("EdgeFar", Vector3.new(W, 1.4, 0.7), Vector3.new(W / 2, -0.7, farZ - 0.35))
	end
	fascia("EdgeLeft", Vector3.new(0.7, 1.4, span), Vector3.new(0.35, -0.7, midZ))
	fascia("EdgeRight", Vector3.new(0.7, 1.4, span), Vector3.new(W - 0.35, -0.7, midZ))

	-- Hazard striping on both lips. These are the parts that go green on solve, so they are
	-- the bay's whole state readout -- amber means the gap is still open.
	local lips = {}
	local DASH = 2
	for x = 0, W - DASH, DASH * 2 do
		local function dash(name, z)
			local p = newPart(name, Vector3.new(DASH, 0.22, 0.9),
				Vector3.new(x + DASH / 2, 0.11, z), AMBER, Enum.Material.Neon, folder,
				{CanQuery = false})
			table.insert(lips, p)
		end
		dash("LipNear", nearZ + 0.45)
		if not wholeBay then
			dash("LipFar", farZ - 0.45)
		end
	end

	-- Warning lights down the shaft, so the depth is legible rather than just dark. Range is
	-- capped just under the spacing so each one reads as a separate marker going down and none
	-- of them spills back up through the opening to light the bay floor from below.
	for y = -Config.VoidLightSpacing, -depth + 4, -Config.VoidLightSpacing do
		local anchor = newPart("ShaftLight", Vector3.new(0.4, 0.4, 0.4),
			Vector3.new(W / 2, y, midZ), nil, nil, folder, {Transparency = 1, CanQuery = false})
		local l = Instance.new("PointLight")
		l.Color = Color3.fromRGB(255, 70, 40)
		l.Brightness = 1.1
		l.Range = Config.VoidLightSpacing - 2
		l.Parent = anchor
	end

	----------------------------------------------------------------
	-- Kill plane. Sits above the shaft floor so the death happens in open air rather than on
	-- contact with scenery, and spans wider than the bay so stepping off sideways still lands
	-- in it.
	----------------------------------------------------------------
	local catcher = newPart("VoidCatcher", Vector3.new(W + 12, 2, span + 4),
		Vector3.new(W / 2, -depth + 4, midZ), Color3.fromRGB(0, 0, 0),
		Enum.Material.SmoothPlastic, folder, {Transparency = 1})
	catcher.CanTouch = true
	catcher.Touched:Connect(function(hit)
		local _, hum = characterFrom(hit)
		if hum and hum.Health > 0 then
			hum.Health = 0
		end
	end)

	----------------------------------------------------------------
	-- Placement holograms: a crate-sized ghost at each solveCell, so the player can read the
	-- cell to call out instead of guessing it off the debug grid. One disappears as its cell
	-- is filled, which makes "what is left to do" visible in world as well as on the HUD.
	--
	-- Amber rather than tinted to a required colour: any block fits, so a coloured ghost would
	-- be telling the operator to go and find a cube they do not need.
	----------------------------------------------------------------
	local tint = AMBER
	local ghosts = {}
	for _, sc in ipairs(info.solveCells or {}) do
		local col, row = sc[1], sc[2]
		local c = cellCenter(i, col, row)
		local box = newPart("GhostCrate", Vector3.new(4, 4, 4), Vector3.new(c.X, 2, c.Z),
			tint, Enum.Material.ForceField, folder, {Transparency = 0.55, CanQuery = false})
		local label = addLabel(folder, string.format("%s  (%d,%d)", blockReq(info.level), col, row),
			Vector3.new(c.X, 6.5, c.Z), tint)
		ghosts[col .. "," .. row] = {box = box, label = label}
	end

	local function showGhost(key, visible)
		local g = ghosts[key]
		if not g then
			return
		end
		g.box.Transparency = visible and 0.55 or 1
		g.label.Visible = visible
	end

	----------------------------------------------------------------
	-- Objective HUD. No countdown: this bay has no clock of its own, and inventing one here
	-- would be a mechanic rather than an obstacle. The task line is the cell callout instead,
	-- which is exactly what the operator needs shouted at them.
	----------------------------------------------------------------
	local filled = {}

	local function nextNeeded()
		for _, sc in ipairs(info.solveCells or {}) do
			local key = sc[1] .. "," .. sc[2]
			if not filled[key] then
				return sc, key
			end
		end
		return nil
	end

	-- One description of how the bay looks, driven off what has actually landed rather than
	-- off state.solved -- buildBay's setSolved only calls onSolved on the way IN, so hanging
	-- the lip colour off that left the bay still showing "cleared" after a crate was lifted
	-- back out of it.
	local function refresh()
		local complete = (nextNeeded() == nil)
		for _, p in ipairs(lips) do
			p.Color = complete and GREEN or AMBER
		end
		for key in pairs(ghosts) do
			showGhost(key, not filled[key])
		end
	end

	-- No occupancy test here: publishObjective only ever reaches players standing in this bay,
	-- and clears the rest, so the payload is built unconditionally.
	local function pushObjective()
		local p = {title = string.format("BAY %d  -  THE VOID", i)}
		if state.solved then
			p.task = "CLEARED"
			p.hint = "The bridge is in -- jump across to the exit."
			p.tone = "ok"
		else
			local sc = nextNeeded()
			local remaining = 0
			for _, s2 in ipairs(info.solveCells or {}) do
				if not filled[s2[1] .. "," .. s2[2]] then
					remaining += 1
				end
			end
			if sc then
				p.task = string.format("%s  ->  COL %d, ROW %d",
					blockReq(info.level), sc[1], sc[2])
			else
				p.task = blockReq(info.level)
			end
			p.hint = (remaining > 1)
				and string.format("No floor for %d studs. Call out both cells -- the crates are the bridge.", span)
				or "One more block, then jump from block to block."
			p.tone = (remaining > 1) and "danger" or "warn"
		end
		publishObjective(i, p, CELL)
	end

	-- Track what has actually landed, for the holograms and the callout. Solve detection
	-- itself stays where it belongs -- checkSolved owns state.solved for a placement bay.
	BlockSync.CellsChanged:Connect(function(bayModel, cellsList)
		if bayModel ~= bay then
			return
		end
		filled = {}
		for _, c in ipairs(cellsList) do
			if (c.level or 1) >= info.level then
				filled[c.col .. "," .. c.row] = true
			end
		end
		refresh()
	end)

	-- Both hooks share refresh() so there is exactly one description of how the bay looks.
	state.onSolved = refresh

	function state.reset()
		filled = {}
		refresh()
	end

	-- The HUD follows occupancy: padded toward the entrance so the callout is already on
	-- screen while the player is still on the approach catwalk, reading the gap. Ends with the
	-- folder, like every other loop here: a rebuild (or the round's map being destroyed) used
	-- to leave this one running forever.
	task.spawn(function()
		while folder.Parent do
			pushObjective()
			task.wait(0.2)
		end
	end)
end

-- LASER WALK: the whole 4x3 grid is lethal, and the single yellow crate is the only thing that
-- switches a cell off. You cross by having the operator walk that ONE crate ahead of you, cell
-- by cell, along a route only they can see.
--
-- The three rules that make it a puzzle rather than a chore:
--
--   * A cell holding the crate is safe. Nothing else is, ever.
--   * Only the NEXT cell of the route accepts the crate -- every other cell refuses the
--     delivery -- so the operator cannot shortcut straight down a column.
--   * The cell the crate just left stays safe for Config.LaserCooldownSeconds, counted from
--     the moment the crate SEATS in its new cell, not from when it was lifted. That matters:
--     one arm move is ~11s of flight, so a cooldown started at lift would be spent before the
--     crate even landed, and the bay would be a race against the arm instead of a race across
--     the floor.
--
-- The route is generated per run and the player can't see it, so the operator's overlay is
-- load-bearing: Bridge.send publishes the next cell to the physical side every time it changes.
BUILDERS.LaserWalk = function(i, folder, info, state)
	-- The cube is a TOKEN here, not an object. The operator slides a real cube across the real
	-- mat and the matching tile goes quiet; the player walks on the floor, because the pad is
	-- what kills and a safe pad does not. A crate standing in the cell was scenery -- and
	-- scenery that reads as "climb me" in the one bay where climbing is not the point.
	-- (the attribute is set just below, once `bay` is in scope)

	local bay = RunControl.warehouse():FindFirstChild(string.format("Bay%02d", i))
	if bay then
		bay:SetAttribute("VirtualCrates", true)
	end
	local COLS, ROWS = Config.BayCols, Config.BayRows

	-- Arming has to trigger from the APPROACH, not from inside the bay. Every cell is lethal
	-- until the first crate lands, so a bay that only armed once somebody was standing in it
	-- could only ever be armed by somebody dying in it. One cell of slack puts the player on
	-- the catwalk, where they can read the callout and wait for the operator's first placement.
	local ARM_PAD = CELL

	local RED = Color3.fromRGB(255, 0, 0)
	local AMBER = Color3.fromRGB(255, 176, 40)
	local GREEN = Color3.fromRGB(120, 240, 140)

	local function keyOf(c, r)
		return c .. "," .. r
	end

	----------------------------------------------------------------
	-- Per-cell hazard. The floor pad is the authoritative killer -- it is the thing you
	-- actually stand on, so it cannot be stepped over -- and the crossed beams above it are
	-- what make the cell legible from across the bay.
	----------------------------------------------------------------
	local cells = {}
	for col = 0, COLS - 1 do
		for row = 0, ROWS - 1 do
			local c = cellCenter(i, col, row)
			local pad = newPart("CellPad", Vector3.new(CELL - 0.5, 0.12, CELL - 0.5),
				Vector3.new(c.X, 0.07, c.Z), RED, Enum.Material.Neon, folder,
				{Transparency = 0.7, CanQuery = false})
			makeLethalPart(pad)

			local beams = {}
			for _, y in ipairs({1.6, 4.4, 7.2}) do
				local across = newPart("CellBeam", Vector3.new(CELL - 0.2, 0.16, 0.16),
					Vector3.new(c.X, y, c.Z), RED, Enum.Material.Neon, folder,
					{Transparency = 0.15, CanQuery = false})
				local along = newPart("CellBeam", Vector3.new(0.16, 0.16, CELL - 0.2),
					Vector3.new(c.X, y, c.Z), RED, Enum.Material.Neon, folder,
					{Transparency = 0.15, CanQuery = false})
				makeLethalPart(across)
				makeLethalPart(along)
				table.insert(beams, across)
				table.insert(beams, along)
			end

			-- The number goes ON THE TILE. How long until the ground under you turns lethal is
			-- the most urgent thing in this bay, and a line in a panel at the top of the screen
			-- is the wrong place for it -- you are looking at your feet, picking the next step.
			-- SurfaceGui rather than Billboard: a flat number reads as painted floor marking,
			-- and a Billboard adorned to a part has already failed to render once here.
			local sg = Instance.new("SurfaceGui")
			sg.Face = Enum.NormalId.Top
			sg.LightInfluence = 0
			sg.PixelsPerStud = 36
			sg.Adornee = pad
			sg.Enabled = false
			sg.Parent = pad
			local count = Instance.new("TextLabel")
			count.AnchorPoint = Vector2.new(0.5, 0.5)
			count.Position = UDim2.new(0.5, 0, 0.5, 0)
			count.Size = UDim2.new(0.7, 0, 0.7, 0)
			count.BackgroundTransparency = 1
			count.Font = Enum.Font.GothamBold
			count.TextScaled = true
			count.TextColor3 = Color3.fromRGB(20, 14, 6)
			count.TextStrokeTransparency = 0.35
			count.Rotation = -90       -- a Top-face GUI's axes run across the bay
			count.Text = ""
			count.Parent = sg

			cells[keyOf(col, row)] = {col = col, row = row, pad = pad, beams = beams,
				live = true, countGui = sg, count = count}
		end
	end

	-- A cell is only ever one of these three, and the pad colour says which from anywhere.
	local LIVE, SAFE, COOLING = "live", "safe", "cooling"
	local function setCellState(cell, mode, flash)
		cell.live = (mode == LIVE)
		if cell.countGui then
			cell.countGui.Enabled = (mode == COOLING)
		end
		for _, b in ipairs(cell.beams) do
			b:SetAttribute("Live", cell.live)
			b.Transparency = cell.live and 0.15 or 1
		end
		cell.pad:SetAttribute("Live", cell.live)
		if mode == LIVE then
			cell.pad.Color = RED
			cell.pad.Transparency = 0.7
		elseif mode == SAFE then
			cell.pad.Color = GREEN
			cell.pad.Transparency = 0.45
		else
			cell.pad.Color = AMBER
			-- the pulse IS the warning: it speeds up as the cooldown runs out
			cell.pad.Transparency = flash and 0.25 or 0.6
		end
	end

	----------------------------------------------------------------
	-- Route generation. A simple (non-repeating) orthogonal walk that starts on the entrance
	-- row and finishes on the exit row, so the bay is genuinely crossed. Randomised DFS with
	-- backtracking -- the grid is 12 cells, so this is instant and always finds one.
	----------------------------------------------------------------
	local function shuffled(t)
		for a2 = #t, 2, -1 do
			local b2 = math.random(a2)
			t[a2], t[b2] = t[b2], t[a2]
		end
		return t
	end

	local function routeOfLength(target)
		local best, path, seen = nil, {}, {}

		local function dfs(col, row)
			if best then
				return
			end
			if #path == target then
				if row == ROWS - 1 then
					best = table.clone(path)
				end
				return
			end
			for _, d in ipairs(shuffled({{1, 0}, {-1, 0}, {0, 1}, {0, -1}})) do
				local nc, nr = col + d[1], row + d[2]
				local k = keyOf(nc, nr)
				if nc >= 0 and nc < COLS and nr >= 0 and nr < ROWS and not seen[k] then
					seen[k] = true
					table.insert(path, {nc, nr})
					dfs(nc, nr)
					table.remove(path)
					seen[k] = nil
					if best then
						return
					end
				end
			end
		end

		for _, sc in ipairs(shuffled({0, 1, 2, 3})) do
			path, seen = {{sc, 0}}, {[keyOf(sc, 0)] = true}
			dfs(sc, 0)
			if best then
				return best
			end
		end
		return nil
	end

	local function generateRoute()
		local lo, hi = Config.LaserRouteMin, Config.LaserRouteMax
		-- try the requested length first, then shorter, so an unlucky target can't leave the
		-- bay unplayable
		local want = math.random(lo, hi)
		for len = want, lo, -1 do
			local r = routeOfLength(len)
			if r then
				return r
			end
		end
		return routeOfLength(lo) or {{1, 0}, {1, 1}, {1, 2}}
	end

	----------------------------------------------------------------
	-- Run state
	----------------------------------------------------------------
	local route, step = nil, 0      -- step = how many route cells the crate has occupied
	local blockKey = nil            -- cell the crate is in; survives the crate being in flight
	local cooling = {}              -- [cellKey] = os.clock() when it goes live again
	local lastVacated = nil         -- the cell the crate just left: where the player is standing
	local running = false
	local flashText, flashUntil = nil, 0

	-- Optional: the physical side's overlay. Bridge only exists on branches that have the real
	-- robot link, and may be offline, so this is best-effort and the HUD always carries the
	-- same information for solo play.
	-- ARCADE: the obby's own Bridge is gone and ServerScriptService.Bridge is the core's socket,
	-- so this goes through the arcade's handle on it, ServerStorage.Shared.Bridge (send +
	-- isOnline, no isConnected).
	local Bridge
	do
		local shared = ServerStorage:FindFirstChild("Shared")
		local mod = shared and shared:FindFirstChild("Bridge")
		if mod then
			local ok, result = pcall(require, mod)
			if ok then
				Bridge = result
			end
		end
	end

	local function nextCell()
		return route and route[step + 1] or nil
	end

	local lastEmitted = nil
	local function emitTarget()
		if not Bridge or not Bridge.send then
			return
		end
		local ok = pcall(function()
			if Bridge.isOnline and not Bridge.isOnline() then
				return
			end
			local n = nextCell()
			local sig = n and (n[1] .. "," .. n[2] .. "@" .. (step + 1)) or "done"
			if sig == lastEmitted then
				return
			end
			lastEmitted = sig
			Bridge.send({
				t = "target",
				bay = i,
				level = info.level,
				col = n and n[1] or nil,
				row = n and n[2] or nil,
				step = n and (step + 1) or nil,
				of = route and #route or nil,
				done = (n == nil),
			})
		end)
		if not ok then
			lastEmitted = nil
		end
	end

	local function armRun()
		running = true
		route = generateRoute()
		step = 0
		blockKey = nil
		cooling = {}
		lastVacated = nil
		lastEmitted = nil
		local parts = {}
		for _, c in ipairs(route) do
			table.insert(parts, string.format("(%d,%d)", c[1], c[2]))
		end
		print(string.format("[HazardManager] laser walk: route of %d -> %s",
			#route, table.concat(parts, " ")))
		emitTarget()
	end

	local function disarm()
		running = false
		route = nil
		step = 0
		blockKey = nil
		cooling = {}
		lastVacated = nil
		lastEmitted = nil
		emitTarget()
	end

	----------------------------------------------------------------
	-- Placement guard: only the next cell of the route takes the crate. A refusal is parked by
	-- BlockSync rather than discarded -- the operator's cube is still on the real table, so the
	-- game owes them the placement the moment the answer changes.
	----------------------------------------------------------------
	if bay then
		BlockSync.setPlacementGuard(bay, function(cell)
			local n = nextCell()
			if not n then
				return false, "ROUTE COMPLETE"
			end
			if cell.col == n[1] and cell.row == n[2] then
				return true
			end
			return false, string.format("NOT THE NEXT CELL - COL %d, ROW %d", n[1], n[2])
		end)
	end

	BlockSync.PlacementRejected:Connect(function(bayModel, _, reason)
		if bayModel ~= bay then
			return
		end
		flashText, flashUntil = reason, os.clock() + 2.5
	end)

	----------------------------------------------------------------
	-- The crate SEATING is the only thing that advances the route and the only thing that
	-- starts a cooldown -- which is why this listens to CratePlaced and not CellsChanged.
	--
	-- CellsChanged fires the moment the operator's cube moves on the real table, which is
	-- about five seconds before the arm has carried the crate anywhere, and it fires for cells
	-- the placement guard went on to REFUSE. Driving the bay off it marked a cell the player
	-- could not actually stand on as safe, and started the cooldown on the cell under their
	-- feet while the new one was still in the air.
	--
	-- While the crate is in flight there is no safe cell to switch to, and blockKey
	-- deliberately keeps its old value through that gap -- that is what keeps the ground under
	-- the player safe until the new cell is genuinely ready.
	----------------------------------------------------------------
	BlockSync.CratePlaced:Connect(function(bayModel, cell)
		if bayModel ~= bay or not running then
			return
		end
		if (cell.level or 1) < info.level then
			return
		end
		local landed = keyOf(cell.col, cell.row)
		if landed == blockKey then
			return
		end

		if blockKey then
			cooling[blockKey] = os.clock() + Config.LaserCooldownSeconds
			lastVacated = blockKey
		end
		blockKey = landed

		local n = nextCell()
		if n and landed == keyOf(n[1], n[2]) then
			step += 1
			emitTarget()
		end
	end)

	----------------------------------------------------------------
	-- HUD
	----------------------------------------------------------------
	local function pushObjective()
		local p = {title = string.format("BAY %d  -  LASER WALK", i)}
		if state.solved then
			p.task = "CLEARED"
			p.hint = "The grid is down -- walk out."
			p.tone = "ok"
		elseif not running then
			p.task = "STEP ONTO THE GRID"
			p.hint = "Every cell is live. The crate is the only safe ground."
			p.tone = "danger"
		else
			local n = nextCell()
			if n then
				p.task = string.format("%s  ->  COL %d, ROW %d",
					blockReq(info.level), n[1], n[2])
				p.hint = string.format("Step %d of %d. Only that cell will take the crate.",
					step + 1, #route)
				p.tone = (step == 0) and "danger" or "warn"
			else
				p.task = "STAND ON THE LAST CELL"
				p.hint = "Route complete -- step onto the crate's cell to kill the grid."
				p.tone = "warn"
			end

			-- The countdown is specifically the cell the crate JUST left, because that is the
			-- one the player is standing on. Showing whichever cooldown expires soonest looked
			-- right until two overlapped, and then it counted down a cell already behind them
			-- -- reading 0.3s while the ground underfoot actually had a full 6s left.
			local at = lastVacated and cooling[lastVacated] or nil
			if at then
				local left = math.max(0, at - os.clock())
				-- Name the cell. "CELL GOES LIVE IN" with two cells cooling told you a number
				-- but not which ground it belonged to.
				local c, r = lastVacated:match("(%d+),(%d+)")
				p.timerLabel = c and ("COL %s, ROW %s GOES LIVE IN"):format(c, r)
					or "CELL GOES LIVE IN"
				p.timer = left
				p.timerTone = (left <= Config.LaserRearmWarnSeconds) and "danger" or "warn"
			end
		end

		if os.clock() < flashUntil then
			p.flash = flashText
		end
		publishObjective(i, p, CELL)
	end

	----------------------------------------------------------------
	-- Run loop
	----------------------------------------------------------------
	local function inCell(pos, col, row)
		local c = cellCenter(i, col, row)
		return math.abs(pos.X - c.X) <= CELL / 2 and math.abs(pos.Z - c.Z) <= CELL / 2
	end

	task.spawn(function()
		while folder.Parent do
			local occupants = occupantsOf(i, ARM_PAD)
			local now = os.clock()

			if state.solved then
				-- cleared for good; grid stays down
			elseif not running then
				if #occupants > 0 then
					armRun()
				end
			elseif #occupants == 0 then
				-- The bay emptied unsolved, which in practice means the player died on the
				-- grid. By design that regenerates the route and the operator has to carry the
				-- cube back to the new first cell -- so the HUD has to be loud about it.
				disarm()
			end

			if running and not state.solved then
				for k, at in pairs(cooling) do
					if now >= at then
						cooling[k] = nil
					end
				end

				for k, cell in pairs(cells) do
					if k == blockKey then
						setCellState(cell, SAFE)
					elseif cooling[k] then
						local left = cooling[k] - now
						local rate = (left <= Config.LaserRearmWarnSeconds) and 14 or 4
						setCellState(cell, COOLING, math.sin(now * rate) > 0)
						-- tenths under the warning threshold, so the last two seconds read as
						-- urgent rather than as a 2 that sits there
						if cell.count then
							cell.count.Text = (left <= Config.LaserRearmWarnSeconds)
								and ("%.1f"):format(math.max(0, left))
								or tostring(math.ceil(left))
							cell.count.TextColor3 = (left <= Config.LaserRearmWarnSeconds)
								and Color3.fromRGB(70, 10, 10) or Color3.fromRGB(20, 14, 6)
						end
					else
						setCellState(cell, LIVE)
					end
				end

				-- solved by standing on the final cell of the route, not merely by the crate
				-- arriving there -- the player has to actually make the last step
				if route and step >= #route and blockKey then
					local last = route[#route]
					for _, o in ipairs(occupants) do
						if inCell(o.position, last[1], last[2]) then
							state.setSolved(true)
							break
						end
					end
				end
			end

			pushObjective()
			task.wait(0.1)
		end
	end)

	function state.onSolved()
		-- staggered power-down, so the grid dies in a sweep rather than all at once
		task.spawn(function()
			local idx = 0
			for _, cell in pairs(cells) do
				setCellState(cell, SAFE)
				cell.pad.Transparency = 1
				idx += 1
				if idx % 3 == 0 then
					task.wait(0.03)
				end
			end
		end)
		emitTarget()
	end

	function state.reset()
		disarm()
		for _, cell in pairs(cells) do
			setCellState(cell, LIVE)
		end
	end
end

-- LAVA: rises on a timer and forces the player to keep moving. Blocks stand proud of the
-- maximum level, so a placed path stays dry. Solving freezes the rise (cryo) but the lava
-- itself stays lethal -- the blocks are the way across.
BUILDERS.Lava = function(i, folder, info, state)
	local maxY = 3.2 -- crates are 4 tall, so their tops stay dry
	local riseFor = (info.level == 2) and 12 or 20

	-- pool only covers `coverRows`, so the bay stays crossable on a 2-cube budget
	local rows = info.coverRows or {0, 1, 2}
	local poolStart = math.min(table.unpack(rows)) * CELL
	local poolDepth = (#rows) * CELL
	local centre = Vector3.new(Config.BayWidth / 2, 0,
		bayZStart(i) + poolStart + poolDepth / 2)

	local lava = newPart("Lava", Vector3.new(Config.BayWidth - 0.5, 0.6, poolDepth - 0.5),
		Vector3.new(centre.X, 0.2, centre.Z), Color3.fromRGB(255, 94, 12),
		Enum.Material.Neon, folder)
	makeLethal(lava, state)
	local poolWidth = Config.BayWidth - 0.5
	local poolSpan = poolDepth - 0.5

	local glow = Instance.new("PointLight")
	glow.Color = Color3.fromRGB(255, 130, 40)
	-- kept short-range on purpose: at Range 30 this flooded the neighbouring laser bay with
	-- orange and made the red beams read salmon
	glow.Range = 15
	glow.Brightness = 2
	glow.Parent = lava

	task.spawn(function()
		local t = 0
		while folder.Parent do
			if not state.solved then
				t = math.min(t + 0.1, riseFor)
				local h = (t / riseFor) * maxY
				lava.Size = Vector3.new(poolWidth, 0.6 + h, poolSpan)
				lava.CFrame = CFrame.new(centre.X, (0.6 + h) / 2 - 0.1, centre.Z)
			end
			task.wait(0.1)
		end
	end)

	function state.onSolved()
		lava.Color = Color3.fromRGB(255, 150, 60)
	end
end

-- CRUSHER ROOF: the whole ceiling of the bay descends. A stacked pair props it; the roof
-- halts ON the stack, leaving headroom for the player to walk under.
BUILDERS.CrusherRoof = function(i, folder, info, state)
	local centre = bayCenter(i)
	local startY = 15
	local propY = 8.2  -- rests on a stacked pair (4 + ~3.5)
	local crushY = 1.6 -- unsolved: comes all the way down

	local roof = newPart("CrusherRoof", Vector3.new(Config.BayWidth, 1.6, Config.BayDepth),
		Vector3.new(centre.X, startY, centre.Z), Color3.fromRGB(86, 60, 38),
		Enum.Material.Metal, folder, {CanCollide = true})

	-- spikes underneath so the threat reads instantly
	for col = 0, 3 do
		for row = 0, 2 do
			local cc = cellCenter(i, col, row)
			local spike = newPart("Spike", Vector3.new(0.8, 1.4, 0.8),
				Vector3.new(cc.X, startY - 1.4, cc.Z), Color3.fromRGB(60, 62, 68),
				Enum.Material.Metal, folder)
			spike:SetAttribute("Offset", -1.4)
		end
	end

	local spikes = {}
	for _, p in ipairs(folder:GetChildren()) do
		if p.Name == "Spike" then
			table.insert(spikes, p)
		end
	end

	local currentY = startY
	task.spawn(function()
		while folder.Parent do
			local goal = state.solved and propY or crushY
			currentY = currentY + (goal - currentY) * 0.015
			roof.CFrame = CFrame.new(centre.X, currentY, centre.Z)
			for _, s in ipairs(spikes) do
				s.CFrame = CFrame.new(s.Position.X, currentY - 1.5, s.Position.Z)
			end

			-- crush anything caught under a descending (unsolved) roof
			if not state.solved and currentY < 6 then
				for _, pl in ipairs(session.runners) do
					local ch = pl.Character
					local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
					local hum = ch and ch:FindFirstChildOfClass("Humanoid")
					if hrp and hum and hum.Health > 0 and not isGhost(ch) then
						local p = hrp.Position
						if math.abs(p.Z - centre.Z) < Config.BayDepth / 2
							and p.X > 0 and p.X < Config.BayWidth
							and p.Y < currentY then
							hum.Health = 0
						end
					end
				end
			end
			task.wait(0.05)
		end
	end)

	function state.onSolved() end
end

-- MOBS: Minecraft-style zombies spawn from two wall openings and chase the player. Blocks
-- seal the openings, which stops the spawns; the lane itself stays open to walk through.
local ZOMBIE_SKIN = Color3.fromRGB(106, 140, 79)
local ZOMBIE_SHIRT = Color3.fromRGB(58, 106, 118)
local ZOMBIE_PANTS = Color3.fromRGB(58, 62, 104)

local function buildZombie(spawnPos, parent)
	local m = Instance.new("Model")
	m.Name = "Zombie"

	local function limb(name, size, color)
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.Color = color
		p.Material = Enum.Material.SmoothPlastic
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = m
		return p
	end

	local root = limb("HumanoidRootPart", Vector3.new(2, 2, 1), ZOMBIE_SHIRT)
	root.Transparency = 1
	root.CFrame = CFrame.new(spawnPos)

	local torso = limb("Torso", Vector3.new(2, 2, 1), ZOMBIE_SHIRT)
	local head = limb("Head", Vector3.new(1.6, 1.6, 1.6), ZOMBIE_SKIN)
	local la = limb("Left Arm", Vector3.new(1, 2, 1), ZOMBIE_SKIN)
	local ra = limb("Right Arm", Vector3.new(1, 2, 1), ZOMBIE_SKIN)
	local ll = limb("Left Leg", Vector3.new(1, 2, 1), ZOMBIE_PANTS)
	local rl = limb("Right Leg", Vector3.new(1, 2, 1), ZOMBIE_PANTS)

	-- dark sunken eyes
	for _, sx in ipairs({-0.38, 0.38}) do
		local eye = Instance.new("Part")
		eye.Size = Vector3.new(0.34, 0.26, 0.1)
		eye.Color = Color3.fromRGB(18, 28, 20)
		eye.Material = Enum.Material.SmoothPlastic
		eye.Name = "Eye"
		eye.Parent = m
		local w = Instance.new("Weld")
		w.Part0 = head
		w.Part1 = eye
		w.C0 = CFrame.new(sx, 0.12, -0.82)
		w.Parent = eye
	end

	local function joint(p1, c0, name)
		local j = Instance.new("Motor6D")
		j.Name = name
		j.Part0 = torso
		j.Part1 = p1
		j.C0 = c0
		j.Parent = torso
		return j
	end

	local rootJoint = Instance.new("Motor6D")
	rootJoint.Name = "RootJoint"
	rootJoint.Part0 = root
	rootJoint.Part1 = torso
	rootJoint.Parent = root

	joint(head, CFrame.new(0, 1.8, 0), "Neck")
	local leftArm = joint(la, CFrame.new(-1.5, 0.4, 0), "LeftShoulder")
	local rightArm = joint(ra, CFrame.new(1.5, 0.4, 0), "RightShoulder")
	local leftLeg = joint(ll, CFrame.new(-0.5, -1.6, 0), "LeftHip")
	local rightLeg = joint(rl, CFrame.new(0.5, -1.6, 0), "RightHip")

	local hum = Instance.new("Humanoid")
	hum.MaxHealth = 60
	hum.Health = 60
	hum.WalkSpeed = 7
	hum.Parent = m

	m.PrimaryPart = root
	m.Parent = parent

	-- arms out front + shambling leg swing
	local baseLA, baseRA = leftArm.C0, rightArm.C0
	local baseLL, baseRL = leftLeg.C0, rightLeg.C0
	leftArm.C0 = baseLA * CFrame.Angles(math.rad(-80), 0, 0)
	rightArm.C0 = baseRA * CFrame.Angles(math.rad(-80), 0, 0)

	task.spawn(function()
		while m.Parent and hum.Health > 0 do
			local s = math.sin(os.clock() * 5) * 0.5
			leftLeg.C0 = baseLL * CFrame.Angles(s, 0, 0)
			rightLeg.C0 = baseRL * CFrame.Angles(-s, 0, 0)
			leftArm.C0 = baseLA * CFrame.Angles(math.rad(-80) + s * 0.25, 0, 0)
			rightArm.C0 = baseRA * CFrame.Angles(math.rad(-80) - s * 0.25, 0, 0)
			task.wait(0.06)
		end
	end)

	return m, hum, root
end

BUILDERS.Mobs = function(i, folder, info, state)
	local z = cellCenter(i, 0, 1).Z
	local mobs = {}

	-- two spawner openings in the side walls
	local spawners = {}
	for _, sx in ipairs({-0.4, Config.BayWidth + 0.4}) do
		local hole = newPart("Spawner", Vector3.new(1.2, 6, CELL - 1),
			Vector3.new(sx, 3, z), Color3.fromRGB(18, 14, 24),
			Enum.Material.Slate, folder)
		local l = Instance.new("PointLight")
		l.Color = Color3.fromRGB(120, 60, 200)
		l.Range = 10
		l.Brightness = 1.5
		l.Parent = hole
		table.insert(spawners, hole)
	end

	task.spawn(function()
		while folder.Parent do
			if not state.solved and #mobs < 4 then
				local from = spawners[math.random(1, #spawners)]
				local pos = from.Position + Vector3.new(from.Position.X < 0 and 3 or -3, 0, 0)
				local m, hum, root = buildZombie(Vector3.new(pos.X, 4, pos.Z), folder)
				table.insert(mobs, m)

				-- chase + attack
				task.spawn(function()
					while m.Parent and hum.Health > 0 do
						local best, bestD = nil, 1e9
						for _, pl in ipairs(session.runners) do
							local ch = pl.Character
							local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
							-- ghosts are invisible to mobs
							if hrp and not isGhost(ch) then
								local d = (hrp.Position - root.Position).Magnitude
								if d < bestD then best, bestD = ch, d end
							end
						end
						if best and bestD < 60 then
							hum:MoveTo(best.HumanoidRootPart.Position)
							if bestD < 4 then
								local ph = best:FindFirstChildOfClass("Humanoid")
								if ph and ph.Health > 0 then
									ph:TakeDamage(12)
									task.wait(1)
								end
							end
						end
						task.wait(0.3)
					end
				end)
			end
			task.wait(3)
		end
	end)

	function state.onSolved()
		for _, s in ipairs(spawners) do
			s.Color = Color3.fromRGB(70, 70, 78)
			for _, d in ipairs(s:GetChildren()) do
				if d:IsA("PointLight") then d.Enabled = false end
			end
		end
		for _, m in ipairs(mobs) do
			if m.Parent then m:Destroy() end
		end
		table.clear(mobs)
	end
end

-- ARROW TURRETS: wall dispensers fire volleys across the bay. Arrows physically die against
-- any crate, so a placed block is real hard cover you can stand behind; filling both solve
-- cells also shuts the turrets down.
BUILDERS.ArrowTurrets = function(i, folder, info, state)
	local z0 = bayZStart(i)
	local turrets = {}

	for _, side in ipairs({{x = -0.9, dir = 1}, {x = Config.BayWidth + 0.9, dir = -1}}) do
		for _, row in ipairs({0, 2}) do
			local z = z0 + row * CELL + CELL / 2
			for _, y in ipairs({2.2, 4.8}) do
				local t = newPart("Dispenser", Vector3.new(1.7, 1.7, 1.7),
					Vector3.new(side.x, y, z), Color3.fromRGB(62, 60, 56),
					Enum.Material.Slate, folder)
				local eye = Instance.new("PointLight")
				eye.Color = Color3.fromRGB(255, 150, 60)
				eye.Range = 7
				eye.Brightness = 1.2
				eye.Parent = t
				table.insert(turrets, {part = t, dir = side.dir, y = y, z = z})
			end
		end
	end

	local function crateBlocks(pos)
		local bay = folder.Parent
		for _, c in ipairs(bay:GetChildren()) do
			if c.Name == "Crate" then
				local b = c:FindFirstChild("Base")
				if b and math.abs(b.Position.X - pos.X) < 2.6
					and math.abs(b.Position.Z - pos.Z) < 2.6
					and pos.Y < b.Position.Y + 2.5 then
					return true
				end
			end
		end
		return false
	end

	task.spawn(function()
		while folder.Parent do
			if not state.solved then
				for _, t in ipairs(turrets) do
					local arrow = newPart("Arrow", Vector3.new(2.4, 0.26, 0.26),
						Vector3.new(t.part.Position.X + t.dir * 1.6, t.y, t.z),
						Color3.fromRGB(205, 190, 165), Enum.Material.Wood, folder)
					makeLethalPart(arrow)

					task.spawn(function()
						local travelled = 0
						while arrow.Parent and travelled < Config.BayWidth + 4 do
							arrow.CFrame = arrow.CFrame + Vector3.new(t.dir * 1.5, 0, 0)
							travelled += 1.5
							if crateBlocks(arrow.Position) then
								break -- absorbed by cover
							end
							task.wait(0.03)
						end
						if arrow.Parent then
							arrow:Destroy()
						end
					end)
				end
			end
			task.wait(2.4)
		end
	end)

	function state.onSolved()
		for _, t in ipairs(turrets) do
			t.part.Color = Color3.fromRGB(90, 88, 84)
			for _, l in ipairs(t.part:GetChildren()) do
				if l:IsA("PointLight") then
					l.Enabled = false
				end
			end
		end
		for _, a in ipairs(folder:GetChildren()) do
			if a.Name == "Arrow" then
				a:Destroy()
			end
		end
	end
end

-- DARK ZONE: lights out, with pits you cannot see until something lights them. The only
-- obstacle solved by what the block EMITS rather than what it blocks.
BUILDERS.DarkZone = function(i, folder, info, state)
	-- DARK ROOM. A search, not a traverse -- the only bay where the obstacle is not knowing
	-- where anything is.
	--
	-- The cube is a TOKEN, like the laser walk: a block on the operator's mat hangs a LANTERN
	-- from the ceiling above that cell. Nothing is carried in and nothing is stood on. What the
	-- operator is really doing is aiming a torch, one cell at a time, while the runner searches
	-- the pool of light underneath it.
	--
	-- Ten screws lie on the floor and are INVISIBLE unless their cell is lit. That gate is the
	-- whole bay: you cannot sweep the floor blind, so finding them is a conversation -- "light
	-- column 2" -- rather than a walk. With all ten in, a power box on the side wall at head
	-- height comes live, and driving its screws unlocks the room and brings the lights up.
	local bay = RunControl.warehouse():FindFirstChild(string.format("Bay%02d", i))
	if bay then
		bay:SetAttribute("VirtualCrates", true)
		-- a rebuild always starts lit, whatever the torn-down builder left behind
		bay:SetAttribute("Dark", false)
	end

	local z0 = bayZStart(i)
	local W, D = Config.BayWidth, Config.BayDepth
	local CEIL_Y = 14          -- low enough to read as a room, below the gantry rails at 18
	local SCREW_COUNT = 10

	local DARK = Color3.fromRGB(26, 26, 32)
	local WARM = Color3.fromRGB(255, 206, 128)
	local STEEL = Color3.fromRGB(198, 202, 212)

	----------------------------------------------------------------
	-- The room. Sealed on four sides and roofed, because "dark" has to come from being shut
	-- in rather than from a tinted box you can still see the warehouse through.
	----------------------------------------------------------------
	for _, side in ipairs({{"Left", 0}, {"Right", W}}) do
		newPart("DarkWall" .. side[1], Vector3.new(1, CEIL_Y, D),
			Vector3.new(side[2], CEIL_Y / 2, z0 + D / 2), DARK,
			Enum.Material.DiamondPlate, folder, {CanCollide = true})
	end
	newPart("DarkWallFar", Vector3.new(W + 2, CEIL_Y, 1),
		Vector3.new(W / 2, CEIL_Y / 2, z0 + D), DARK, Enum.Material.DiamondPlate, folder,
		{CanCollide = true})
	newPart("DarkCeiling", Vector3.new(W + 2, 1, D),
		Vector3.new(W / 2, CEIL_Y, z0 + D / 2), DARK, Enum.Material.DiamondPlate, folder,
		{CanCollide = true})

	-- The door you came in by. It drops behind you, which is what makes this a locked room.
	local GATE_H = 14
	local gate = newPart("DarkGate", Vector3.new(W, GATE_H, 1),
		Vector3.new(W / 2, -GATE_H / 2, z0), Color3.fromRGB(58, 56, 52),
		Enum.Material.DiamondPlate, folder, {CanCollide = true})

	-- The way out, in the far wall. Stays shut until the power box is driven.
	local exitDoor = newPart("DarkExit", Vector3.new(CELL * 1.5, 9, 1.2),
		Vector3.new(W / 2, 4.5, z0 + D), Color3.fromRGB(44, 48, 56),
		Enum.Material.Metal, folder, {CanCollide = true})
	local exitGlow = newPart("DarkExitEdge", Vector3.new(CELL * 1.5 + 0.4, 0.3, 1.5),
		Vector3.new(W / 2, 9.2, z0 + D), Color3.fromRGB(70, 74, 84),
		Enum.Material.Neon, folder, {CanQuery = false})

	----------------------------------------------------------------
	-- Wall sconces, not ceiling lanterns.
	--
	-- A block lights the sconce for its cell, and the throw is WIDE on purpose: one lamp
	-- bleeds across its neighbours, so two or three blocks wash most of the room rather than
	-- picking out twelve separate squares. Light coming in sideways also rakes across the
	-- floor, which is what makes a screw lying on it catch the eye -- a lamp directly overhead
	-- lights the floor flatly and hides them.
	--
	-- HOTSPOTS. Three cells are wired to a double fixture and throw much further. They are
	-- visible even unlit, by the neon trim ring, so the operator can see them from the
	-- spectator view and choose: a block on a hotspot lights most of the room, a block
	-- anywhere else still helps but less. That is the whole placement decision in this bay.
	local SCONCE_Y = 5.2
	local hotspots = {}
	do
		local all = {}
		for col = 0, Config.BayCols - 1 do
			for row = 0, Config.BayRows - 1 do
				table.insert(all, col .. "," .. row)
			end
		end
		for n = #all, 2, -1 do
			local j = math.random(n)
			all[n], all[j] = all[j], all[n]
		end
		for n = 1, 3 do
			hotspots[all[n]] = true
		end
	end

	local lamps = {}
	for col = 0, Config.BayCols - 1 do
		for row = 0, Config.BayRows - 1 do
			local key = col .. "," .. row
			local hot = hotspots[key] == true
			local c = cellCenter(i, col, row)
			-- nearest side wall, nudged along it so the two columns sharing a wall do not
			-- land on top of each other
			local onLeft = (col < Config.BayCols / 2)
			local x = onLeft and 0.75 or (W - 0.75)
			local nudge = (col == 0 or col == Config.BayCols - 1) and -1.9 or 1.9
			local z = c.Z + nudge
			local inward = onLeft and 1 or -1

			local body = newPart("Sconce", Vector3.new(0.5, hot and 1.8 or 1.2, hot and 2.4 or 1.5),
				Vector3.new(x, SCONCE_Y, z), Color3.fromRGB(34, 34, 40),
				Enum.Material.Metal, folder, {CanQuery = false})
			-- the trim is emissive so a hotspot is readable in a pitch-dark room
			local trim = newPart("SconceTrim",
				Vector3.new(0.18, (hot and 1.8 or 1.2) + 0.3, (hot and 2.4 or 1.5) + 0.3),
				Vector3.new(x + inward * 0.3, SCONCE_Y, z),
				hot and Color3.fromRGB(120, 80, 20) or Color3.fromRGB(30, 30, 38),
				Enum.Material.Neon, folder, {CanQuery = false})
			local glass = newPart("SconceGlass", Vector3.new(0.22, hot and 1.3 or 0.9, hot and 1.8 or 1.1),
				Vector3.new(x + inward * 0.36, SCONCE_Y, z), WARM,
				Enum.Material.Neon, folder, {Transparency = 1, CanQuery = false})

			-- Which cell is this lamp? Six fittings a wall and no way to tell them apart was
			-- the actual problem with the lighting UI -- "light column two" is useless if the
			-- operator cannot find column two's lamp. The number is painted on the fitting,
			-- facing into the room.
			local tag = Instance.new("SurfaceGui")
			tag.Face = onLeft and Enum.NormalId.Right or Enum.NormalId.Left
			tag.LightInfluence = 0
			tag.PixelsPerStud = 40
			tag.Adornee = body
			tag.Parent = body
			local tagText = Instance.new("TextLabel")
			tagText.Size = UDim2.new(1, 0, 1, 0)
			tagText.BackgroundTransparency = 1
			tagText.Font = Enum.Font.GothamBold
			tagText.TextScaled = true
			tagText.TextColor3 = hot and Color3.fromRGB(255, 200, 110)
				or Color3.fromRGB(150, 158, 175)
			tagText.TextStrokeTransparency = 0.3
			tagText.Text = string.format("%d,%d", col, row)
			tagText.Parent = tag

			local light = Instance.new("SpotLight")
			light.Color = WARM
			light.Angle = 150
			light.Face = onLeft and Enum.NormalId.Right or Enum.NormalId.Left
			light.Range = hot and (CELL * 3.6) or (CELL * 1.8)
			light.Brightness = 0
			light.Enabled = false
			light.Parent = glass

			lamps[key] = {body = body, trim = trim, glass = glass, light = light,
				tag = tagText, hot = hot, on = false}
		end
	end

	local function setLamp(col, row, on)
		local l = lamps[col .. "," .. row]
		if not l or l.on == on then
			return
		end
		l.on = on
		l.glass.Transparency = on and 0 or 1
		l.light.Enabled = on
		l.light.Brightness = on and (l.hot and 5.0 or 2.6) or 0
		l.trim.Color = on and (l.hot and Color3.fromRGB(255, 190, 90) or Color3.fromRGB(190, 150, 90))
			or (l.hot and Color3.fromRGB(120, 80, 20) or Color3.fromRGB(30, 30, 38))
		if l.tag then
			l.tag.TextColor3 = on and Color3.fromRGB(255, 240, 210)
				or (l.hot and Color3.fromRGB(255, 200, 110) or Color3.fromRGB(150, 158, 175))
		end
	end

	-- How far a lamp REVEALS, in cells.
	--
	-- Tuned down hard: at a 2-cell hotspot reach a single block in a corner lit nine of the
	-- twelve cells and showed 8 of the 10 screws, which is the whole bay solved by placing one
	-- cube anywhere. An ordinary lamp now pools over its own cell and a hotspot washes the ring
	-- around it, so the choice the operator makes is worth something: roughly one screw for a
	-- plain cell against four or five for an amber one.
	local function litRadiusCells(l)
		return l.hot and 1 or 0
	end

	local function isLit(col, row)
		for key, l in pairs(lamps) do
			if l.on then
				local lc, lr = key:match("(%d+),(%d+)")
				lc, lr = tonumber(lc), tonumber(lr)
				local reach = litRadiusCells(l)
				if math.abs(lc - col) <= reach and math.abs(lr - row) <= reach then
					return true
				end
			end
		end
		return false
	end

	----------------------------------------------------------------
	-- The ceiling lights. Dead until the power box is driven -- then the wall lamps go out and
	-- these come up, which is the room going back to normal and the way on opening.
	----------------------------------------------------------------
	local ceilingLights = {}
	for n = 0, 2 do
		local z = z0 + D * (0.2 + n * 0.3)
		local panel = newPart("CeilingPanel", Vector3.new(W * 0.55, 0.35, 2.2),
			Vector3.new(W / 2, CEIL_Y - 0.8, z), Color3.fromRGB(70, 72, 80),
			Enum.Material.SmoothPlastic, folder, {CanQuery = false})
		local lamp = Instance.new("PointLight")
		lamp.Color = Color3.fromRGB(235, 242, 255)
		lamp.Range = CELL * 4.5
		lamp.Brightness = 0
		lamp.Enabled = false
		lamp.Parent = panel
		table.insert(ceilingLights, {panel = panel, light = lamp})
	end

	local function setCeiling(on)
		for _, c in ipairs(ceilingLights) do
			c.light.Enabled = on
			c.light.Brightness = on and 3.0 or 0
			c.panel.Material = on and Enum.Material.Neon or Enum.Material.SmoothPlastic
			c.panel.Color = on and Color3.fromRGB(240, 246, 255) or Color3.fromRGB(70, 72, 80)
		end
	end

	----------------------------------------------------------------
	-- The screws. Scattered, and invisible until their cell is lit.
	----------------------------------------------------------------
	local screws = {}
	local found = 0
	do
		-- Spread over the twelve cells so no single lantern reveals half of them, and jittered
		-- within each so a lit cell still has to be looked at rather than merely entered.
		local slots = {}
		for col = 0, Config.BayCols - 1 do
			for row = 0, Config.BayRows - 1 do
				table.insert(slots, {col, row})
			end
		end
		for n = #slots, 2, -1 do
			local j = math.random(n)
			slots[n], slots[j] = slots[j], slots[n]
		end
		for n = 1, SCREW_COUNT do
			local slot = slots[((n - 1) % #slots) + 1]
			local c = cellCenter(i, slot[1], slot[2])
			local jx = (math.random() - 0.5) * (CELL - 2.5)
			local jz = (math.random() - 0.5) * (CELL - 2.5)
			local screw = newPart("Screw", Vector3.new(0.45, 1.1, 0.45),
				Vector3.new(c.X + jx, 0.55, c.Z + jz), STEEL, Enum.Material.Metal, folder,
				{Transparency = 1, CanQuery = false, Shape = Enum.PartType.Cylinder})
			screw.CFrame = CFrame.new(screw.Position) * CFrame.Angles(0, 0, math.rad(90))
			table.insert(screws, {part = screw, col = slot[1], row = slot[2], taken = false})
		end
	end

	----------------------------------------------------------------
	-- The power box. Dead until every screw is in, then it is the way out.
	----------------------------------------------------------------
	local boxZ = z0 + D * 0.5
	local box = newPart("PowerBox", Vector3.new(0.6, 3.4, 2.6),
		Vector3.new(W - 1.2, 4.6, boxZ), Color3.fromRGB(38, 38, 44),
		Enum.Material.DiamondPlate, folder, {CanCollide = false})
	local boxLamp = newPart("PowerBoxLamp", Vector3.new(0.3, 0.4, 2.0),
		Vector3.new(W - 1.6, 6.1, boxZ), Color3.fromRGB(70, 20, 20),
		Enum.Material.Neon, folder, {CanQuery = false})
	local driver = newPart("Screwdriver", Vector3.new(0.3, 1.6, 0.3),
		Vector3.new(W - 2.0, 4.6, boxZ), Color3.fromRGB(220, 180, 60),
		Enum.Material.Metal, folder, {Transparency = 1, CanQuery = false})

	local boxLabel = addLabel(folder, "POWER BOX  -  SEALED",
		Vector3.new(W - 2.2, 7.6, boxZ), Color3.fromRGB(150, 120, 120))

	local prompt = Instance.new("ProximityPrompt")
	prompt.ActionText = "Drive the screws"
	prompt.ObjectText = "Power Box"
	prompt.KeyboardKeyCode = Enum.KeyCode.E
	prompt.HoldDuration = 2.5
	prompt.MaxActivationDistance = 9
	prompt.RequiresLineOfSight = false
	prompt.Enabled = false
	prompt.Parent = box

	----------------------------------------------------------------
	-- Darkness. The room has to be GENUINELY dark: at 0.15 brightness with a lifted ambient you
	-- could still read the floor, which made the lamps cosmetic. Kushagra's original dimmed the
	-- global Lighting service (saving and restoring a baseline stamped on Lighting, because a
	-- rebuild mid-dark once made "restore" restore to pitch black for every bay, forever).
	--
	-- ARCADE: no Lighting at all. The arcade owns Lighting, and dimming it would black out the
	-- Workshop and the robot's view along with every other bay. The darkness is CAMERA-LOCAL
	-- now: this sets the attribute Dark on the bay model, and the runner's client
	-- (Views.Player.DarkRoom) darkens its own camera while its character stands in a bay whose
	-- Dark is true. The baseline trap is gone with it -- there is nothing to restore -- but
	-- every path that used to restore Lighting still clears Dark: leaving (or dying), the power
	-- box, solving, reset, and the run loop ending. A rebuild starts Dark = false above.
	----------------------------------------------------------------
	local dark = false
	local function setDark(on)
		if dark == on then
			return
		end
		dark = on
		-- A torn-down builder (its folder destroyed by a rebuild) must not write: the new one has
		-- already set Dark = false and may have darkened the room again since. With no Obstacle
		-- folder in the bay at all, clearing is always safe.
		if bay and (folder.Parent or not bay:FindFirstChild("Obstacle")) then
			bay:SetAttribute("Dark", on)
		end
	end

	----------------------------------------------------------------
	-- Which cells are lit follows the operator's blocks.
	----------------------------------------------------------------
	local litCells = {}
	BlockSync.CellsChanged:Connect(function(bayModel, cellsList)
		if not folder.Parent or bayModel ~= folder.Parent then
			return
		end
		local now = {}
		for _, c in ipairs(cellsList) do
			now[c.col .. "," .. c.row] = true
		end
		litCells = now
		for col = 0, Config.BayCols - 1 do
			for row = 0, Config.BayRows - 1 do
				setLamp(col, row, now[col .. "," .. row] == true)
			end
		end
	end)

	----------------------------------------------------------------
	-- Picking screws up. Only in the light -- otherwise you would sweep the floor blind and
	-- the lanterns would be decoration.
	----------------------------------------------------------------
	local function collect(entry)
		if entry.taken or not isLit(entry.col, entry.row) then
			return
		end
		entry.taken = true
		found += 1
		entry.part.Transparency = 1
		entry.part.CanTouch = false
		local pop = newPart("ScrewPop", Vector3.new(0.6, 0.6, 0.6), entry.part.Position,
			WARM, Enum.Material.Neon, folder,
			{CanQuery = false, Shape = Enum.PartType.Ball})
		TweenService:Create(pop, TweenInfo.new(0.35), {
			Size = Vector3.new(3, 3, 3),
			Transparency = 1,
		}):Play()
		Debris:AddItem(pop, 0.5)
	end

	for _, entry in ipairs(screws) do
		entry.part.Touched:Connect(function(hit)
			local ch = characterFrom(hit)
			if ch and not isGhost(ch) then
				collect(entry)
			end
		end)
	end

	----------------------------------------------------------------
	-- Driving the screws home.
	----------------------------------------------------------------
	local opened = false
	local function openRoom()
		if opened then
			return
		end
		opened = true
		prompt.Enabled = false

		task.spawn(function()
			-- the screwdriver turns, then the room comes back
			driver.Transparency = 0
			local spin = 0
			local t0 = os.clock()
			while os.clock() - t0 < 1.2 and folder.Parent do
				spin += 0.5
				driver.CFrame = CFrame.new(driver.Position) * CFrame.Angles(0, spin, 0)
				task.wait(0.03)
			end
			driver.Transparency = 1
			-- the wall lamps die and the ceiling comes up: the room going back to normal
			for col = 0, Config.BayCols - 1 do
				for row = 0, Config.BayRows - 1 do
					setLamp(col, row, false)
				end
			end
			setCeiling(true)
			setDark(false)
			boxLamp.Color = Color3.fromRGB(120, 240, 150)
			exitGlow.Color = Color3.fromRGB(120, 240, 150)
			boxLabel.Text = "POWER BOX  -  ON"
			boxLabel.TextColor3 = Color3.fromRGB(140, 255, 170)
			TweenService:Create(exitDoor, TweenInfo.new(1.0, Enum.EasingStyle.Quad), {
				CFrame = CFrame.new(exitDoor.Position.X, -5, exitDoor.Position.Z),
			}):Play()
			task.wait(1.0)
			exitDoor.CanCollide = false
			state.setSolved(true)
		end)
	end

	prompt.Triggered:Connect(function(player)
		local ch = player.Character
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if not hum or hum.Health <= 0 or isGhost(ch) or found < SCREW_COUNT then
			return
		end
		openRoom()
	end)

	----------------------------------------------------------------
	-- Run loop
	----------------------------------------------------------------
	local running = false
	local function setRunning(on)
		if running == on then
			return
		end
		running = on
		TweenService:Create(gate, TweenInfo.new(0.5), {
			CFrame = CFrame.new(gate.Position.X,
				on and GATE_H / 2 or -GATE_H / 2, gate.Position.Z),
		}):Play()
		setDark(on)
	end

	task.spawn(function()
		while folder.Parent do
			local occupants = occupantsOf(i, 0)
			setRunning(#occupants > 0 and not state.solved)

			for _, entry in ipairs(screws) do
				if not entry.taken then
					entry.part.Transparency = isLit(entry.col, entry.row) and 0 or 1
				end
			end

			local ready = (found >= SCREW_COUNT)
			prompt.Enabled = ready and not opened
			if opened then
				-- left as the open-room presentation
			elseif ready then
				boxLamp.Color = Color3.fromRGB(240, 200, 60)
				boxLabel.Text = "POWER BOX  -  HOLD E"
				boxLabel.TextColor3 = Color3.fromRGB(255, 220, 120)
			else
				boxLamp.Color = Color3.fromRGB(70, 20, 20)
				boxLabel.Text = string.format("POWER BOX  -  %d/%d SCREWS", found, SCREW_COUNT)
				boxLabel.TextColor3 = Color3.fromRGB(170, 130, 130)
			end

			local p = nil
			if running or state.solved then
				p = {title = "BAY 4  -  DARK ROOM"}
				if state.solved then
					p.task = "CLEARED"
					p.hint = "The lights are on and the door is open."
					p.tone = "ok"
				elseif ready then
					p.task = "POWER BOX  -  DRIVE THE SCREWS"
					p.hint = "Right-hand wall, middle of the room. Hold E."
					p.tone = "warn"
				else
					p.task = string.format("FIND THE SCREWS  -  %d / %d", found, SCREW_COUNT)
					p.hint = "Call out a cell. A block lights that wall lamp, and a screw only"
						.. " shows in the light. The amber fittings throw furthest."
					p.tone = "danger"
				end
				local litCount = 0
				for _ in pairs(litCells) do
					litCount += 1
				end
				p.steps = {
					string.format("%s  %d / %d screws",
						ready and "[x]" or "[ ]", found, SCREW_COUNT),
					string.format("%s  power box  -  %s",
						opened and "[x]" or (ready and "[ ]" or "[-]"),
						opened and "driven" or (ready and "ready" or "sealed")),
				}
				local hotLit = 0
				for key in pairs(litCells) do
					if hotspots[key] then
						hotLit += 1
					end
				end
				p.note = string.format(
					"%d lamp%s lit, %d on a hotspot. The amber fittings light far more than the rest.",
					litCount, (litCount == 1) and "" or "s", hotLit)
			end
			publishObjective(i, p, CELL)
			task.wait(0.2)
		end
		-- never leave the room dark because the bay was torn down mid-run (setDark skips the
		-- write if a rebuilt builder already owns the attribute)
		setDark(false)
	end)

	function state.onSolved()
		setDark(false)
		prompt.Enabled = false
	end

	function state.reset()
		setDark(false)
		setCeiling(false)
		opened = false
		found = 0
		driver.Transparency = 1
		for _, entry in ipairs(screws) do
			entry.taken = false
			entry.part.CanTouch = true
			entry.part.Transparency = 1
		end
	end
end
BUILDERS.Ice = function(i, folder, info, state)
	local centre = bayCenter(i)
	local bay = RunControl.warehouse():FindFirstChild(string.format("Bay%02d", i))
	local floor = bay and bay:FindFirstChild("Floor")
	if floor then
		floor.Material = Enum.Material.Ice
		floor.Color = Color3.fromRGB(165, 225, 255)
		-- low friction, heavily weighted so it wins over the character's own properties
		floor.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.02, 0.1, 50, 1)
	end

	-- frosty sheen over the lane
	newPart("Frost", Vector3.new(Config.BayWidth - 1, 0.12, Config.BayDepth - 1),
		Vector3.new(centre.X, 0.08, centre.Z), Color3.fromRGB(210, 245, 255),
		Enum.Material.Glass, folder, {Transparency = 0.55, CanQuery = false})

	-- the pinch point: lethal drops at the outer cells of the middle row
	for _, col in ipairs({0, 3}) do
		local c = cellCenter(i, col, 1)
		local drop = newPart("ColdDrop", Vector3.new(CELL - 0.5, 0.5, CELL - 0.5),
			Vector3.new(c.X, 0.25, c.Z), Color3.fromRGB(16, 48, 96),
			Enum.Material.Neon, folder, {Transparency = 0.25})
		makeLethal(drop, state)
		newPart("DropEdge", Vector3.new(CELL - 0.5, 0.5, 0.5),
			Vector3.new(c.X, 0.35, c.Z - CELL / 2), Color3.fromRGB(120, 220, 255),
			Enum.Material.Neon, folder)
	end

	function state.onSolved()
		-- rails are up: the drops are covered, so take the shine off them
		for _, p in ipairs(folder:GetChildren()) do
			if p.Name == "ColdDrop" then
				p.Color = Color3.fromRGB(70, 110, 150)
				p.Transparency = 0.6
			end
		end
	end
end

----------------------------------------------------------------
-- Build every bay
----------------------------------------------------------------
local states = {}

local function buildBay(i)
	local info = BayData[i]
	local warehouse = RunControl.warehouse()
	local bay = warehouse and warehouse:FindFirstChild(string.format("Bay%02d", i))
	if not info or not bay then
		return
	end

	local folder = bay:FindFirstChild("Obstacle")
	if folder then folder:Destroy() end
	folder = Instance.new("Folder")
	folder.Name = "Obstacle"
	folder.Parent = bay

	local builder = BUILDERS[info.obstacle]
	if not builder then
		warn("[HazardManager] no builder for obstacle " .. tostring(info.obstacle))
		return
	end

	local state = {solved = false, info = info, folder = folder}

	-- The one place a bay becomes solved or unsolved, so the two routes in -- cells filled
	-- (checkSolved) and an obstacle deciding for itself (the saw wall's levers) -- share the
	-- same presentation and the same edge-only onSolved call.
	function state.setSolved(solved)
		if solved == state.solved then
			return
		end
		state.solved = solved
		if solved then
			print(string.format("[HazardManager] %s SOLVED", state.info.obstacle))
			if state.label then
				state.label.Text = state.info.obstacle:upper() .. "  -  CLEARED"
				state.label.TextColor3 = Color3.fromRGB(120, 240, 140)
			end
			if state.onSolved then
				state.onSolved()
			end
		elseif state.label then
			state.label.Text = state.banner
			state.label.TextColor3 = Color3.fromRGB(255, 180, 90)
		end
	end

	builder(i, folder, info, state)

	CollectionService:AddTag(folder, "Obstacle")
	folder:SetAttribute("Obstacle", info.obstacle)
	folder:SetAttribute("Level", info.level)

	local c = bayCenter(i)
	-- A bay may name its own banner -- an action bay's requirement is not "colour x level" and
	-- the default used to be hard-coded to bay 1's levers, which was wrong for every other
	-- action bay. The default still describes a placement bay, which is most of them.
	state.banner = info.banner
		or string.format("%s  -  %s", info.obstacle:upper(), blockReq(info.level))
	-- On the bay's own sign, not floating over the middle of it. The floating version
	-- duplicated the objective HUD word for word, hung in the air at head height, and was
	-- the single most intrusive piece of UI in the game.
	state.label = baySignPlate(bay, state.banner, Ui.C.amber)

	states[bay] = state
	return state
end

for i = 1, Config.NumBays do
	buildBay(i)
	task.wait()
end

----------------------------------------------------------------
-- Solve detection: driven by whatever BlockSync has actually placed
----------------------------------------------------------------
local function checkSolved(info, cellsList)
	local byKey = {}
	for _, c in ipairs(cellsList) do
		byKey[c.col .. "," .. c.row] = c
	end
	-- Colour is deliberately not checked: any block satisfies a cell. The level test stays,
	-- because that is a cube COUNT -- a level-2 cell still wants two cubes stacked.
	for _, sc in ipairs(info.solveCells) do
		local c = byKey[sc[1] .. "," .. sc[2]]
		if not c then return false end
		if (c.level or 1) < info.level then return false end
	end
	return true
end

BlockSync.CellsChanged:Connect(function(bayModel, cellsList)
	local state = states[bayModel]
	if not state then
		local known = {}
		for k in pairs(states) do
			table.insert(known, k.Name)
		end
		warn(string.format("[HazardManager] no state for %s; known = [%s]",
			bayModel:GetFullName(), table.concat(known, ",")))
		return
	end

	-- Bays whose goal is an action rather than a placement own their own solved state; the
	-- crates there are the means, so filling cells must not short-circuit them.
	if ownsItsSolve(state.info) then
		return
	end

	-- A solved placement bay LATCHES. With the real rig, advancing requires player 2 to sweep
	-- the physical mat clear and re-place for the next bay -- there are only two cubes of each
	-- colour, so the cubes holding one bay open are the same ones the next bay needs. Without
	-- this latch that sweep re-arms every bay behind player 1: the void opens back up under
	-- someone walking out of a bay they already cleared.
	--
	-- Measured before the latch went in: 2 crates -> "VOID - CLEARED", then the mat sweep ->
	-- 0 crates -> "VOID - RED x1" again, 5.5 s later.
	--
	-- Switch-mode bays were already immune, which is why only this branch needs it. The R
	-- hotkey below is still the way to genuinely un-solve a bay.
	if state.solved then
		return
	end

	state.setSolved(checkSolved(state.info, cellsList))
end)

-- A bay is reset by REBUILDING it, not by asking it to tidy up after itself.
--
-- The old reset called setSolved(false) plus an optional per-obstacle state.reset(), and
-- carried a standing caveat: obstacles that present "solved" as a one-shot tween (the laser
-- grid fading out) never animated back, so their loops resumed while the visual stayed
-- cleared. Only the saw bay rebuilt properly. buildBay already destroys the Obstacle folder
-- and runs the builder from scratch, and every run loop in this file is `while folder.Parent
-- do`, so destroying the folder terminates all of them cleanly. Rebuilding is therefore a
-- genuine fresh state for every bay, and the caveat is gone rather than documented.
--
-- Crates are a separate concern and belong to BlockSync: a rebuilt bay that kept the previous
-- run's crates would also keep the diff state saying they are there, so re-placing the same
-- cube would be a no-op.
local function resetBay(i)
	local bay = RunControl.bayModel(i)
	if bay then
		BlockSync.clearBay(bay)
	end
	local st = buildBay(i)
	-- tell the crate sources to forget this bay, or the next edit re-delivers what was here
	RunControl.notifyBayReset(i)
	return st
end

RunControl.rebuildBay = resetBay

-- Wipe the whole course. Used when the crate source changes: solo and live disagree about who
-- owns the crates and what the arm is doing, so nothing may survive the switch.
function RunControl.rebuildAll()
	for n = 1, Config.NumBays do
		resetBay(n)
		task.wait()
	end
end
RunControl.bayState = function(i)
	local bay = RunControl.bayModel(i)
	return bay and states[bay]
end
RunControl.markReady()

-- R rebuilds every bay. A debug key (Config.ArcadeDebug / session.debug): with it off the
-- handler is never connected, so the remote does nothing however it is fired. Tracked, so the
-- connection dies with the round.
if session.debug then
	local DebugHotkey = Remotes:WaitForChild("DebugHotkey")
	session.track(DebugHotkey.OnServerEvent:Connect(function(_, key)
		if key ~= "R" then
			return
		end
		for i = 1, Config.NumBays do
			resetBay(i)
			task.wait()
		end
		print("[HazardManager] all bays rebuilt from scratch")
	end))
end

print("[HazardManager] one obstacle per bay built for all " .. Config.NumBays .. " bays")

HazardManager.states = states
return HazardManager
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.ActiveBayTracker", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.ActiveBayTracker (ModuleScript)
-- ActiveBayTracker -- the sliding window. Which bay the mat maps to follows the runner.
--
-- This is what was missing when you walked out of bay 1 into bay 2 and nothing happened: the
-- active bay only ever moved when the debug menu or a hotkey moved it, so the mat, the cell
-- editor, the crane and every crate delivery stayed pointed at the bay behind you. Blocks you
-- placed went into bay 1. The grid still showed bay 1.
--
-- It does not do the work itself -- it calls RunControl.setActiveBay, and everything already
-- hangs off that: Mapping re-origins on the new bay's Cell_0_0 anchor, SkyArm slides the crane
-- along the rails, DebugMode swaps to that bay's own cell state, and BridgeFeed clears the bay
-- being left behind.
--
-- THE CATWALK BELONGS TO THE BAY AHEAD. A bay spans BayDepth of its BayPitch and the rest is
-- the catwalk between it and the next. Standing on that catwalk counts as the NEXT bay, so the
-- mat is ready before you walk in rather than a moment after -- the operator needs to be
-- placing while you approach, not catching up once you are already inside. It also keeps this
-- agreeing with the debug menu, whose "start run" drops you on the approach catwalk: without
-- the rule the tracker would immediately drag the window back to the previous bay.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local RunControl = require(script.Parent:WaitForChild("RunControl"))

local session = RunControl.session

local SETTLE = 0.35        -- seconds a new bay must hold before the window moves

-- Which bay a world Z sits in, counting the catwalk after a bay as the next one. The arithmetic
-- is in course Z (bay 1's entrance = 0); the map itself sits Config.OriginZ down +Z.
local function bayAt(worldZ)
	local z = RunControl.courseZ(worldZ)
	if z < 0 then
		return 1
	end
	local i = math.floor(z / Config.BayPitch) + 1
	local into = z - (i - 1) * Config.BayPitch
	if into > Config.BayDepth then
		i += 1                -- on the catwalk: the bay ahead is the one being set up
	end
	return math.clamp(i, 1, Config.NumBays)
end

-- The runner drives the window, and the runner is whoever is furthest along. With one player
-- that is simply them. With two it follows the one actually running the course rather than
-- flipping to whoever wandered backwards. Only this round's runners count (session.runners):
-- anyone else in the server is in the Workshop, not on the course.
--
-- Ghosts are excluded: Q is a debug flight mode for touring the course, and having it drag
-- the mat from bay to bay while you fly over them would be useless to the operator.
local function leadBay()
	local best = nil
	for _, pl in ipairs(session.runners) do
		local ch = pl.Character
		local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
		local hum = ch and ch:FindFirstChildOfClass("Humanoid")
		if hrp and hum and hum.Health > 0 and ch:GetAttribute("Ghost") ~= true then
			local i = bayAt(hrp.Position.Z)
			if best == nil or i > best then
				best = i
			end
		end
	end
	return best
end

local candidate, since = nil, 0

session.track(RunService.Heartbeat:Connect(function(dt)
	local want = leadBay()
	if want == nil or want == RunControl.activeBay then
		candidate, since = nil, 0
		return
	end

	-- Debounced, because standing on a boundary otherwise flaps the window -- and every flap
	-- re-origins Mapping, tweens the crane and clears a bay's crates.
	if want ~= candidate then
		candidate, since = want, 0
		return
	end
	since += dt
	if since >= SETTLE then
		candidate, since = nil, 0
		local from = RunControl.activeBay
		RunControl.setActiveBay(want)
		print(("[ActiveBayTracker] runner moved: bay %d -> %d"):format(from, want))
	end
end))

print("[ActiveBayTracker] online -- the mat follows the runner")

return {}
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.BridgeFeed", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.BridgeFeed (ModuleScript)
-- BridgeFeed -- the live robot feed, wired into the bay (robot-link.md).
--
-- Replaces DebugMode as the source of crates in "live" feed mode. The difference is not
-- just where the data comes from: DebugMode treats a placement as a *command* and has SkyArm
-- animate a delivery, while here player 2's hands already did the delivery. So nothing is
-- animated. A cube is wherever the real cube is, and a held one follows the jaw.
--
--   hello  -> Mapping learns the real sheet geometry (never assume it; the spec is measured)
--   state  -> ArmMirror mirrors the arm, BlockSync.applyBlocks turns cubes into crates
--
-- Everything downstream of BlockSync.CellsChanged -- HazardManager's solve detection, the
-- placement guards, Bay 1's levers -- is untouched and cannot tell this from the cell editor.
--
-- THE ARCADE OWNS THE LINK. There is no obby Bridge any more: the core's ServerScriptService.Bridge
-- is the one socket, and it must never be required from here. The robot's data comes from the core
-- store instead -- ReplicatedStorage.Core.StateStore keeps the raw frame in sheet mm (get(), hello()),
-- and the arcade wrapper ServerStorage.Shared.StateStore fires Updated once per core update. Whether
-- the link is up is Shared.Bridge.isOnline(), which the Status module reports; nothing here dials,
-- hangs up or polls.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local RunControl = require(script.Parent:WaitForChild("RunControl"))

local Mapping = require(script.Parent:WaitForChild("Mapping"))
local ArmMirror = require(script.Parent:WaitForChild("ArmMirror"))
local BlockSync = require(script.Parent:WaitForChild("BlockSync"))
local SkyArm = require(script.Parent:WaitForChild("SkyArm"))

local session = RunControl.session

-- The core store (raw mm frames) and the arcade's Updated signal. Either may be missing in a bare
-- test place, and then there is no live feed at all -- solo still plays.
local function tryRequire(parent, ...)
	local node = parent
	for _, name in ipairs({...}) do
		node = node and node:FindFirstChild(name)
	end
	if not node then
		return nil
	end
	local ok, result = pcall(require, node)
	if not ok then
		warn("[BridgeFeed] " .. tostring(result))
		return nil
	end
	return result
end

local core = tryRequire(ReplicatedStorage, "Core", "StateStore")
local sharedStore = tryRequire(ServerStorage, "Shared", "StateStore")

-- Follows whichever bay is live. RunControl owns that, the debug menu drives it today, and
-- ActiveBayTracker drives it from the runner's position.
RunControl.setActiveBay(RunControl.activeBay)

local function currentBay()
	return RunControl.activeBayModel()
end

-- One arm on screen, and which one is a visual choice (Config.ArmStyle).
local gantry = Config.ArmStyle ~= "mirror"
local mirror = nil

-- The arm has TWO drivers and they must never overlap. In live the real arm steers it by the
-- tip; in solo the delivery job queue does, because the player is the operator and the arm is
-- carrying what they placed. Leaving live mode on in solo meant the Heartbeat kept lerping the
-- trolley toward a stale live target while a queued job tweened it somewhere else.
local function applyArmDriver()
	if gantry then
		SkyArm.setLiveMode(RunControl.feedMode == "live")
	end
end

if gantry then
	applyArmDriver()
	SkyArm.setActiveBay(RunControl.activeBayModel())
else
	mirror = ArmMirror.new(session.map)
	local ikRig = session.map:FindFirstChild("SkyArmRig")
	if ikRig then
		for _, part in ipairs(ikRig:GetDescendants()) do
			if part:IsA("BasePart") then
				part.Transparency = 1
				part.CanCollide = false
			end
		end
	end
end

-- The crane slides along the roof to sit over whichever bay is live. This is the sliding
-- window from the plan, and it is the thing that makes one mat serve nine bays legible.
RunControl.ActiveBayChanged:Connect(function()
	if gantry then
		local bay = RunControl.activeBayModel()
		if bay then
			SkyArm.setActiveBay(bay)
		end
	end
end)

-- The hello, once per round. The core keeps the last one it got, so by the time a live round
-- starts it is already here (the link only counts as online after a hello).
local h = core and core.hello and core.hello()
if type(h) == "table" and h.space then
	Mapping.setSpace(h.space)
	RunControl.setActiveBay(RunControl.activeBay)   -- ORIGIN depends on the scale hello just set
	print(("[BridgeFeed] %s v%s, %.0f Hz | grid %dx%d @ %.2f mm | cube %.2f studs | scale %.6f")
		:format(tostring(h.source), tostring(h.v), tonumber(h.state_hz) or 0,
			Mapping.GridCols, Mapping.GridRows, Mapping.CellMm,
			Mapping.cubeStuds(), Mapping.STUDS_PER_MM))
end

-- The jaw: the frame's arm.tip when it sends one, else the point named "tip", else the last
-- point (points run base to tip).
local function tipOf(arm)
	if type(arm) ~= "table" then
		return nil
	end
	local tip = type(arm.tip) == "table" and arm.tip or nil
	if not tip and type(arm.points) == "table" then
		for _, p in ipairs(arm.points) do
			if p.name == "tip" then
				tip = p
			end
		end
		tip = tip or arm.points[#arm.points]
	end
	if not (tip and tonumber(tip.x) and tonumber(tip.y) and tonumber(tip.z)) then
		return nil
	end
	return tip
end

local function onState(s)
	-- The arm keeps following in every mode: seeing the real arm move is useful even while
	-- debugging solo, and it costs nothing. Only the CRATES are gated on being the source.
	-- Live only. In solo there is no feed at all, and the arm belongs to the job queue.
	if RunControl.feedMode ~= "live" or type(s) ~= "table" then
		return
	end

	if gantry then
		local tip = tipOf(s.arm)
		if tip then
			SkyArm.followTip(Mapping.point(tip),
				s.arm.joints and s.arm.joints.gripper or 50)
		end
	else
		mirror:update(s.arm, s.arm_age)
	end

	-- Blocks update slower than the arm (perception is ~10 Hz against the arm's 30) and both
	-- ages climb on a bus dropout or a lost sheet. A stale block pose is worse than none: it
	-- is footing the player may be standing on that is no longer where the robot thinks. Hold
	-- the last good layout rather than re-asserting a stale one.
	local age = tonumber(s.blocks_age) or 0
	if age <= (Config.StaleAfterSeconds or 2) then
		local bay = currentBay()
		if bay then
			BlockSync.applyBlocks(bay, s.blocks)
		end
	end
end

-- Every core update, read as the raw mm frame (the Shared wrapper's own state is in cm).
if core and sharedStore and sharedStore.Updated then
	session.track(sharedStore.Updated.Event:Connect(function()
		onState(core.get())
	end))
else
	warn("[BridgeFeed] no Core/Shared StateStore in this place: the live feed is off")
end

-- Crates belong to the bay they were placed in; leaving them behind on a bay change would
-- strand them in a scenario nobody is running.
RunControl.ActiveBayChanged:Connect(function(_, previous)
	local old = RunControl.bayModel(previous)
	if old then
		BlockSync.clearBay(old)
	end
end)

BlockSync.PlacementRejected:Connect(function(bayModel, cell, reason)
	-- The cube is still on player 2's real table, so this is deferred, not discarded. The live
	-- path re-checks the guard every frame, so it lands the moment the guard relents.
	print(("[BridgeFeed] placement refused at (%s,%s): %s")
		:format(tostring(cell.col), tostring(cell.row), tostring(reason or "no reason given")))
end)

-- A mode change is a hard reset. Crates placed by the other source are not ours, the arm's
-- driver changes under it, and a half-built bay from the previous mode is just confusing.
RunControl.FeedModeChanged:Connect(function(mode)
	applyArmDriver()
	if RunControl.rebuildAll then
		RunControl.rebuildAll()
	end
	-- The core's link stays up either way: it is the arcade's, not ours to dial or hang up.
	if mode == "live" then
		print("[BridgeFeed] LIVE -- the real arm owns the crates; nothing else may place one")
	else
		print("[BridgeFeed] SOLO -- you are the operator; the grid places, the arm carries")
	end
end)

return {}
