table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.Status", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.Status (ModuleScript)
-- Status -- the always-on half of the old DebugMenu: what the server knows about the course, pushed
-- to the people who need it, so no client has to guess.
--
-- The debug menu used to own this, which tied the overseer's view to a debug tool: no debug
-- menu, no status, and the robot view framed nothing. In the arcade the debug menu is off for
-- anyone playing (Config.ArcadeDebug), but the runner's cell editor and the robot operator's
-- view still need it every round, so it lives here and DebugMenu only sends commands.
--
--   Remotes.Status    (server -> client) the snapshot() table below: every field the old
--                     DebugStatus payload had, plus linkOnline / runState / runEndsAt. Sent on
--                     change and on request (a client calls Remotes.Status:FireServer()).
--   Remotes.BayCells  (server -> client) (bayIndex, cellsList) whenever a bay's cells change.
--
-- Both go to this round's runners and the robot-role players (session.robots()) only, never to
-- the whole server: everyone else is in the Workshop.
--
--   Status.push(player?)  one player, or everyone above
--   Status.bumpReset()    a full reset happened (DebugMenu); see resetToken

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")

local Obby = ReplicatedStorage:WaitForChild("Obby")
local Config = require(Obby:WaitForChild("Config"))
local RunControl = require(script.Parent:WaitForChild("RunControl"))
local BayData = require(script.Parent:WaitForChild("BayData"))
local BlockSync = require(script.Parent:WaitForChild("BlockSync"))

local session = RunControl.session

local Remotes = Obby:WaitForChild("Remotes")
local StatusRemote = Remotes:WaitForChild("Status")
local BayCells = Remotes:WaitForChild("BayCells")

local Status = {}

-- The arcade's handle on the core robot link (Shared.Bridge). Missing in a bare test place, and
-- then the link simply reads as offline.
local sharedBridge = nil
do
	local shared = ServerStorage:FindFirstChild("Shared")
	local module = shared and shared:FindFirstChild("Bridge")
	if module then
		local ok, result = pcall(require, module)
		sharedBridge = ok and result or nil
	end
end

local function linkOnline()
	if not sharedBridge then
		return false
	end
	local ok, online = pcall(sharedBridge.isOnline)
	return ok and online == true
end

-- Who hears about the course: this round's runners, and the robot operator(s).
local function audience()
	local list = table.clone(session.runners)
	for _, r in ipairs(session.robots()) do
		if not table.find(list, r) then
			table.insert(list, r)
		end
	end
	return list
end

local function isAudience(player)
	return session.isRunner(player) or table.find(session.robots(), player) ~= nil
end

-- Bumped by a full reset. Clients that hold view state of their own -- the overseer's zoom
-- and pan -- watch this rather than guessing from the bay number, which does not change when
-- you full-reset while already standing on bay 1.
local resetToken = 0

function Status.bumpReset()
	resetToken += 1
	return resetToken
end

-- Which cells currently hold a block, pushed to clients.
--
-- The overseer's mini grid cannot work this out by looking: bays 3 and 4 set VirtualCrates, so
-- there is no crate in the world to see. A separate channel from CellsUpdated, which is the
-- cell editor's own echo and only fires in solo.
--
-- The last list per bay is kept too, so a view that opens mid-round (and asks for status) gets
-- the cells already placed instead of an empty grid until the next change.
local lastCells = {}

BlockSync.CellsChanged:Connect(function(bayModel, cellsList)
	local idx = tonumber(tostring(bayModel.Name):match("Bay(%d+)"))
	if idx then
		lastCells[idx] = cellsList
		for _, p in ipairs(audience()) do
			BayCells:FireClient(p, idx, cellsList)
		end
	end
end)

if not RunControl.waitForReady(15) then
	warn("[Status] HazardManager never published its rebuild hooks; bay status will read unsolved")
end

----------------------------------------------------------------
-- Status, so the client panel reflects the server rather than guessing
----------------------------------------------------------------
local function snapshot()
	local bays = {}
	for i = 1, Config.NumBays do
		local info = BayData[i]
		local state = RunControl.bayState and RunControl.bayState(i)
		bays[i] = {
			index = i,
			obstacle = info and info.obstacle or "?",
			color = info and info.color or nil,
			level = info and info.level or nil,
			solved = state and state.solved or false,
			switches = info and info.solveMode == "switches" or false,
			-- Where this bay wants blocks. The overseer view marks these in world, because
			-- "place a block at (1,0)" is only useful if you can see which cell that is.
			solveCells = info and info.solveCells or nil,
			banner = info and info.banner or nil,
		}
	end
	return {
		bays = bays,
		activeBay = RunControl.activeBay,
		feedMode = RunControl.feedMode,
		hasOverseer = RunControl.hasOverseer(),
		resetToken = resetToken,
		-- arcade additions: is the core's robot link up, and where the run clock is
		linkOnline = linkOnline(),
		runState = Obby:GetAttribute("RunState"),
		runEndsAt = Obby:GetAttribute("RunEndsAt"),
	}
end

Status.snapshot = snapshot

function Status.push(player)
	if not session.alive then
		return
	end
	local s = snapshot()
	if player then
		StatusRemote:FireClient(player, s)
	else
		for _, p in ipairs(audience()) do
			StatusRemote:FireClient(p, s)
		end
	end
end

RunControl.FeedModeChanged:Connect(function()
	Status.push()
end)

-- The tracker moves the active bay without anyone issuing a command, so the panel has to be
-- told or it shows the bay you were standing in two bays ago -- and the overseer view, which
-- reads activeBay from the same payload, would frame the wrong bay entirely.
RunControl.ActiveBayChanged:Connect(function()
	Status.push()
end)

-- A solve is also worth broadcasting: the menu greys a cleared bay and the overseer view stops
-- marking cells it no longer wants.
RunControl.BayReset:Connect(function()
	Status.push()
end)

-- Module drives the run (Ready -> Running -> Won/Lost) through these attributes; the views show it.
session.track(Obby:GetAttributeChangedSignal("RunState"):Connect(function()
	Status.push()
end))
session.track(Obby:GetAttributeChangedSignal("RunEndsAt"):Connect(function()
	Status.push()
end))

-- A fresh character (a death and the respawn checkpoint) gets a fresh copy, as the old
-- PlayerAdded hook did -- but for this round's runners only.
for _, player in ipairs(session.runners) do
	session.track(player.CharacterAdded:Connect(function()
		task.wait(0.5)
		if session.alive and player.Parent then
			Status.push(player)
		end
	end))
end

-- A client asking (a view that just opened): the status, then every bay's cells it has missed.
session.track(StatusRemote.OnServerEvent:Connect(function(player)
	if not isAudience(player) then
		return
	end
	Status.push(player)
	for idx, cellsList in pairs(lastCells) do
		BayCells:FireClient(player, idx, cellsList)
	end
end))

task.defer(Status.push)

print(("[Status] online -- %d bays, crate source: %s, robot link %s")
	:format(Config.NumBays, RunControl.feedMode, linkOnline() and "online" or "offline"))

return Status
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.DebugMenu", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.DebugMenu (ModuleScript)
-- DebugMenu (server) -- jump to any scenario and start a clean run on it, solo if you like.
--
-- Separate from DebugMode on purpose. DebugMode is one *source of crates* (the cell editor
-- standing in for player 2) and stands down when the real arm owns them. This is the control
-- panel, and it has to work in every feed mode -- including "live", where DebugMode is silent.
-- Folding the two together is what left the live build with no debug menu at all.
--
-- What "a fresh run" means here, in order:
--   1. rebuild the bay's obstacle from scratch   (RunControl.rebuildBay -> HazardManager)
--   2. wipe its crates and all diff state        (BlockSync.clearBay, via the same call)
--   3. clear the objective HUD
--   4. put the player OUTSIDE the entrance, alive, at full health
--
-- Step 4 is deliberate. Teleporting *into* a bay skips the doorway, and that is exactly how
-- bay 1's entry-blocking wall survived testing: the test teleported to row 2 and never walked
-- through the door (bay-01-saw-wall.md, bug 1). The run starts on the catwalk so the entry
-- path is always exercised.
--
-- ARCADE: debug only. Module requires this only when session.debug (Config.ArcadeDebug), and
-- only this round's runners may send it commands. The status it used to broadcast (DebugStatus,
-- BayCells) is the always-on Status module now; this file just calls Status.push after a command.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RunControl = require(script.Parent:WaitForChild("RunControl"))
local session = RunControl.session

if not session.debug then
	return {}
end

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))
local BayData = require(script.Parent:WaitForChild("BayData"))
local Status = require(script.Parent:WaitForChild("Status"))

local Remotes = ReplicatedStorage.Obby:WaitForChild("Remotes")

local DebugCommand = Remotes:WaitForChild("DebugCommand")
local GhostToggle = Remotes:WaitForChild("GhostToggle")

if not RunControl.waitForReady(15) then
	warn("[DebugMenu] HazardManager never published its rebuild hooks; menu will be inert")
end

local function pushStatus(player)
	Status.push(player)
end

----------------------------------------------------------------
-- Placement
----------------------------------------------------------------
-- Just outside the entrance, centred, so the player walks in through the doorway, facing down
-- the course: RunControl.approachCFrame (it adds Config.OriginZ and does the facing).
local function placePlayer(player, i, healFirst)
	local character = player.Character
	if not character then
		return false
	end
	local hum = character:FindFirstChildOfClass("Humanoid")
	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp or not hum or hum.Health <= 0 then
		-- Health = MaxHealth does not revive a *destroyed* Humanoid, and a stale character
		-- reads as "no player in the bay", so the obstacle never arms and the test silently
		-- passes (bay-01-saw-wall.md, bug 2). Reload instead.
		player:LoadCharacter()
		character = player.Character or player.CharacterAdded:Wait()
		hum = character:WaitForChild("Humanoid", 5)
		hrp = character:WaitForChild("HumanoidRootPart", 5)
		if not hrp then
			return false
		end
	elseif healFirst then
		hum.Health = hum.MaxHealth
	end
	-- Turning the BODY does not turn the CAMERA: placeCharacter also tells the client's
	-- CameraPolish which way to look, or the character faces the bay and the player still sees
	-- the way they came.
	return RunControl.placeCharacter(player, RunControl.approachCFrame(i))
end

----------------------------------------------------------------
-- Commands
----------------------------------------------------------------
local ObjectiveEvent = Remotes:WaitForChild("Objective")

-- The mat maps to whichever bay is live; RunControl owns that so every crate source and
-- Mapping agree on it. ActiveBayTracker will drive the same call from player 1's position.
local function setActiveBay(i)
	return RunControl.setActiveBay(i)
end

-- The course start, not bay 1's doorway, is RunControl.startCFrame(): the map's Start part
-- (where the obby's SpawnLocation was), facing +Z. Never a SpawnLocation lookup -- in the
-- arcade that finds the Workshop's.

-- Everything back to how the place loads. Not a teleport: a FRESH CHARACTER.
--
-- A run leaves marks a teleport does not clear -- ghost mode's transparency and infinite
-- health, PlatformStand left on by the fly controller, a hazard's weld, whatever velocity you
-- died with. Those travel with the character, so the only reliable way to be rid of all of
-- them at once is to throw the character away and take a new one.
local function fullReset(player)
	setActiveBay(1)
	for i = 1, Config.NumBays do
		if RunControl.rebuildBay then
			RunControl.rebuildBay(i)       -- obstacle rebuilt + every crate wiped
		end
		task.wait()
	end

	ObjectiveEvent:FireClient(player, nil)
	player:LoadCharacter()
	local character = player.Character or player.CharacterAdded:Wait()
	if character:WaitForChild("HumanoidRootPart", 5) then
		RunControl.placeCharacter(player, RunControl.startCFrame())
	end
	-- The new character is solid, but the ghost HUD survives respawn (ResetOnSpawn = false)
	-- and would still read GHOST ON over a body that can die.
	GhostToggle:FireClient(player, false)

	print("[DebugMenu] FULL RESET -- every bay rebuilt, fresh character on the spawn")
	Status.bumpReset()
	pushStatus()
end

local function startRun(player, i)
	i = math.clamp(math.floor(i or RunControl.activeBay), 1, Config.NumBays)
	setActiveBay(i)

	if RunControl.rebuildBay then
		RunControl.rebuildBay(i)          -- obstacle from scratch + crates wiped
	end
	ObjectiveEvent:FireClient(player, nil)
	placePlayer(player, i, true)

	local info = BayData[i]
	print(("[DebugMenu] run started on Bay %02d (%s) | crate source: %s")
		:format(i, info and info.obstacle or "?", RunControl.feedMode))
	pushStatus()
end

session.track(DebugCommand.OnServerEvent:Connect(function(player, action, arg)
	if not session.isRunner(player) then
		return
	end
	if action == "teleport" then
		setActiveBay(arg)
		placePlayer(player, RunControl.activeBay, true)
		pushStatus()

	elseif action == "startRun" then
		startRun(player, arg or RunControl.activeBay)

	elseif action == "resetBay" then
		if RunControl.rebuildBay then
			RunControl.rebuildBay(RunControl.activeBay)
		end
		ObjectiveEvent:FireClient(player, nil)
		print(("[DebugMenu] Bay %02d reset in place"):format(RunControl.activeBay))
		pushStatus()

	elseif action == "fullReset" then
		fullReset(player)

	elseif action == "resetAll" then
		for i = 1, Config.NumBays do
			if RunControl.rebuildBay then
				RunControl.rebuildBay(i)
			end
			task.wait()
		end
		ObjectiveEvent:FireClient(player, nil)
		print("[DebugMenu] every bay rebuilt")
		pushStatus()

	elseif action == "feedMode" then
		-- BridgeFeed does the world reset on the change event, so every bay is rebuilt and
		-- every crate cleared -- not just the active bay's. Crates from the previous source
		-- belong to the previous source.
		RunControl.setFeedMode(arg)
		ObjectiveEvent:FireClient(player, nil)
		pushStatus()

	elseif action == "status" then
		-- the old request; Remotes.Status:FireServer() is the real one now (Status answers it)
		pushStatus(player)
	end
end))

print(("[DebugMenu] online -- %d bays, crate source: %s")
	:format(Config.NumBays, RunControl.feedMode))

return {}
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.GhostMode", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.GhostMode (ModuleScript)
-- GhostMode -- debug spectator toggle (Q). Lets you tour every bay without dying: invincible,
-- no collision, and ignored by mobs. The character attribute "Ghost" is the single source of
-- truth; HazardManager checks it before doing any damage.
--
-- ARCADE: debug only (session.debug, Config.ArcadeDebug), never shipped in a round, and only this
-- round's runners can toggle it.
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local RunControl = require(script.Parent:WaitForChild("RunControl"))
local session = RunControl.session

local GhostMode = {}

if not session.debug then
	return GhostMode
end

local GhostToggle = ReplicatedStorage.Obby:WaitForChild("Remotes"):WaitForChild("GhostToggle")

local function applyGhost(character, on)
	character:SetAttribute("Ghost", on)

	for _, d in ipairs(character:GetDescendants()) do
		if d:IsA("BasePart") then
			-- HumanoidRootPart is invisible normally; don't reveal it
			if d.Name ~= "HumanoidRootPart" then
				d.Transparency = on and 0.6 or 0
			end
			d.CanCollide = not on
		elseif d:IsA("Decal") then
			d.Transparency = on and 0.6 or 0
		end
	end

	local hum = character:FindFirstChildOfClass("Humanoid")
	if hum then
		if on then
			hum.MaxHealth = math.huge
			hum.Health = math.huge
		else
			hum.MaxHealth = 100
			hum.Health = 100
		end
	end
end

session.track(GhostToggle.OnServerEvent:Connect(function(player)
	if not session.isRunner(player) then
		return
	end
	local character = player.Character
	if not character then
		return
	end
	local on = not (character:GetAttribute("Ghost") == true)
	applyGhost(character, on)
	print("[GhostMode] " .. player.Name .. " ghost = " .. tostring(on))
	GhostToggle:FireClient(player, on)
end))

-- a fresh character starts solid again (this round's runners only; no global PlayerAdded hook)
for _, plr in ipairs(session.runners) do
	if plr.Character then
		plr.Character:SetAttribute("Ghost", false)
	end
	session.track(plr.CharacterAdded:Connect(function(char)
		char:SetAttribute("Ghost", false)
	end))
end

-- The round is over: nobody walks back into the Workshop invincible and see-through.
function GhostMode.stop()
	for _, plr in ipairs(session.runners) do
		local character = plr.Character
		if character and character:GetAttribute("Ghost") == true then
			applyGhost(character, false)
			GhostToggle:FireClient(plr, false)
		end
	end
end

return GhostMode
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.BayData", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.BayData (ModuleScript)
-- BayData -- ONE obstacle per bay. Each 4x3 bay is a single obstacle the operator must clear.
--
-- BLOCKS ARE INTERCHANGEABLE: no obstacle requires a particular colour. The operator places
-- whichever cube is to hand, and any block satisfies any cell. `level` is still enforced,
-- because it is a cube COUNT and not a colour -- level 2 means two cubes stacked in that cell.
--
-- CUBE BUDGET: bays still ask for at most 2 cubes each, which is what the designs were built
-- around back when the limit was two cubes PER COLOUR. The rig owns 14 cubes in total, so that
-- ceiling is now self-imposed rather than physical -- a bay could ask for more, but none has
-- been redesigned to.
--
-- `solveCells` are where blocks must land. They double as the player's footing/route, so every
-- obstacle leaves a walkable way through -- the player is never killed while standing on the
-- thing that solved it.
--
-- col 0-3, row 0-2; row 0 is nearest the bay entrance.
-- `coverRows` limits an area obstacle to certain rows so the bay stays crossable on budget.
return {
	----------------------------------------------------------------
	-- IN SCOPE: bays 1-4. Config.NumBays is 4, so only these are built.
	--
	-- DarkZone was bay 8 and is bay 4 now, because the course has to be contiguous -- left at
	-- 8 you would walk through four empty bays to reach it.
	----------------------------------------------------------------
	[1] = {
		obstacle = "Saw",
		-- Solved by throwing both levers, not by filling cells: here the crates are a LADDER
		-- to the answer, not the answer. checkSolved skips this bay and the builder owns
		-- state.solved itself. solveCells stays as the advisory "stack here" hint.
		solveMode = "switches",
		banner = "SAW  -  THROW BOTH LEVERS",
		level = 1,
		solveCells = {{0, 1}, {3, 0}},
		-- The two levers cost 1 cube and 2 cubes respectively, plus 1 optional brake crate.
		-- They used to be on different colours because 3 of one colour was over budget; with
		-- colour irrelevant that constraint is gone, but the split stays -- the levers differ
		-- by the HEIGHT you must be standing at, which is the part that was ever load-bearing.
		-- minStand is that crate-top height, and it is what actually enforces the cube cost:
		-- a single crate tops out at 4, a stacked pair at 7. No colour is checked anywhere.
		--
		-- The wall closes from the far end toward the entrance, so row 1 is reached before
		-- row 0. Lever A sits deeper (row 1) and is therefore the timed one; Lever B sits by
		-- the entrance, which the wall reaches last.
		--
		-- A's crate buys a stall when the wall meets it, but only Config.SawWallStallSeconds
		-- and only once, so the whole bay stays a race -- and standing on that crate stops
		-- being safe the moment its stall is spent.
		-- A lever belongs to ONE stand level, and the builder derives everything from it: the
		-- mounting height, the painted level band on the wall, and the gate. `standLevel` is
		-- how many crates you stand on -- 1 for A, 2 for B -- so a lever cannot be reached from
		-- the wrong height in either direction. Standing on the stacked pair does NOT let you
		-- reach down and flip A; each lever costs its own crates, which is the cube budget
		-- argument this whole bay is built on.
		--
		-- Heights are no longer written here because they follow the real cube size
		-- (Mapping.cubeStuds, 6.72 studs) and would only rot if duplicated.
		levers = {
			{id = "A", side = "left",  cell = {0, 1}, level = 1, standLevel = 1},
			{id = "B", side = "right", cell = {3, 0}, level = 2, standLevel = 2},
		},
		note = "Bay seals behind you; a wall of chainsaws closes in from the exit end. Lever A"
			.. " (reachable off one crate) kills the blades and arms Lever B (needs a stacked"
			.. " pair), which halts the wall and sinks it into the floor -- that is the exit."
			.. " Lever heights clear the wall, so it passes under them.",
	},
	[2] = {
		obstacle = "Void",
		level = 1,
		-- Row 2 keeps its floor, so 2 cubes is enough to cross.
		-- The gap this leaves (16 studs) is already nearly twice a running jump (8.67), so the
		-- crates cannot be skipped; widening it to all three rows would only cost the player the
		-- landing, not add difficulty.
		coverRows = {0, 1},
		-- Both in column 1, one per uncovered row: that spaces the crate faces 2 / 4 / 2 studs
		-- apart across the gap, so every hop is comfortably inside a jump even though the gap as
		-- a whole is not. The bay tests the operator's placement, not the player's platforming.
		solveCells = {{1, 0}, {1, 1}},
		note = "No floor over rows 0-1. The blocks ARE the bridge from the catwalk to solid ground."
			.. " Nothing here is lethal but the drop, so the bridge is also the only safe footing.",
	},
	[3] = {
		obstacle = "LaserWalk",
		-- An ACTION bay: there is no fixed set of cells to fill, so checkSolved is skipped and
		-- the obstacle owns state.solved. It resolves when the player stands on the last cell
		-- of the route, not when the crate merely arrives there.
		solveMode = "action",
		banner = "LASER WALK  -  FOLLOW THE CRATE",
		level = 1,
		-- Deliberately NO solveCells: the route is generated per run (Config.LaserRoute*), so
		-- the answer does not exist until the bay arms. One cube is the whole cost -- it is the
		-- same crate the whole way across, walked ahead of the player one cell at a time.
		note = "Every cell of the grid is lethal. The one crate switches off whatever cell"
			.. " it sits in, and only the next cell of the route will accept it, so the operator"
			.. " walks you across. The cell the crate just left stays safe for a few seconds"
			.. " after the crate lands -- that gap is your window to follow it.",
	},
	[4] = {
		obstacle = "DarkZone",
		level = 1,
		-- Solved by an ACTION -- driving the power box -- not by filling cells. The blocks are
		-- lanterns here: they light the search, they are not the answer. checkSolved skips the
		-- bay and the builder owns state.solved.
		solveMode = "action",
		solveCells = {},
		banner = "DARK ROOM  -  FIND 10 SCREWS",
		note = "Lights out. A block hangs a lantern over its cell, and a screw is invisible"
			.. " until its cell is lit -- so finding all ten is a conversation, not a walk."
			.. " With ten in, the power box on the right-hand wall opens the room.",
	},

	----------------------------------------------------------------
	-- OUT OF SCOPE. Kept rather than deleted: these are past Config.NumBays, so HazardManager
	-- never builds them and ActiveBayTracker never selects them. Raise NumBays and re-run
	-- build/scope_course.lua to bring them back.
	----------------------------------------------------------------
	[5] = {
		obstacle = "Lava",
		level = 1,
		coverRows = {0, 1},   -- row 2 stays dry, so 2 stepping stones is enough
		solveCells = {{1, 0}, {1, 1}},
		note = "Lava rises on a timer. Blocks stand proud of the max level as dry stepping stones.",
	},
	[6] = {
		obstacle = "CrusherRoof",
		level = 2,
		solveCells = {{1, 1}},
		note = "Ceiling descends; a stacked pair props it and the roof halts on the stack.",
	},
	[7] = {
		obstacle = "Mobs",
		level = 1,
		solveCells = {{0, 1}, {3, 1}},
		note = "Blocks seal the two wall spawners so the mobs stop coming; the lane stays open.",
	},
	[8] = {
		obstacle = "ArrowTurrets",
		level = 1,
		solveCells = {{1, 1}, {2, 1}},
		note = "Wall dispensers fire volleys across the bay. The blocks are hard cover -- arrows die"
			.. " against them -- and placing both shuts the turrets down.",
	},
	[9] = {
		obstacle = "Ice",
		level = 1,
		solveCells = {{0, 1}, {3, 1}},
		finale = true,
		note = "Finale: frictionless ice. You slide through a pinch point with lethal drops either"
			.. " side; the blocks are guard rails that cover them.",
	},
}
]=] })
