table.insert(SOURCES, { path = "ServerStorage.Modes.Obby.Server.Mapping", class = "ModuleScript", source = [=[
-- ServerStorage.Modes.Obby.Server.Mapping (ModuleScript)
-- Mapping -- sheet millimetres -> obby studs. The only place the mat-to-bay scale lives.
--
-- Python sends everything in the sheet frame (PROTOCOL.md): origin at the printed sheet's
-- top-left corner, +x right, +y down the page (away from the arm), +z up off the paper.
-- Roblox is Y-up, so sheet y becomes world Z and sheet z becomes world Y. Both grids run the
-- same direction -- mat row A is nearest the arm, bay row 0 is nearest the entrance, and the
-- arm sits at the entrance end -- so there is no axis flip anywhere in here.
--
-- The scale is NOT a free parameter, unlike the bridge branch's 0.46 studs/mm. The mat's 4x3
-- grid has to land on the active bay's 4x3 grid of Config.CellSize cells, which pins it:
--
--     studs per mm = Config.CellSize / hello.space.grid.cell_mm = 8 / 57.15 = 0.1399825
--
-- Verified against the baked Cell_c_r anchors: all 12 mat cell centres land on their anchor to
-- within 2e-15 studs. Two things fall out of that number, both lucky:
--
--   * a 48 mm cube becomes 6.72 studs, so ONE cube is climbable against the ~12.8 studs a
--     default jump clears and a stacked PAIR (13.44) is not. That is exactly the gate Bay 1's
--     two levers rely on, arriving as a consequence of the real scale rather than a tuned
--     constant.
--   * the arm base lands at X = 16.00, the exact centre of the bay's 32 stud width.
--
-- What does NOT fall out nicely: the real arm's pan axis is 69 mm off the paper (9.66 studs)
-- while its wrist reaches 306 mm (42.9 studs). The SO-101 is a table arm that reaches up and
-- over, so a faithful mirror stands at the bay entrance and towers over it -- it is not the
-- ceiling-gantry arm Config.GantryHeight was sized for. See Config.GantryHeight.
--
-- ORIGIN is derived from the active bay's Cell_0_0 anchor rather than hardcoded, so following
-- the player from bay to bay is one setActiveBay call and the baked geometry stays the single
-- source of truth for where a cell actually is.

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))

local Mapping = {}

-- Defaults from robot/assets/workspace_sheet.json, so this module is usable before the hello
-- frame lands. setSpace replaces them with whatever the server actually measured.
Mapping.CellMm = 57.15
Mapping.GridOriginMm = {25.4, 22.225}
Mapping.GridRows = 3
Mapping.GridCols = 4
Mapping.CubeMm = 48
Mapping.SheetMm = {279.4, 215.9}
Mapping.ArmBaseMm = {139.7, -44.5}

Mapping.STUDS_PER_MM = Config.CellSize / Mapping.CellMm

-- HEIGHT is scaled separately from the floor plan, and only height.
--
-- The horizontal scale is pinned by the cell grid and must not move. Vertical is not pinned by
-- anything, and at the same 0.14 the real arm's 306 mm of reach becomes 43 studs -- which is
-- taller than the warehouse and turns the Sky Arm into a tower standing at the door rather than
-- the gantry crane sliding along the roof. Compressing height keeps the arm under its own rails
-- and a carried cube under the ceiling.
--
-- This does NOT touch a resting cube: its height comes from its stack level (level * cubeStuds),
-- so 6.72 and 13.44 studs are untouched and Bay 1's lever gate is unaffected. Only a HELD cube
-- and the arm's own points use it, and both need to agree or the jaw and the cube it is carrying
-- drift apart.
--
-- Derived, not picked: the arm's usable span in-world is floor to shoulder, about
-- GantryHeight - SHOULDER_OFFSET, against roughly 250 mm of real lift.
Mapping.HEIGHT_PER_MM = (Config.GantryHeight - 4) / 250

Mapping.ORIGIN = Vector3.new(0, 0, 0)
Mapping.activeBay = nil

local function recompute()
	Mapping.STUDS_PER_MM = Config.CellSize / Mapping.CellMm
	if Mapping.activeBay then
		Mapping.setActiveBay(Mapping.activeBay)
	end
end

-- Static geometry from the hello frame. Everything here is measured on the robot side (the
-- sheet size comes from the tag fit, the grid from workspace_sheet.json), so ask rather than
-- assume: an earlier bridge-branch bug hardcoded the sheet portrait when it is landscape and
-- built a floor pad that stopped 29 studs short of where real blocks mapped to.
function Mapping.setSpace(space)
	if type(space) ~= "table" then
		return
	end
	local g = space.grid
	if type(g) == "table" then
		Mapping.CellMm = tonumber(g.cell_mm) or Mapping.CellMm
		if type(g.origin_mm) == "table" and #g.origin_mm >= 2 then
			Mapping.GridOriginMm = {tonumber(g.origin_mm[1]), tonumber(g.origin_mm[2])}
		end
		if type(g.rows) == "table" then Mapping.GridRows = #g.rows end
		if type(g.cols) == "table" then Mapping.GridCols = #g.cols end
	end
	Mapping.CubeMm = tonumber(space.cube_mm) or Mapping.CubeMm
	if type(space.sheet) == "table" then
		Mapping.SheetMm = {tonumber(space.sheet.w_mm), tonumber(space.sheet.h_mm)}
	end
	if type(space.arm_base_mm) == "table" and #space.arm_base_mm >= 2 then
		Mapping.ArmBaseMm = {tonumber(space.arm_base_mm[1]), tonumber(space.arm_base_mm[2])}
	end

	-- The mat is 4 cols x 3 rows and so is a bay. If that ever stops being true the scale
	-- below is meaningless rather than merely wrong, so say so loudly instead of drifting.
	if Mapping.GridCols ~= Config.BayCols or Mapping.GridRows ~= Config.BayRows then
		warn(("[Mapping] grid is %dx%d but a bay is %dx%d -- the mat no longer maps onto a bay")
			:format(Mapping.GridCols, Mapping.GridRows, Config.BayCols, Config.BayRows))
	end
	recompute()
end

-- Point ORIGIN so that mat cell (0,0)'s centre lands exactly on this bay's Cell_0_0 anchor,
-- and sheet z = 0 (the paper) sits on the bay floor.
function Mapping.setActiveBay(bayModel)
	Mapping.activeBay = bayModel
	local anchors = bayModel and bayModel:FindFirstChild("CrateAnchors")
	local first = anchors and anchors:FindFirstChild("Cell_0_0")
	if not first then
		warn("[Mapping] no Cell_0_0 anchor under " .. tostring(bayModel and bayModel:GetFullName()))
		return
	end
	local s = Mapping.STUDS_PER_MM
	local cx = (Mapping.GridOriginMm[1] + 0.5 * Mapping.CellMm) * s
	local cz = (Mapping.GridOriginMm[2] + 0.5 * Mapping.CellMm) * s
	Mapping.ORIGIN = Vector3.new(first.Position.X - cx, first.Position.Y, first.Position.Z - cz)
end

-- A point as Python sends it ({x, y, z} in mm) -> a world position.
function Mapping.point(p)
	local s = Mapping.STUDS_PER_MM
	return Mapping.ORIGIN + Vector3.new(p.x * s, p.z * Mapping.HEIGHT_PER_MM, p.y * s)
end

function Mapping.cubeStuds()
	return Mapping.CubeMm * Mapping.STUDS_PER_MM
end

-- Which cell a sheet-frame point is in, or nil when it is off the grid (the inventory tray,
-- or the bare mat). Deliberately the same floor arithmetic as world.py's _cell_of, so the two
-- sides agree on the boundary case rather than each rounding its own way. The returned col and
-- row are already obby indices -- the mat's printed labels are 1-based columns and lettered
-- rows, but the wire carries millimetres and the arrays are 0-indexed either side.
function Mapping.cellOf(xMm, yMm)
	local col = math.floor((xMm - Mapping.GridOriginMm[1]) / Mapping.CellMm)
	local row = math.floor((yMm - Mapping.GridOriginMm[2]) / Mapping.CellMm)
	if col < 0 or col >= Mapping.GridCols or row < 0 or row >= Mapping.GridRows then
		return nil
	end
	return col, row
end

function Mapping.cellCentreMm(col, row)
	return Mapping.GridOriginMm[1] + (col + 0.5) * Mapping.CellMm,
		Mapping.GridOriginMm[2] + (row + 0.5) * Mapping.CellMm
end

-- Where a block's centre sits. A resting block's height comes from its stack level, not its
-- measured z: the robot snaps a resting cube to its cell and the game should be exactly where
-- it says. A held block is the opposite case -- the real carry height is the whole point, and
-- the player may be standing on it -- so its z is used directly.
function Mapping.blockPosition(b)
	local s = Mapping.STUDS_PER_MM
	local w = Mapping.cubeStuds()
	local y
	if b.held then
		-- Compressed height, matching Mapping.point, so the cube stays in the jaw carrying it.
		y = b.z * Mapping.HEIGHT_PER_MM + w / 2
	else
		-- Stack level, NOT measured millimetres: a resting cube should be exactly where the
		-- robot says, and these are the heights Bay 1's lever gate is tuned against.
		y = (b.level or 0) * w + w / 2
	end
	return Mapping.ORIGIN + Vector3.new(b.x * s, y, b.y * s)
end

function Mapping.blockSize()
	local w = Mapping.cubeStuds()
	return Vector3.new(w, w, w)
end

-- Sheet yaw is degrees counterclockwise seen from above, wrapping every 90 degrees.
function Mapping.blockOrientation(b)
	return CFrame.Angles(0, math.rad(-(b.yaw or 0)), 0)
end

return Mapping
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Config", class = "ModuleScript", source = [=[
-- ReplicatedStorage.Obby.Config (ModuleScript) -- every Robo Obby tunable, read by the server modules
-- (ServerStorage.Modes.Obby.Server) and the client views (ReplicatedStorage.Obby.Views).
-- Arcade copy of lebot_obby/ReplicatedStorage/Config.lua: same values, plus the ARCADE block below.
local Config = {}

-- TWO MODES, and exactly one of them owns the crates at a time (robot-link.md).
--
--   "solo"  one player doing both jobs. You place blocks on the on-screen 4x3 grid and the
--           Sky Arm carries them in, so you are the operator as well as the runner. Nothing
--           is connected and nothing is scripted.
--   "live"  the real SO-101 on the other end of the socket. Your hands are the only thing
--           that places a block.
--
-- There is deliberately no third "play back a recording" mode. A feed that places blocks by
-- itself is indistinguishable from the game doing it, which is alarming and was.
-- In the arcade this is only the fallback: Module.Start picks "live" when the core robot link is up
-- (ServerStorage.Shared.Bridge.isOnline(), status "live" or "mock") and "solo" otherwise, once per
-- round. The obby never opens a socket of its own; the core's ServerScriptService.Bridge is the link.
Config.FeedMode = "solo"
-- Which bay the mat currently maps to. Hardcoded until ActiveBayTracker picks it from where
-- player 1 is standing -- that module is what makes one physical mat serve nine bays.
Config.LiveBay = 1

-- How the real arm is drawn. "gantry" is the Sky Arm proper: it hangs from the ceiling rails,
-- slides along the roof between bays, and is sized to the room. The real arm drives it by the
-- tip, so it reaches where the real arm reaches.
-- "mirror" is the literal stick-figure mirror -- joint for joint, true SO-101 proportions. It
-- is honest but it is a 43 stud tower that stands at the door and pokes through the roof,
-- which needs WallHeight ~50 and BayGap >= 12 to house (robot-link.md section 4).
Config.ArmStyle = "gantry"

----------------------------------------------------------------
-- ARCADE (docs/obby-mode-plan.md)
----------------------------------------------------------------
-- The course is built around bay 1 starting at Z = 0 and X running 0..32. In the arcade the whole map
-- (Warehouse + Backdrop) is baked OriginZ studs down +Z, clear of Pattern Match (Z -400), Flood
-- (X 400) and Dragon Arena (Z ~520..880): the hall spans Z ~1036..1284. A pure Z shift, so every Z
-- the code computes goes through RunControl.bayZStart / HazardManager's bayZStart and X needs nothing.
Config.OriginZ = 1100

-- Debug tools: the F1/F2 debug menu (F2 = full reset), Q ghost flight, the cell editor's hotkeys
-- (1-9 N T K H M R; R rebuilds every bay) and the DebugCommand remote. The arcade runs in Studio
-- (the robot socket only works there), so RunService:IsStudio() is always true and cannot gate
-- them: this flag does. The attribute ArcadeDebug = true on ServerStorage.Modes.Obby also turns it
-- on for a session without editing this file. Keep it false for anyone playing.
Config.ArcadeDebug = false

-- The run clock (the win condition): reach the Finish zone past bay 4 before it runs out.
-- FullRunSeconds (below) is the clock; the arcade's Mode.MaxDuration is 500 (clock + result screen
-- + slack). ResultSeconds is how long the win/lose screen shows before the arcade takes everyone back.
Config.ResultSeconds = 4

-- Character size. The course was built and tuned around 1.0 characters (lever stand levels, the laser
-- walk's beam heights, the void's gap), and the arcade grows everyone to 1.5x (ServerScriptService.
-- CharacterScale). So runners are shrunk to RunnerScale for the round -- on Start and on every respawn,
-- re-checked every 0.25 s because CharacterScale grows a new character only once its appearance has
-- loaded -- and given ArcadeScale back on Stop and when they take the Back to Lobby pad.
-- ArcadeScale must match CharacterScale's SCALE.
Config.RunnerScale = 1
Config.ArcadeScale = 1.5

-- A dead runner comes back at the approach to the furthest bay they have reached (that bay is rebuilt
-- fresh, like the debug menu's "start run"). Seconds after CharacterAdded before the teleport (the
-- runner is shrunk back to RunnerScale first).
Config.RespawnSettleSeconds = 0.6

-- The dark room without touching Lighting (the arcade owns it): HazardManager sets the attribute
-- Dark = true on the bay model, and the runner's client (Views.Player.DarkRoom) puts a
-- ColorCorrectionEffect under its own camera while it stands in that bay. Tune by eye in Play.
Config.DarkTint = Color3.fromRGB(46, 50, 74)
Config.DarkBrightness = -0.12
Config.DarkContrast = 0.35
Config.DarkSaturation = -0.45

-- Grid / world layout (Section 7)
Config.CellSize = 8        -- studs per cell, square
Config.BayCols = 4         -- columns (X), 0-3
Config.BayRows = 3         -- rows (Z), 0-2, row 0 nearest the bay entrance
Config.BayGap = 6          -- catwalk studs between bays
Config.BayWidth = Config.CellSize * Config.BayCols   -- 32
Config.BayDepth = Config.CellSize * Config.BayRows   -- 24
Config.BayPitch = Config.BayDepth + Config.BayGap    -- 30, Z distance from one bay's start to the next
-- SCOPE: four obstacles -- Saw, Void, LaserWalk, DarkZone. BayData keeps the rest past this
-- index so nothing builds them. Raise this and re-run build/scope_course.lua to bring the
-- parked bays and their geometry back.
Config.NumBays = 4

-- Transport (Section 7, 12)
Config.PollRateHz = 3.5
Config.WebSocketHz = 25
Config.StaleAfterSeconds = 2

-- Units -- Open Item #1 (Section 20), unconfirmed with the robot teammate
Config.StudsPerCm = 1
Config.ArmAngleUnits = "degrees"

-- Clocks (Section 6) -- placeholders, retune after measuring real placement speed (Section 15, T+13-17)
Config.FullRunSeconds = 8 * 60 -- the arcade run clock (Module)
Config.DemoRunSeconds = 2 * 60 + 30
Config.DeathPenaltySeconds = 10
Config.TealL1BonusSeconds = 3
Config.TealL2FreezeSeconds = 8

-- Malfunctions (Section 9)
Config.MalfunctionIntensity = 1
Config.MalfunctionTelegraphSeconds = 1.5
Config.MalfunctionCooldownSeconds = 10
Config.MalfunctionGraceAfterBayChange = 3

-- Crate resolution timing (Section 5.2)
Config.CrateConfirmDelay = 0.2
Config.CrateRemoveDelay = 0.4

-- Bay 1 saw wall -- the closing wall IS this obstacle's clock, so this single number sets the
-- whole bay's difficulty. Budget check: one reachAndPlace is ~5.5s of arm animation and the job
-- queue serializes them, so this bay's three placements cost ~17s before the player has climbed
-- anything. 30 played too fast once the no-place band went in, since stalling is no longer
-- available to buy that time back.
-- 60 -> 75: the wall is no longer vaultable, so every crossing has to be earned by
-- actually solving it, and the extra 15 s is the room that costs.
Config.SawWallSeconds = 75
Config.SawWallBrakeEnabled = true

-- You cannot drop a crate in front of live blades to stall the wall: a cell within this many
-- studs of the blades, or already past them, refuses the placement outright. Stalling only
-- becomes possible once Lever A has killed the blades, which is what makes the spare cube a
-- reward for finishing Lever A rather than a way to skip it.
Config.SawWallNoPlaceBand = 4

-- How long one crate holds the wall once the blades are dead. A stall is spent per crate, so
-- the spare cube buys a second one -- but a jammed crate is only ever a reprieve, never a
-- permanent shield, and the wall resumes full speed when the timer runs out.
Config.SawWallStallSeconds = 10

Config.SawLeverHoldSeconds = 1 -- how long E is held to throw a lever

-- Bay 2 void -- the shaft is presentation plus a kill plane; the obstacle is the gap itself,
-- and that is sized by BayData[2].coverRows, not from here. Worth writing down why no tunable
-- is needed for the width: rows 0-1 span 16 studs and a running jump covers 8.67 (stock
-- JumpHeight 7.2, WalkSpeed 16, Gravity 196.2), so one row of void is already unjumpable and
-- two is well clear of it.
Config.VoidShaftDepth = 48    -- studs from floor level down to the kill plane
Config.VoidLightSpacing = 14  -- spacing of the red warning lights going down the shaft

-- Bay 3 laser walk -- one crate walked ahead of the player across a lethal grid.
--
-- The cooldown is counted from the moment the crate SEATS in its new cell, not from when it
-- was lifted, which is what lets this number be about the player's hop instead of the arm's
-- speed: one reachAndPlace is ~5.5s and a move is a remove plus a place, so a cooldown started
-- at lift would be gone before the crate even landed.
-- 6 was not enough to move a real cube and then walk the step. Swapping a block is a physical
-- action on a physical table, and the clock does not start until the NEW tile is live.
Config.LaserCooldownSeconds = 10    -- how long the vacated cell stays safe once the crate lands
Config.LaserRearmWarnSeconds = 2    -- the pad pulses fast, and counts in tenths, for this long
Config.LaserRouteMin = 6            -- steps in a generated route, inclusive
Config.LaserRouteMax = 8

-- Full playspace shell (Section 3.1, 7)
Config.EntranceBuffer = 10   -- buffer studs before Bay 1, holds the spawn
Config.FinaleBuffer = 10     -- buffer studs after Bay 9, holds the finale area
-- Raised from 28. Purely the room: nothing reads WallHeight at runtime, it records what the
-- baked geometry is -- so changing it means re-running build/fit_shell.lua, which is what
-- makes the shell follow it again.
Config.WallHeight = 48
Config.GantryHeight = 18 -- where the SkyArm rails/trolley ride; kept well below the ceiling
-- so there's open air above the arm. Deliberately separate from WallHeight: room height and
-- gantry height are different concerns, and the arm's reach math depends only on this one.
Config.SideMargin = 6   -- aisle space between the bay floor edge and the outer wall, for pallet racks
Config.WarehouseLength = (Config.NumBays - 1) * Config.BayPitch + Config.BayDepth

return Config
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.UiTheme", class = "ModuleScript", source = [=[
-- ReplicatedStorage.Obby.UiTheme (ModuleScript) -- arcade copy of lebot_obby/ReplicatedStorage/UiTheme.lua
-- (Kushagra's shared look: obby_planmds/ui.md), unchanged apart from this line. Required by the
-- Obby views and by HazardManager (in-world brass plates).
-- UiTheme -- one steampunk look, shared by every screen in the game.
--
-- Before this, each client script invented its own panel: three different dark-grey
-- rectangles, three different fonts, three different ideas of what "danger red" is. The HUD
-- read like three separate debug tools stacked on one screen, because that is what it was.
--
-- THE LOOK: riveted iron plate, brass framing, amber gaslight text. Everything is built from
-- Frames and UIStrokes -- no images, no uploaded assets -- so it reproduces from source like
-- the rest of the environment does.
--
-- USAGE
--   local Ui = require(ReplicatedStorage.UiTheme)
--   local panel = Ui.panel({parent = gui, size = UDim2.fromOffset(460, 150)})
--   Ui.text(panel.body, {text = "FIND THE SCREWS", style = "task", tone = "danger"})
--
-- `panel()` returns {frame, body, header, setHeader, setTone}. Put content in `.body`, which
-- is already inset past the frame's rivets -- parenting straight to `.frame` will put your
-- label underneath them.

local UiTheme = {}

----------------------------------------------------------------
-- Palette
----------------------------------------------------------------
-- Pulled from the same places the world is: the hall's brass and copper, the gas lamps'
-- amber, the teal patina on the pipework, and the furnace red the void glows with. The HUD
-- sitting in the same palette as the room is most of what makes it feel built rather than
-- bolted on.
UiTheme.C = {
	iron       = Color3.fromRGB(26, 21, 18),   -- panel body
	ironLight  = Color3.fromRGB(41, 34, 29),   -- raised areas, header band
	ironDark   = Color3.fromRGB(14, 11, 9),    -- insets, grid cells
	brass      = Color3.fromRGB(176, 141, 74), -- framing, rivets, rules
	brassDim   = Color3.fromRGB(110, 86, 44),  -- inactive framing
	copper     = Color3.fromRGB(168, 95, 51),
	patina     = Color3.fromRGB(62, 107, 99),

	amber      = Color3.fromRGB(255, 196, 110), -- primary text, gaslight
	parchment  = Color3.fromRGB(238, 226, 206), -- body text
	faded      = Color3.fromRGB(150, 134, 114), -- secondary text
	ghost      = Color3.fromRGB(96, 85, 72),    -- disabled / done

	danger     = Color3.fromRGB(232, 85, 47),   -- furnace red
	warn       = Color3.fromRGB(240, 170, 60),
	ok         = Color3.fromRGB(111, 207, 143), -- patina green
	info       = Color3.fromRGB(120, 186, 214),
}

-- Tone names are the server's vocabulary (`tone = "danger"` in an objective payload), so the
-- mapping lives here rather than being re-declared by every consumer.
UiTheme.TONE = {
	danger = UiTheme.C.danger,
	warn = UiTheme.C.warn,
	ok = UiTheme.C.ok,
	info = UiTheme.C.info,
}

function UiTheme.tone(name, fallback)
	return UiTheme.TONE[name] or fallback or UiTheme.C.danger
end

----------------------------------------------------------------
-- Type
----------------------------------------------------------------
-- Antique is the Victorian signage face and carries the whole theme; Oswald is condensed
-- industrial lettering for anything that has to be read at a glance across a room; Merriweather
-- is the only one of the three comfortable in a paragraph.
UiTheme.F = {
	title = Enum.Font.Antique,
	task = Enum.Font.Oswald,
	number = Enum.Font.Oswald,
	body = Enum.Font.Merriweather,
	label = Enum.Font.GothamBold,
}

local STYLE = {
	-- style name -> {font, size, colour, alignment}
	title   = {UiTheme.F.title,  15, UiTheme.C.brass,     Enum.TextXAlignment.Center},
	task    = {UiTheme.F.task,   27, UiTheme.C.amber,     Enum.TextXAlignment.Center},
	hint    = {UiTheme.F.body,   13, UiTheme.C.faded,     Enum.TextXAlignment.Center},
	step    = {UiTheme.F.body,   13, UiTheme.C.parchment, Enum.TextXAlignment.Left},
	note    = {UiTheme.F.body,   12, UiTheme.C.faded,     Enum.TextXAlignment.Center},
	caption = {UiTheme.F.label,  11, UiTheme.C.faded,     Enum.TextXAlignment.Left},
	label   = {UiTheme.F.label,  12, UiTheme.C.parchment, Enum.TextXAlignment.Center},
	number  = {UiTheme.F.number, 30, UiTheme.C.parchment, Enum.TextXAlignment.Center},
	big     = {UiTheme.F.title,  34, UiTheme.C.amber,     Enum.TextXAlignment.Center},
}

----------------------------------------------------------------
-- Pieces
----------------------------------------------------------------
local function stroke(inst, colour, thickness, transparency)
	local s = Instance.new("UIStroke")
	s.Color = colour
	s.Thickness = thickness or 1
	s.Transparency = transparency or 0
	s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	s.Parent = inst
	return s
end
UiTheme.stroke = stroke

local function corner(inst, radius)
	local c = Instance.new("UICorner")
	c.CornerRadius = UDim.new(0, radius or 4)
	c.Parent = inst
	return c
end
UiTheme.corner = corner

-- A single brass rivet. Small enough to read as a detail rather than a dot.
function UiTheme.rivet(parent, anchor, pos)
	local r = Instance.new("Frame")
	r.Name = "Rivet"
	r.AnchorPoint = anchor
	r.Position = pos
	r.Size = UDim2.fromOffset(5, 5)
	r.BackgroundColor3 = UiTheme.C.brass
	r.BorderSizePixel = 0
	r.ZIndex = 6
	r.Parent = parent
	corner(r, 3)
	-- a darker underside sells it as domed rather than flat
	local shade = Instance.new("Frame")
	shade.AnchorPoint = Vector2.new(0.5, 1)
	shade.Position = UDim2.new(0.5, 0, 1, 0)
	shade.Size = UDim2.fromOffset(5, 2)
	shade.BackgroundColor3 = UiTheme.C.brassDim
	shade.BorderSizePixel = 0
	shade.ZIndex = 6
	shade.Parent = r
	corner(shade, 2)
	return r
end

-- Rivets marching along the top and bottom edges of a panel.
function UiTheme.rivetRow(frame, inset, spacing)
	-- A rivet is a child Frame, and a child Frame inside a laid-out container is a LIST ITEM.
	-- Called on a UIListLayout panel, this marches rivets down the left edge as rows and
	-- shoves every real control out of position -- which is exactly what it did to the debug
	-- menu. Refuse rather than quietly wreck the layout.
	for _, c in ipairs(frame:GetChildren()) do
		if c:IsA("UIListLayout") or c:IsA("UIGridLayout") or c:IsA("UITableLayout") then
			warn(("[UiTheme] rivetRow skipped on %q: it uses a %s and rivets would become layout items")
				:format(frame.Name, c.ClassName))
			return
		end
	end
	inset = inset or 9
	spacing = spacing or 34
	local width = frame.AbsoluteSize.X
	-- AbsoluteSize is 0 until the frame has been laid out once, so fall back to the offset
	-- component, which is how every panel in this game is sized.
	if width <= 0 then
		width = frame.Size.X.Offset
	end
	local n = math.max(2, math.floor((width - inset * 2) / spacing))
	for i = 0, n do
		local x = inset + (width - inset * 2) * (i / n)
		UiTheme.rivet(frame, Vector2.new(0.5, 0.5), UDim2.new(0, x, 0, inset))
		UiTheme.rivet(frame, Vector2.new(0.5, 0.5), UDim2.new(0, x, 1, -inset))
	end
end

-- The brass sheen that keeps a flat colour from reading as flat.
local function sheen(inst, strength)
	local g = Instance.new("UIGradient")
	g.Rotation = 90
	g.Color = ColorSequence.new(
		Color3.new(1, 1, 1),
		Color3.new(1 - (strength or 0.25), 1 - (strength or 0.25), 1 - (strength or 0.25)))
	g.Parent = inst
	return g
end
UiTheme.sheen = sheen

----------------------------------------------------------------
-- Panel
----------------------------------------------------------------
-- opts: {parent, size, position, anchor, title, tone, padding, zindex}
-- returns {frame, body, header, titleLabel, accent, setTitle, setTone}
function UiTheme.panel(opts)
	local frame = Instance.new("Frame")
	frame.Name = opts.name or "Panel"
	frame.Size = opts.size or UDim2.fromOffset(400, 120)
	frame.Position = opts.position or UDim2.fromOffset(0, 0)
	frame.AnchorPoint = opts.anchor or Vector2.zero
	frame.BackgroundColor3 = UiTheme.C.iron
	frame.BackgroundTransparency = opts.transparency or 0.06
	frame.BorderSizePixel = 0
	frame.ZIndex = opts.zindex or 2
	frame.Parent = opts.parent
	corner(frame, 5)
	sheen(frame, 0.3)
	local edge = stroke(frame, UiTheme.C.brass, 2)

	-- Accent bar: the panel's tone, read at a glance before any word is.
	local accent = Instance.new("Frame")
	accent.Name = "Accent"
	accent.Size = UDim2.new(1, -16, 0, 3)
	accent.Position = UDim2.new(0, 8, 0, 4)
	accent.BackgroundColor3 = UiTheme.tone(opts.tone)
	accent.BorderSizePixel = 0
	accent.ZIndex = frame.ZIndex + 1
	accent.Parent = frame
	corner(accent, 2)

	local titleLabel
	if opts.title ~= nil then
		titleLabel = Instance.new("TextLabel")
		titleLabel.Name = "Title"
		titleLabel.Size = UDim2.new(1, -24, 0, 16)
		titleLabel.Position = UDim2.new(0, 12, 0, 10)
		titleLabel.BackgroundTransparency = 1
		titleLabel.Font = UiTheme.F.title
		titleLabel.TextSize = 14
		titleLabel.TextColor3 = UiTheme.C.brass
		titleLabel.TextXAlignment = Enum.TextXAlignment.Center
		titleLabel.Text = opts.title
		titleLabel.ZIndex = frame.ZIndex + 1
		titleLabel.Parent = frame
	end

	local body = Instance.new("Frame")
	body.Name = "Body"
	body.BackgroundTransparency = 1
	body.BorderSizePixel = 0
	body.ZIndex = frame.ZIndex + 1
	-- inset past the rivet line so content never collides with the frame detail
	local top = (opts.title ~= nil) and 30 or 14
	body.Position = UDim2.new(0, 16, 0, top)
	body.Size = UDim2.new(1, -32, 1, -(top + 12))
	body.Parent = frame

	UiTheme.rivetRow(frame)

	local api = {
		frame = frame, body = body, accent = accent,
		titleLabel = titleLabel, edge = edge,
	}
	function api.setTitle(text)
		if titleLabel then
			titleLabel.Text = text or ""
		end
	end
	function api.setTone(name)
		accent.BackgroundColor3 = UiTheme.tone(name)
	end
	return api
end

----------------------------------------------------------------
-- Text
----------------------------------------------------------------
-- opts: {text, style, tone, size, position, colour, wrap, zindex, scaled}
function UiTheme.text(parent, opts)
	-- An unknown style name used to take the whole client script down with "attempt to index
	-- nil with number", three frames into a playtest, pointing at this file rather than at the
	-- caller that misspelled it. A HUD is not worth losing a script over: warn, name the
	-- offender, and fall back to body text.
	local spec = STYLE[opts.style or "step"]
	if not spec then
		warn(("[UiTheme] unknown text style %q (falling back to \"step\")"):format(tostring(opts.style)))
		spec = STYLE.step
	end
	local l = Instance.new("TextLabel")
	l.Name = opts.name or "Text"
	l.BackgroundTransparency = 1
	l.Font = opts.font or spec[1]
	l.TextSize = opts.textSize or spec[2]
	l.TextColor3 = opts.colour or (opts.tone and UiTheme.tone(opts.tone)) or spec[3]
	l.TextXAlignment = opts.align or spec[4]
	l.TextYAlignment = opts.yAlign or Enum.TextYAlignment.Center
	l.Text = opts.text or ""
	l.TextWrapped = opts.wrap or false
	l.TextScaled = opts.scaled or false
	l.RichText = opts.rich or false
	l.Size = opts.size or UDim2.new(1, 0, 0, spec[2] + 6)
	l.Position = opts.position or UDim2.fromOffset(0, 0)
	l.AnchorPoint = opts.anchor or Vector2.zero
	l.ZIndex = opts.zindex or (parent.ZIndex or 1) + 1
	l.Parent = parent
	return l
end

-- A thin brass rule, for separating sections inside a panel.
function UiTheme.rule(parent, y, inset)
	local r = Instance.new("Frame")
	r.Name = "Rule"
	r.Size = UDim2.new(1, -(inset or 0) * 2, 0, 1)
	r.Position = UDim2.new(0, inset or 0, 0, y)
	r.BackgroundColor3 = UiTheme.C.brassDim
	r.BackgroundTransparency = 0.35
	r.BorderSizePixel = 0
	r.ZIndex = (parent.ZIndex or 1) + 1
	r.Parent = parent
	return r
end

----------------------------------------------------------------
-- A crate, drawn in 2D
----------------------------------------------------------------
-- The operator's job is "put one cube here" or "stack two cubes here", and a number is a
-- worse way to say that than a picture of one cube or two. Used by the overseer card.
function UiTheme.crateIcon(parent, opts)
	local holder = Instance.new("Frame")
	holder.Name = "CrateIcon"
	holder.BackgroundTransparency = 1
	holder.Size = opts.size or UDim2.fromOffset(34, 44)
	holder.Position = opts.position or UDim2.fromOffset(0, 0)
	holder.AnchorPoint = opts.anchor or Vector2.zero
	holder.ZIndex = opts.zindex or (parent.ZIndex or 1) + 1
	holder.Parent = parent

	local count = math.max(1, opts.count or 1)
	local cube = math.max(14, math.floor(holder.Size.Y.Offset / (count + 0.6)))
	for i = 1, count do
		local c = Instance.new("Frame")
		c.Name = "Cube" .. i
		c.AnchorPoint = Vector2.new(0.5, 1)
		c.Position = UDim2.new(0.5, 0, 1, -(i - 1) * (cube + 2))
		c.Size = UDim2.fromOffset(cube, cube)
		c.BackgroundColor3 = opts.colour or UiTheme.C.copper
		c.BorderSizePixel = 0
		c.ZIndex = holder.ZIndex + 1
		c.Parent = holder
		corner(c, 3)
		stroke(c, UiTheme.C.brass, 1.5)
		sheen(c, 0.35)
	end
	return holder
end

----------------------------------------------------------------
-- A diegetic brass plate: UI that lives on a part in the world, not on the screen.
----------------------------------------------------------------
-- The alternative is a BillboardGui, which always faces you, always draws on top, and never
-- belongs to the room. A plate bolted to the thing it describes reads as part of the machine
-- -- and crucially it occludes properly, so a label inside a sealed bay stays inside it.
function UiTheme.plate(part, opts)
	local existing = part:FindFirstChild("UiPlate")
	if existing then
		existing:Destroy()
	end
	local sg = Instance.new("SurfaceGui")
	sg.Name = "UiPlate"
	sg.Face = opts.face or Enum.NormalId.Front
	sg.LightInfluence = opts.lightInfluence or 0
	sg.PixelsPerStud = opts.ppu or 48
	sg.MaxDistance = opts.maxDistance or 90
	sg.Parent = part

	local bg = Instance.new("Frame")
	bg.Size = UDim2.fromScale(1, 1)
	bg.BackgroundColor3 = UiTheme.C.ironDark
	bg.BackgroundTransparency = opts.transparency or 0.1
	bg.BorderSizePixel = 0
	bg.Parent = sg
	corner(bg, 4)
	stroke(bg, UiTheme.C.brass, 2)
	sheen(bg, 0.25)

	local l = Instance.new("TextLabel")
	l.AnchorPoint = Vector2.new(0.5, 0.5)
	l.Position = UDim2.fromScale(0.5, 0.5)
	l.Size = UDim2.new(1, -10, 1, -8)
	l.BackgroundTransparency = 1
	l.Font = opts.font or UiTheme.F.title
	l.TextScaled = true
	l.TextColor3 = opts.colour or UiTheme.C.amber
	l.Text = opts.text or ""
	l.TextWrapped = true
	l.Parent = bg

	return {gui = sg, background = bg, label = l}
end

return UiTheme
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.PlayerView", class = "ModuleScript", source = [=[
-- ReplicatedStorage.Obby.Views.PlayerView (ModuleScript)
-- Robo Obby for the player role and for spectators while the Obby is the active game (Core.GameRegistry;
-- the arcade sets it while the Obby bay's round runs). The PatternMatch PlayerView pattern: everything the
-- game shows on a runner's screen is kept as inert LocalScript templates and cloned into PlayerGui on
-- enter, destroyed on exit:
--   Views.Player.ObjectiveHud   the task panel, the bay countdown and the run clock pill
--   Views.Player.CellEditor     the on-screen 4x3 grid that places blocks: solo only
--                               (ReplicatedStorage.Obby FeedMode == "solo"; follows FeedMode while entered)
--   Views.Player.BackdropFx     the hall's gears, lamps and steam (client-side, tagged parts in the map)
--   Views.Player.CameraPolish   the camera faces teleports and respawns; low ceilings cap the zoom
--   Views.Player.DarkRoom       the dark room's darkness: a ColorCorrectionEffect "ObbyDark" under the camera
--   Views.Debug.DebugMenu, Views.Debug.GhostControl   only when ReplicatedStorage.Obby ArcadeDebug == true
-- ctx.readOnly (spectators): only ObjectiveHud and BackdropFx, with the attribute ReadOnly = true (they
-- send nothing; the camera follows the player's, Core RoleClient).
-- Nothing here touches Lighting (the arcade owns it): the dark room is the effect under the camera.
-- On exit each copy first gets the attribute Exiting = true and one frame to clean up while its script is
-- still running (camera, zoom cap, its ScreenGui): a script's own Destroying handler can't be relied on
-- once the script itself is being destroyed. Then the copies go, and anything left over is removed here:
-- every PlayerGui child with the attribute ObbyView = true (each copy's ScreenGui has it) and ObbyDark.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Obby = ReplicatedStorage:WaitForChild("Obby")
local playerTemplates = script.Parent:WaitForChild("Player")
local debugTemplates = script.Parent:WaitForChild("Debug")

local DARK_NAME = "ObbyDark" -- Views.Player.DarkRoom's effect under the camera
local READ_ONLY = {ObjectiveHud = true, BackdropFx = true}
local SOLO_ONLY = {CellEditor = true}

local PlayerView = {}

local live = {} -- template -> its copy in PlayerGui
local connections = {}
local entered = nil -- the ctx while entered

-- Should this template have a copy right now?
local function wanted(template, fromDebug)
	if not template:IsA("LocalScript") then
		return false
	end
	local readOnly = entered.readOnly == true
	if fromDebug then
		return not readOnly and Obby:GetAttribute("ArcadeDebug") == true
	end
	if readOnly then
		return READ_ONLY[template.Name] == true
	end
	if SOLO_ONLY[template.Name] then
		return Obby:GetAttribute("FeedMode") == "solo"
	end
	return true
end

local function remove(template)
	local copy = live[template]
	if not copy then
		return
	end
	live[template] = nil
	copy:SetAttribute("Exiting", true)
	-- The copy destroys its own ScreenGui on Exiting; whatever it leaves goes in exit's ObbyView sweep.
	task.spawn(function()
		task.wait() -- the copy's script cleans up on Exiting
		copy:Destroy()
	end)
end

-- Adds and removes copies to match what is wanted (enter, and FeedMode / ArcadeDebug changes).
local function sync()
	if not entered then
		return
	end
	local playerGui = Players.LocalPlayer:WaitForChild("PlayerGui")
	for _, entry in ipairs({{playerTemplates, false}, {debugTemplates, true}}) do
		for _, template in ipairs(entry[1]:GetChildren()) do
			local want = wanted(template, entry[2])
			if want and not live[template] then
				local copy = template:Clone()
				copy:SetAttribute("ReadOnly", entered.readOnly == true)
				copy.Parent = playerGui
				live[template] = copy
			elseif not want and live[template] then
				remove(template)
			end
		end
	end
end

function PlayerView.enter(ctx)
	PlayerView.exit()
	entered = ctx or {}
	table.insert(connections, Obby:GetAttributeChangedSignal("FeedMode"):Connect(sync))
	table.insert(connections, Obby:GetAttributeChangedSignal("ArcadeDebug"):Connect(sync))
	sync()
end

function PlayerView.exit()
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	entered = nil
	local copies = {}
	for _, copy in pairs(live) do
		copy:SetAttribute("Exiting", true)
		table.insert(copies, copy)
	end
	table.clear(live)
	if #copies > 0 then
		task.wait() -- the copies' scripts clean up on Exiting
		for _, copy in ipairs(copies) do
			copy:Destroy()
		end
	end
	local playerGui = Players.LocalPlayer:FindFirstChild("PlayerGui")
	for _, child in ipairs(playerGui and playerGui:GetChildren() or {}) do
		if child:GetAttribute("ObbyView") == true then
			child:Destroy()
		end
	end
	local camera = workspace.CurrentCamera
	local dark = camera and camera:FindFirstChild(DARK_NAME)
	if dark then
		dark:Destroy()
	end
end

return PlayerView
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.RobotView", class = "ModuleScript", source = [=[
-- ReplicatedStorage.Obby.Views.RobotView (ModuleScript)
-- Robo Obby's robot view (Core.Games.Obby): what the operator at the real arm sees while the Obby is the
-- active game. The arcade port of lebot_obby/StarterPlayerScripts/OverseerCam.client.lua (Kushagra's
-- overseer view, his notes kept below), turned into enter(ctx) / exit():
--   * enter builds the panels and the overlay and turns the overseer view ON at once. The robot role has
--     no runner of its own to flip back to, so there is no V key. Zoom (wheel, - / =), right-drag pan, G
--     walls and the two buttons stay: they are the operator's controls.
--   * the robot has NO character. The "runner" it outlines and tracks on the mat grid is the player whose
--     Role attribute is "player" (fallback: any other player with a character).
--   * the world is workspace.ObbyMap (cloned in each round, ModelStreamingMode Persistent). It is waited for
--     by the paint loop, not by enter, so enter never holds up Core RoleClient; the bays sit Config.OriginZ
--     down +Z, so every Z worked out from a bay index adds it (bayZStart).
--   * Remotes.Status (activeBay, solveCells, level, resetToken, feedMode, linkOnline) and Remotes.BayCells
--     (the occupied cells) drive his order card and the mat grid; Remotes.Objective (the runner's task,
--     copied to the robot by the server, the win / lose screens included) shows top centre in his
--     ObjectiveHud order-board look. A status panel top left, under the Roblox top bar: the run clock
--     (ReplicatedStorage.Obby RunEndsAt / RunState), the feed mode, and ROBOT LINK OFFLINE when the feed
--     is live and the core link is down. His card, mat and buttons own the right-hand column; the two
--     arcade panels stay left of it and clear of it down to a 1024-wide screen.
--   * exit disconnects everything, stops the paint loop, puts back every LocalTransparencyModifier it
--     ghosted, destroys the overlay, the highlight and the GUI, unbinds its actions and puts the camera back
--     (FloodRobotView's savedCamera). Never touches Lighting.
--
-- OverseerCam (client) -- player 2's view of the bay.
--
-- The overseer's job is to put real cubes on a real mat and have them land in the right cells.
-- That needs a view where the 4x3 grid is legible, the runner is findable, and the obstacle is
-- visible at the same time. The runner's over-the-shoulder camera is none of those.
--
-- WHY NEARLY TOP-DOWN. Steep enough that the grid reads as a grid -- at a shallower angle the
-- far row foreshortens and "col 2, row 2" becomes a guess -- but tilted a few degrees toward
-- the entrance so the room keeps its walls and some sense of depth.
--
-- WALLS. Two layers are in the way and both are handled CLIENT-SIDE, so this is one viewer's
-- x-ray and not a change to the world -- the runner still sees solid walls around them:
--   * the warehouse shell, which surrounds every bay
--   * the bay's OWN walls and ceiling. Bay 4 is the acute case: the dark room is roofed at
--     y = 14, so without this the overseer is looking at the top of a closed box.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local ContextActionService = game:GetService("ContextActionService")
local CollectionService = game:GetService("CollectionService")
local Workspace = game:GetService("Workspace")

local Obby = ReplicatedStorage:WaitForChild("Obby")
local Config = require(Obby:WaitForChild("Config"))
local Ui = require(Obby:WaitForChild("UiTheme"))

local Remotes = Obby:WaitForChild("Remotes")
local Status = Remotes:WaitForChild("Status")
local BayCells = Remotes:WaitForChild("BayCells")
local Objective = Remotes:WaitForChild("Objective")

local player = Players.LocalPlayer

local MAP_NAME = "ObbyMap"
local CELL = Config.CellSize
local HEIGHT = 62          -- steep: the grid has to read as a grid
local SETBACK = 9          -- a few degrees of tilt so the room keeps its walls
-- HEIGHT and SETBACK were tuned on the default camera's field of view. The robot camera is fully
-- scripted and may arrive from another view with a different one, so the view sets it (and exit puts
-- the old one back).
local FOV = 70

local INK = Ui.C.parchment
local WANT = Ui.C.amber        -- the cell being asked for RIGHT NOW
local HELD = Ui.C.ok           -- already filled
local RUNNER = Ui.C.info       -- where player 1 is standing
local DIMMED = Ui.C.ghost

-- Arcade panels. His right-hand column (buttons, order card, mat) is 250 wide at 18 from the right
-- edge; the objective board is centred and the status panel sits top left, and both are sized so
-- neither reaches that column on a 1024-wide screen (460 + 2 * (250 + 18 + 12) = 1020).
local OBJ_W = 460
local OBJ_TOP = 16
local STATUS_W, STATUS_H = 250, 80
local STATUS_TOP = 64      -- under the Roblox top bar's buttons (the gui ignores the inset)
local TOAST_LIFE = 4.5     -- as ObjectiveHud's toasts: long enough to read a sentence

local RobotView = {}

local active = false
local activeBay = Config.LiveBay or 1
local generation = 0       -- bumped by exit: the paint loop of an older enter stops on it
local connections = {}
local savedCamera = nil
local map, warehouse = nil, nil

local function track(conn)
	table.insert(connections, conn)
	return conn
end

-- Course Z of bay i's entrance edge, in world space (RunControl.bayZStart): the map is baked
-- Config.OriginZ down +Z, so the old "bay 1 starts at Z = 0" needs the offset added back.
local function bayZStart(i)
	return Config.OriginZ + (i - 1) * Config.BayPitch
end

-- Camera the overseer can actually drive. A fixed shot is fine until you need to look at one
-- corner of the bay, which is most of the time once a run is underway.
--
-- PAN IS ON THE RIGHT MOUSE BUTTON, not on keys. Every key that reads as "move the view" --
-- WASD and the arrows alike -- is already a key that WALKS THE RUNNER, and in solo the
-- overseer and the runner are the same person. Panning with the arrows marched the character
-- out of the bay while the operator thought they were looking around.
-- (In the arcade the robot role has no character to walk, but the binding stays as he built it.)
local zoom, panX, panZ = 1, 0, 0
local ZOOM_MIN, ZOOM_MAX = 0.45, 2.3
local PAN_LIMIT = 26        -- studs from the bay centre; past that the bay leaves the screen
local PAN_PER_PIXEL = 0.09
local panning = false

-- X-ray is a toggle, not a fixture. Sometimes you want to see the room as the runner sees it
-- -- walls, roof and all -- and then put them back.
local xray = true
local xrayBtn, recenterBtn
local solveCells, bayName = nil, "?"
local bayLevel = nil          -- cubes per cell, for the order card
local occupied = {}
local markers = {}
local hidden = {}          -- part -> its real LocalTransparencyModifier
local highlight = nil
local status = nil         -- the last Remotes.Status payload

-- Built by buildGui at enter, dropped by exit.
local overlay
local gui, banner, sub, gridFrame
local card, crateHolder, colLabel, rowLabel, qtyLabel, progressLabel
local cellBtns = {}
local objectiveUi, statusUi

local function drawCrate(count)
	if not crateHolder then
		return
	end
	crateHolder:ClearAllChildren()
	if count and count > 0 then
		Ui.crateIcon(crateHolder, {count = count, anchor = Vector2.new(0.5, 1),
			position = UDim2.new(0.5, 0, 1, 0), size = UDim2.fromOffset(40, 58)})
	end
end

local function ctrlButton(text, y)
	local b = Instance.new("TextButton")
	b.AnchorPoint = Vector2.new(1, 0)
	b.Position = UDim2.new(1, -18, 0, y)
	b.Size = UDim2.fromOffset(250, 30)
	b.BackgroundColor3 = Ui.C.ironLight
	b.BorderSizePixel = 0
	b.AutoButtonColor = true
	b.Font = Ui.F.label
	b.TextSize = 11
	b.TextColor3 = Ui.C.faded
	b.Text = text
	b.ZIndex = 3
	b.Parent = gui
	Ui.corner(b, 4)
	Ui.stroke(b, Ui.C.brassDim, 1.5)
	Ui.sheen(b, 0.2)
	return b
end

----------------------------------------------------------------
-- The objective board (arcade)
----------------------------------------------------------------
-- The runner's task, ported from Views.Player.ObjectiveHud's order board (same look, same place:
-- top centre). The camera already aims past the bay's middle to keep the grid out from under it,
-- which is the layout this view was built around when the runner's HUD shared the screen. The
-- mode's win / lose screens arrive here too, as ordinary payloads.
-- Payload: {title, task, hint, tone, timer, timerLabel, timerTone, flash, steps, note}
-- `flash` is raised as one toast under the board, edge-detected like ObjectiveHud's (it persists in
-- every later push, so showing it while present would never take it down).
local function buildObjective(parent)
	local board = Ui.panel({
		parent = parent,
		name = "Objective",
		title = "",
		size = UDim2.fromOffset(OBJ_W, 140),
		position = UDim2.new(0.5, 0, 0, OBJ_TOP),
		anchor = Vector2.new(0.5, 0),
		tone = "danger",
		zindex = 2,
	})
	board.frame.Visible = false

	local taskLabel = Ui.text(board.body, {style = "task", text = "", size = UDim2.new(1, 0, 0, 32)})
	local hintLabel = Ui.text(board.body, {style = "hint", text = "",
		position = UDim2.fromOffset(0, 34), size = UDim2.new(1, 0, 0, 18), wrap = true})

	local timerBox = Instance.new("Frame")
	timerBox.Name = "TimerBox"
	timerBox.AnchorPoint = Vector2.new(0.5, 0)
	timerBox.Position = UDim2.new(0.5, 0, 0, 56)
	timerBox.Size = UDim2.fromOffset(150, 40)
	timerBox.BackgroundColor3 = Ui.C.ironDark
	timerBox.BorderSizePixel = 0
	timerBox.ZIndex = board.body.ZIndex + 1
	timerBox.Visible = false
	timerBox.Parent = board.body
	Ui.corner(timerBox, 4)
	Ui.stroke(timerBox, Ui.C.brassDim, 1.5)

	local timerCaption = Ui.text(timerBox, {style = "caption", text = "", align = Enum.TextXAlignment.Center,
		size = UDim2.new(1, 0, 0, 12), position = UDim2.fromOffset(0, 3)})
	local timerValue = Ui.text(timerBox, {style = "number", text = "", textSize = 24,
		size = UDim2.new(1, 0, 0, 24), position = UDim2.fromOffset(0, 14)})

	local stepLabels = {}
	for i = 1, 5 do
		stepLabels[i] = Ui.text(board.body, {style = "step", text = "",
			position = UDim2.fromOffset(8, 0), size = UDim2.new(1, -16, 0, 17)})
		stepLabels[i].Visible = false
	end

	local noteLabel = Ui.text(board.body, {style = "note", text = "", wrap = true,
		size = UDim2.new(1, -8, 0, 30)})
	noteLabel.Visible = false

	-- the flash toast: ObjectiveHud's toast look, one slot, under the board
	local toast = Instance.new("Frame")
	toast.Name = "Flash"
	toast.AnchorPoint = Vector2.new(0.5, 0)
	toast.Position = UDim2.new(0.5, 0, 0, OBJ_TOP + 150)
	toast.Size = UDim2.fromOffset(OBJ_W - 40, 32)
	toast.BackgroundColor3 = Ui.C.iron
	toast.BackgroundTransparency = 0.08
	toast.BorderSizePixel = 0
	toast.ZIndex = 5
	toast.Visible = false
	toast.Parent = parent
	Ui.corner(toast, 4)
	Ui.stroke(toast, Ui.C.warn, 1.5)
	Ui.sheen(toast, 0.25)

	local tab = Instance.new("Frame")
	tab.Size = UDim2.new(0, 4, 1, -10)
	tab.Position = UDim2.fromOffset(5, 5)
	tab.BackgroundColor3 = Ui.C.warn
	tab.BorderSizePixel = 0
	tab.ZIndex = 6
	tab.Parent = toast
	Ui.corner(tab, 2)

	local toastLabel = Ui.text(toast, {style = "step", text = "", textSize = 14,
		colour = Ui.C.parchment, position = UDim2.fromOffset(18, 0),
		size = UDim2.new(1, -26, 1, 0), zindex = 6})

	return {
		board = board, task = taskLabel, hint = hintLabel,
		timerBox = timerBox, timerCaption = timerCaption, timerValue = timerValue,
		steps = stepLabels, note = noteLabel,
		toast = toast, toastLabel = toastLabel, toastToken = 0, lastFlash = nil,
	}
end

local function showObjective(ui, p)
	if not p then
		ui.board.frame.Visible = false
		ui.toast.Visible = false
		ui.lastFlash = nil
		return
	end

	ui.board.frame.Visible = true
	ui.board.setTone(p.tone)
	ui.board.setTitle(p.title or "")
	ui.task.Text = p.task or ""
	ui.task.TextColor3 = Ui.tone(p.tone, Ui.C.amber)
	ui.hint.Text = p.hint or ""

	local y = 58
	if p.timer then
		ui.timerCaption.Text = p.timerLabel or ""
		-- whole seconds only; a ticking fraction reads as noise at this size
		local secs = math.max(0, math.floor(p.timer + 0.5))
		ui.timerValue.Text = string.format("%d:%02d", math.floor(secs / 60), secs % 60)
		ui.timerValue.TextColor3 = (p.timerTone and Ui.tone(p.timerTone))
			or (secs <= 10 and Ui.C.danger)
			or Ui.C.parchment
		ui.timerBox.Position = UDim2.new(0.5, 0, 0, y)
		ui.timerBox.Visible = true
		y += 48
	else
		ui.timerBox.Visible = false
	end

	local used = 0
	for idx, l in ipairs(ui.steps) do
		local text = p.steps and p.steps[idx]
		l.Visible = text ~= nil
		if text then
			used = idx
			l.Text = text
			l.TextColor3 = text:find("%[x%]") and Ui.C.ok
				or text:find("%[%-%]") and Ui.C.ghost
				or Ui.C.parchment
			l.Position = UDim2.fromOffset(8, y + (idx - 1) * 18)
		end
	end
	y += used * 18 + (used > 0 and 4 or 0)

	ui.note.Visible = p.note ~= nil
	if p.note then
		ui.note.Text = p.note
		ui.note.Position = UDim2.fromOffset(4, y)
		y += 32
	end

	local height = math.max(120, y + 34)
	ui.board.frame.Size = UDim2.fromOffset(OBJ_W, height)
	ui.toast.Position = UDim2.new(0.5, 0, 0, OBJ_TOP + height + 10)

	if p.flash and p.flash ~= ui.lastFlash then
		ui.toastToken += 1
		local mine = ui.toastToken
		ui.toastLabel.Text = tostring(p.flash):upper()
		ui.toast.Visible = true
		task.delay(TOAST_LIFE, function()
			if ui.toastToken == mine and ui.toast.Parent then
				ui.toast.Visible = false
			end
		end)
	end
	ui.lastFlash = p.flash
end

----------------------------------------------------------------
-- The status panel (arcade)
----------------------------------------------------------------
-- Top left: the run clock and who owns the crates this round. The accent bar carries the feed
-- state, so a dead robot link reads before any word does.
local function buildStatus(parent)
	local panel = Ui.panel({
		parent = parent,
		name = "RunStatus",
		size = UDim2.fromOffset(STATUS_W, STATUS_H),
		position = UDim2.fromOffset(18, STATUS_TOP),
		tone = "info",
		zindex = 3,
	})
	local clock = Ui.text(panel.body, {style = "number", text = "", textSize = 22,
		align = Enum.TextXAlignment.Left, size = UDim2.new(1, 0, 0, 24)})
	local feed = Ui.text(panel.body, {style = "caption", text = "",
		position = UDim2.fromOffset(0, 24), size = UDim2.new(1, 0, 0, 14)})
	local detail = Ui.text(panel.body, {style = "note", text = "", align = Enum.TextXAlignment.Left,
		position = UDim2.fromOffset(0, 38), size = UDim2.new(1, 0, 0, 14)})
	return {panel = panel, clock = clock, feed = feed, detail = detail}
end

local function formatClock(sec)
	sec = math.max(0, math.ceil(sec))
	return string.format("%d:%02d", sec // 60, sec % 60)
end

local function refreshStatus()
	if not statusUi then
		return
	end
	local state = Obby:GetAttribute("RunState")
	local endsAt = Obby:GetAttribute("RunEndsAt")
	local clock = statusUi.clock
	clock.TextColor3 = Ui.C.parchment
	if state == "Won" then
		clock.Text = "RUN CLEAR"
		clock.TextColor3 = Ui.C.ok
	elseif state == "Lost" then
		clock.Text = "RUN OVER"
		clock.TextColor3 = Ui.C.danger
	elseif state ~= nil and (type(endsAt) == "number" or Obby:GetAttribute("RunSeconds")) then
		local left = type(endsAt) == "number" and (endsAt - Workspace:GetServerTimeNow())
			or Obby:GetAttribute("RunSeconds")
		clock.Text = "RUN " .. formatClock(left) .. (state == "Ready" and "   READY" or "")
		if left < 30 then
			clock.TextColor3 = Ui.C.danger
		end
	else
		clock.Text = "ROBO OBBY"
		clock.TextColor3 = Ui.C.amber
	end

	local feedMode = Obby:GetAttribute("FeedMode") or (status and status.feedMode)
	local feed, detail = statusUi.feed, statusUi.detail
	if feedMode == "live" and status and status.linkOnline == false then
		statusUi.panel.setTone("danger")
		feed.Text = "ROBOT LINK OFFLINE"
		feed.TextColor3 = Ui.C.danger
		detail.Text = "the arm is not reaching the game"
	elseif feedMode == "live" then
		statusUi.panel.setTone("ok")
		feed.Text = "LIVE ROBOT"
		feed.TextColor3 = Ui.C.ok
		detail.Text = "your cubes place the crates"
	elseif feedMode == "solo" then
		statusUi.panel.setTone("warn")
		feed.Text = "SOLO"
		feed.TextColor3 = Ui.C.warn
		detail.Text = "the runner places the crates"
	else
		statusUi.panel.setTone("info")
		feed.Text = ""
		detail.Text = ""
	end
end

----------------------------------------------------------------
-- Panel
----------------------------------------------------------------
local function buildGui()
	gui = Instance.new("ScreenGui")
	gui.Name = "OverseerCam"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 12

	----------------------------------------------------------------
	-- THE ORDER CARD. The most important thing on player 2's screen.
	----------------------------------------------------------------
	-- Player 2's entire job is "put a cube on the mat at the right square". Everything they need
	-- for that is one coordinate and one quantity, and it used to be spelled out nowhere -- the
	-- old panel said "2 cells want a block" and left them to find which two on a 4x3 of
	-- identically-styled squares. This card answers it directly, in the largest type on screen,
	-- and the mat below is now the confirmation rather than the instruction.
	card = Ui.panel({
		parent = gui,
		name = "OrderCard",
		title = "NEXT BLOCK",
		size = UDim2.fromOffset(250, 150),
		position = UDim2.new(1, -18, 0, 92),
