	objectiveUi = buildObjective(gui)
	statusUi = buildStatus(gui)

	gui.Parent = player:WaitForChild("PlayerGui")
end

----------------------------------------------------------------
-- Keeping the card truthful
----------------------------------------------------------------
-- The "next" cell is the first wanted one not already filled, in the server's own solveCells
-- order -- so for a routed bay like the laser walk this follows the route rather than
-- inventing an order of its own.
local function nextWantedCell()
	for _, c in ipairs(solveCells or {}) do
		if not occupied[c[1] .. "," .. c[2]] then
			return c[1], c[2]
		end
	end
	return nil
end

local function refreshCard()
	if not card then
		return
	end
	local total = #(solveCells or {})
	local filled = 0
	for _, c in ipairs(solveCells or {}) do
		if occupied[c[1] .. "," .. c[2]] then
			filled += 1
		end
	end

	local col, row = nextWantedCell()
	if col then
		card.setTone("ok")
		card.setTitle("NEXT BLOCK")
		colLabel.Text = "COL " .. col
		rowLabel.Text = "ROW " .. row
		colLabel.TextColor3 = Ui.C.amber
		rowLabel.TextColor3 = Ui.C.amber
		qtyLabel.Text = (bayLevel and bayLevel > 1)
			and ("STACK " .. bayLevel .. " CUBES") or "ONE CUBE"
		drawCrate(bayLevel or 1)
	elseif total > 0 then
		card.setTone("ok")
		card.setTitle("ALL PLACED")
		colLabel.Text = "STAND"
		rowLabel.Text = "BY"
		colLabel.TextColor3 = Ui.C.ok
		rowLabel.TextColor3 = Ui.C.ok
		qtyLabel.Text = "NOTHING TO PLACE"
		drawCrate(nil)
	else
		-- an action bay: its cells are decided at runtime, or there are none at all
		card.setTone("warn")
		card.setTitle("NO CELL CALLED")
		colLabel.Text = "WAIT"
		rowLabel.Text = ""
		colLabel.TextColor3 = Ui.C.faded
		rowLabel.TextColor3 = Ui.C.faded
		qtyLabel.Text = "THIS BAY CLEARS BY ACTION"
		drawCrate(nil)
	end

	progressLabel.Text = (total > 0)
		and ("%d of %d cells filled"):format(filled, total)
		or "watch the runner"
end

----------------------------------------------------------------
-- In-world cell markers
----------------------------------------------------------------
local function clearMarkers()
	for _, m in ipairs(markers) do
		if m then
			m:Destroy()
		end
	end
	table.clear(markers)
end

local function wantedSet()
	local want = {}
	for _, c in ipairs(solveCells or {}) do
		want[c[1] .. "," .. c[2]] = true
	end
	return want
end

local function buildMarkers()
	clearMarkers()
	local bay = warehouse and warehouse:FindFirstChild(("Bay%02d"):format(activeBay))
	local anchors = bay and bay:FindFirstChild("CrateAnchors")
	if not (anchors and overlay) then
		return
	end
	local want = wantedSet()
	for col = 0, Config.BayCols - 1 do
		for row = 0, Config.BayRows - 1 do
			local a = anchors:FindFirstChild(("Cell_%d_%d"):format(col, row))
			if a then
				local key = col .. "," .. row
				local isWanted = want[key]
				local pad = Instance.new("Part")
				pad.Name = "OverseerCell_" .. key
				pad.Anchored = true
				pad.CanCollide = false
				pad.CanQuery = false
				pad.CanTouch = false
				pad.Size = Vector3.new(CELL - 1.2, 0.08, CELL - 1.2)
				pad.CFrame = CFrame.new(a.Position + Vector3.new(0, 0.1, 0))
				pad.Material = Enum.Material.Neon
				pad.Transparency = isWanted and 0.35 or 0.86
				pad.Color = isWanted and WANT or Color3.fromRGB(90, 130, 190)
				pad.Parent = overlay
				table.insert(markers, pad)

				local sg = Instance.new("SurfaceGui")
				sg.Face = Enum.NormalId.Top
				sg.LightInfluence = 0
				sg.PixelsPerStud = 36
				sg.Adornee = pad
				sg.Parent = pad
				local t = Instance.new("TextLabel")
				t.AnchorPoint = Vector2.new(0.5, 0.5)
				t.Position = UDim2.new(0.5, 0, 0.5, 0)
				t.Size = UDim2.new(0.62, 0, 0.42, 0)
				t.BackgroundColor3 = Color3.fromRGB(10, 14, 22)
				t.BackgroundTransparency = isWanted and 0.1 or 0.32
				t.BorderSizePixel = 0
				t.Font = Enum.Font.GothamBold
				t.Rotation = -90
				t.TextScaled = true
				t.TextColor3 = isWanted and Color3.fromRGB(130, 255, 170) or INK
				t.Text = ("%d,%d"):format(col, row)
				t.Parent = sg
				Instance.new("UICorner", t).CornerRadius = UDim.new(0.18, 0)
				local ts = Instance.new("UIStroke", t)
				ts.Color = isWanted and Color3.fromRGB(70, 200, 120)
					or Color3.fromRGB(80, 92, 112)
				ts.Thickness = 2
			end
		end
	end
end

----------------------------------------------------------------
-- X-ray: the shell, plus the active bay's own walls and ceiling.
----------------------------------------------------------------
local function ghost(part, amount)
	if part:IsA("BasePart") and hidden[part] == nil then
		hidden[part] = part.LocalTransparencyModifier
		part.LocalTransparencyModifier = amount
	end
end

local function ghostWalls(on)
	if not on then
		for p, v in pairs(hidden) do
			if p and p.Parent then
				p.LocalTransparencyModifier = v
			end
		end
		table.clear(hidden)
		return
	end
	if not warehouse then
		return -- the map has not streamed in yet; the paint loop re-applies this when it does
	end

	local shell = warehouse:FindFirstChild("Shell")
	for _, p in ipairs(shell and shell:GetChildren() or {}) do
		ghost(p, 0.92)
	end

	-- The roof trusses sit at y = 46, between a 62-stud camera and the floor, and laid two
	-- black bars straight across the bay. The rail beams are left alone: they are thin, they
	-- are where the crane actually rides, and seeing the crane is useful.
	local rails = warehouse:FindFirstChild("SkyRails")
	for _, p in ipairs(rails and rails:GetChildren() or {}) do
		if p.Name:match("^Truss") then
			ghost(p, 1)
		end
	end

	-- The crane hangs directly over the bay and is the single biggest thing between this
	-- camera and the floor. Faded rather than hidden: where the jaw is still tells the
	-- operator what the arm is doing. (SkyArm builds the rig inside the map in the arcade.)
	local rig = map and map:FindFirstChild("SkyArmRig")
	for _, p in ipairs(rig and rig:GetDescendants() or {}) do
		ghost(p, 0.75)
	end

	-- Backdrop scenery over the course -- the hall's roof deck, skylight and arch ribs --
	-- carries the "OverseerHide" tag instead of being enumerated here: the generators in
	-- build/ own the tag, this script just honours it. Hidden outright (not faded) because
	-- at zoom-out the camera rises to ~143 and all of it sits between camera and floor.
	-- Only the obby's own: another game's map may use the tag too.
	for _, p in ipairs(CollectionService:GetTagged("OverseerHide")) do
		if map and p:IsDescendantOf(map) then
			ghost(p, 1)
		end
	end

	-- The bay's own box. Matched by NAME rather than by size or position, because a bay builds
	-- whatever it needs and only its walls and roof should disappear -- the obstacle itself has
	-- to stay visible, which is the entire point of looking.
	local bay = warehouse:FindFirstChild(("Bay%02d"):format(activeBay))
	local obst = bay and bay:FindFirstChild("Obstacle")
	for _, p in ipairs(obst and obst:GetChildren() or {}) do
		local n = p.Name
		if n:match("Ceiling") then
			ghost(p, 1)            -- a roof between camera and floor has to go entirely
		elseif n:match("Wall") or n:match("SideRail") then
			ghost(p, 0.82)         -- walls stay faintly, so the room keeps its shape
		end
	end
end

----------------------------------------------------------------
-- The runner. Outlined, so they are findable in a dark room or behind an obstacle.
----------------------------------------------------------------
-- The robot role has no character of its own: the runner is the player role (Core.Roles), or,
-- with no roles assigned, whoever else has a body.
local function runnerCharacter()
	local fallback = nil
	for _, p in ipairs(Players:GetPlayers()) do
		if p ~= player and p.Character then
			if p:GetAttribute("Role") == "player" then
				return p.Character
			end
			fallback = fallback or p.Character
		end
	end
	return fallback
end

local function setHighlight(on)
	if highlight then
		highlight:Destroy()
		highlight = nil
	end
	if not on then
		return
	end
	local ch = runnerCharacter()
	if not ch then
		return
	end
	highlight = Instance.new("Highlight")
	highlight.FillColor = Color3.fromRGB(120, 210, 255)
	highlight.FillTransparency = 0.5
	highlight.OutlineColor = Color3.fromRGB(200, 240, 255)
	highlight.OutlineTransparency = 0
	highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	highlight.Adornee = ch
	highlight.Parent = ch
end

local function runnerCell()
	local ch = runnerCharacter()
	local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return nil
	end
	local zStart = bayZStart(activeBay)
	local col = math.floor(hrp.Position.X / CELL)
	local row = math.floor((hrp.Position.Z - zStart) / CELL)
	if col < 0 or col >= Config.BayCols or row < 0 or row >= Config.BayRows then
		return nil
	end
	return col .. "," .. row
end

----------------------------------------------------------------
-- The view
----------------------------------------------------------------
local function aimCamera()
	local cam = Workspace.CurrentCamera
	if not cam then
		return
	end
	local zStart = bayZStart(activeBay)
	local midX = Config.BayWidth / 2
	local midZ = zStart + Config.BayDepth / 2
	-- Aimed past the middle of the bay, which pushes the whole grid DOWN the screen and out
	-- from under the objective panel. Aiming at the centre put the far row behind it.
	local h = HEIGHT * zoom
	local back = SETBACK * zoom
	-- Clamped, because an unbounded pan is a way to lose the bay entirely and no way to find
	-- it again: a few flicks and the operator is staring at empty sky with no horizon to
	-- steer by. The limit scales with zoom -- zoomed out you can afford to roam further.
	local lim = PAN_LIMIT * zoom
	panX = math.clamp(panX, -lim, lim)
	panZ = math.clamp(panZ, -lim, lim)
	cam.CameraType = Enum.CameraType.Scriptable
	cam.CFrame = CFrame.lookAt(
		Vector3.new(midX + panX, h, midZ - back + panZ),
		Vector3.new(midX + panX, 0, midZ + 10 + panZ))
end

local nextKey = nil        -- the one cell the operator should be reaching for

local function paintGrid()
	local want = wantedSet()
	local here = runnerCell()
	local nc, nr = nextWantedCell()
	nextKey = nc and (nc .. "," .. nr) or nil

	for key, c in pairs(cellBtns) do
		local isNext = (key == nextKey)
		local isWanted = want[key]
		local isHeld = occupied[key]
		local isHere = (key == here)

		-- Priority is deliberate and is the whole point of the redesign: THE NEXT CELL WINS.
		-- Everything else on this grid is context. Before, every wanted cell was painted the
		-- same green and the operator had to work out which of them to do first.
		if isNext then
			c.frame.BackgroundColor3 = Color3.fromRGB(58, 42, 18)
			c.stroke.Color = WANT
			c.stroke.Thickness = 3
			c.label.TextColor3 = WANT
		elseif isHeld then
			c.frame.BackgroundColor3 = Color3.fromRGB(22, 46, 32)
			c.stroke.Color = HELD
			c.stroke.Thickness = 2
			c.label.TextColor3 = HELD
		elseif isWanted then
			c.frame.BackgroundColor3 = Color3.fromRGB(40, 32, 20)
			c.stroke.Color = Ui.C.brassDim
			c.stroke.Thickness = 1.5
			c.label.TextColor3 = Ui.C.faded
		else
			c.frame.BackgroundColor3 = Ui.C.ironDark
			c.stroke.Color = Ui.C.brassDim
			c.stroke.Thickness = 1
			c.label.TextColor3 = DIMMED
		end
		if not isNext then
			-- the pulse below only ever writes the next cell; one that stops being next keeps
			-- whatever fade it was left at unless it is put back here
			c.stroke.Transparency = 0
		end

		-- the runner's square is marked on top of whatever it already is
		if isHere then
			c.stroke.Color = RUNNER
			c.stroke.Thickness = 3
		end
	end

	refreshCard()
end

-- On only at enter, off only at exit: the robot never hands the camera to a runner of its own.
-- Off leaves the camera alone; exit puts back the one it saved.
local function setActive(on)
	active = on
	if gui then
		gui.Enabled = on
	end
	if on then
		ghostWalls(xray)
		setHighlight(true)
		buildMarkers()
		aimCamera()
		paintGrid()
	else
		clearMarkers()
		panning = false
		ghostWalls(false)
		setHighlight(false)
	end
end

local function refreshBanner()
	if not (banner and sub) then
		return
	end
	banner.Text = ("OVERSEER VIEW   -   BAY %02d   -   %s"):format(activeBay, bayName:upper())
	sub.Text = ("scroll or -/= zoom   .   right-drag pan   .   G walls %s")
		:format(xray and "see-through" or "solid")
end

-- X-RAY, one place. It is reached three ways -- the G key, the on-screen button, and a bay
-- change re-applying it -- and having each of those poke the flag by hand is how the banner
-- and the world drifted apart.
--
-- G IS CLAIMED THROUGH ContextActionService, not UserInputService.InputBegan. V arrives on
-- InputBegan and G did not: something upstream was marking it handled, and InputBegan's
-- gameProcessedEvent guard then dropped it before this script ever saw it. A bound action
-- sits above that and sinks the key, so the binding holds regardless of who else wants it.
local function setXray(on)
	xray = on
	ghostWalls(false)
	ghostWalls(xray)
	refreshBanner()
	if xrayBtn then
		xrayBtn.Text = xray and "WALLS: SEE-THROUGH  (G)" or "WALLS: SOLID  (G)"
		xrayBtn.BackgroundColor3 = xray and Color3.fromRGB(26, 52, 86) or Color3.fromRGB(34, 38, 48)
		xrayBtn.TextColor3 = xray and HELD or DIMMED
	end
end

-- ZOOM IS BOUND THE SAME WAY, AND FOR THE SAME REASON. Roblox's own camera module claims the
-- mouse wheel through ContextActionService, so by the time a wheel turn reaches
-- InputChanged it is already flagged handled and a gameProcessedEvent guard eats it --
-- CameraType = Scriptable stops the module MOVING the camera, it does not stop it listening.
-- Binding above it is the only way to get the wheel.
--
-- The - and = keys do the same job. A wheel is not a given -- half of demoing this happens on
-- a laptop trackpad -- and a contested input with no alternative is one that just fails.
local function stepZoom(by)
	zoom = math.clamp(zoom + by, ZOOM_MIN, ZOOM_MAX)
	aimCamera()
end

local ACTION_ZOOM, ACTION_XRAY = "OverseerZoom", "OverseerXray"

local function bindActions()
	ContextActionService:BindActionAtPriority(ACTION_ZOOM, function(_, state, input)
		if not active then
			return Enum.ContextActionResult.Pass
		end
		if input.UserInputType == Enum.UserInputType.MouseWheel then
			if state == Enum.UserInputState.Change and input.Position.Z ~= 0 then
				stepZoom(-input.Position.Z * 0.12)
			end
		elseif state == Enum.UserInputState.Begin then
			stepZoom(input.KeyCode == Enum.KeyCode.Minus and 0.18 or -0.18)
		end
		return Enum.ContextActionResult.Sink
	end, false, Enum.ContextActionPriority.High.Value,
		Enum.UserInputType.MouseWheel, Enum.KeyCode.Minus, Enum.KeyCode.Equals)

	ContextActionService:BindActionAtPriority(ACTION_XRAY, function(_, state)
		if not active then
			return Enum.ContextActionResult.Pass
		end
		if state == Enum.UserInputState.Begin then
			setXray(not xray)
		end
		return Enum.ContextActionResult.Sink
	end, false, Enum.ContextActionPriority.High.Value, Enum.KeyCode.G)
end

local resetToken = nil

local function onStatus(s)
	if type(s) ~= "table" then
		return
	end
	status = s
	-- A full reset puts the course back to bay 1, which usually reads as a bay change -- but
	-- not when you full-reset while already on bay 1, and then the camera kept whatever zoom
	-- and pan the last run left it with. The token changes either way.
	local wasReset = resetToken ~= nil and s.resetToken ~= resetToken
	resetToken = s.resetToken

	local moved = s.activeBay ~= activeBay or wasReset
	activeBay = s.activeBay or activeBay
	local info = s.bays and s.bays[activeBay]
	solveCells = info and info.solveCells or nil
	bayName = info and info.obstacle or "?"
	bayLevel = info and info.level or nil
	if moved then
		occupied = {}
		zoom, panX, panZ = 1, 0, 0    -- a new bay gets the default framing back
	end
	refreshBanner()
	refreshStatus()
	if active then
		-- the bay moved under us, or a solve changed which cells matter, and the x-ray has to
		-- follow: the walls being ghosted belong to the bay we were looking at
		ghostWalls(false)
		ghostWalls(xray)
		buildMarkers()
		paintGrid()
		if moved then
			aimCamera()
		end
	end
end

-- The map is cloned in by the mode each round and streams in as one piece (Persistent). Found
-- (or lost) here, from the paint loop, so enter never waits on it.
local function findMap()
	local m = Workspace:FindFirstChild(MAP_NAME)
	local w = m and m:FindFirstChild("Warehouse")
	if w == warehouse and m == map then
		return
	end
	ghostWalls(false)     -- whatever was ghosted belonged to the old map
	map, warehouse = m, w
	if active then
		ghostWalls(xray)
		buildMarkers()    -- clears the old map's markers too, when there is no new one
		paintGrid()
		if warehouse then
			Status:FireServer() -- the bay and its wanted cells, now that there is a bay to mark
		end
	end
end

function RobotView.enter(_ctx)
	RobotView.exit()
	generation += 1
	local myGeneration = generation

	-- Core RoleClient has already made the robot's camera Scriptable; saved anyway, so exit hands
	-- back exactly what enter found (FloodRobotView's pattern).
	local cam = Workspace.CurrentCamera
	savedCamera = {camera = cam, type = cam.CameraType, cframe = cam.CFrame, fov = cam.FieldOfView}
	cam.CameraType = Enum.CameraType.Scriptable
	cam.FieldOfView = FOV

	overlay = Instance.new("Folder")
	overlay.Name = "OverseerOverlay"
	overlay.Parent = Workspace

	buildGui()
	setXray(xray)
	refreshStatus()

	bindActions()

	track(xrayBtn.MouseButton1Click:Connect(function()
		setXray(not xray)
	end))

	track(recenterBtn.MouseButton1Click:Connect(function()
		zoom, panX, panZ = 1, 0, 0
		aimCamera()
	end))

	track(Status.OnClientEvent:Connect(onStatus))

	track(BayCells.OnClientEvent:Connect(function(bayIndex, cellsList)
		if bayIndex ~= activeBay then
			return
		end
		local now = {}
		for _, c in ipairs(cellsList or {}) do
			now[c.col .. "," .. c.row] = true
		end
		occupied = now
		if active then
			paintGrid()
		end
	end))

	track(Objective.OnClientEvent:Connect(function(p)
		if objectiveUi then
			showObjective(objectiveUi, p)
		end
	end))

	for _, name in ipairs({"RunState", "RunEndsAt", "FeedMode"}) do
		track(Obby:GetAttributeChangedSignal(name):Connect(refreshStatus))
	end

	track(UserInputService.InputBegan:Connect(function(input)
		-- Right button starts a pan. The processed guard is skipped on purpose: the operator
		-- grabs the view by dragging over the middle of the screen, and the objective panel and
		-- the mini grid both sit in that space.
		if active and input.UserInputType == Enum.UserInputType.MouseButton2 then
			panning = true
		end
	end))

	track(UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton2 then
			panning = false
		end
	end))

	-- Right-drag to pan. No processed guard: the drag starts over the middle of the screen,
	-- where the objective panel and the mini grid both live. (Zoom is a bound action, above.)
	track(UserInputService.InputChanged:Connect(function(input)
		if not active then
			return
		end
		if panning and input.UserInputType == Enum.UserInputType.MouseMovement then
			-- The camera looks down -Z-ish, so screen-right is world +X and screen-up is world
			-- +Z. Scaled by zoom so a drag covers the same amount of SCREEN at any zoom.
			panX -= input.Delta.X * PAN_PER_PIXEL * zoom
			panZ += input.Delta.Y * PAN_PER_PIXEL * zoom
			aimCamera()
		end
	end))

	-- The camera is re-asserted every frame rather than only when it moves: Roblox hands the
	-- camera back to the default scripts on a few CoreGui transitions, and a one-shot CFrame
	-- would silently lose the view.
	track(RunService.RenderStepped:Connect(function()
		if not active then
			return
		end
		aimCamera()
		-- A slow breath on the one cell being asked for. Motion is what the eye finds first in a
		-- grid of twelve identical squares, and it costs one property write a frame.
		local c = nextKey and cellBtns[nextKey]
		if c then
			c.stroke.Transparency = 0.35 + 0.35 * math.sin(os.clock() * 4)
		end
	end))

	findMap()
	setActive(true)

	-- The runner's cell changes as they move, which no event reports. The same beat finds the map
	-- once it streams in, re-outlines the runner after a respawn (the highlight dies with the old
	-- character) and ticks the run clock.
	task.spawn(function()
		while generation == myGeneration do
			if active then
				findMap()
				local ch = runnerCharacter()
				if ch and not (highlight and highlight.Parent == ch) then
					setHighlight(true)
				end
				paintGrid()
				refreshStatus()
			end
			task.wait(0.25)
		end
	end)

	Status:FireServer()
	print("[RobotView] overseer view on")
end

function RobotView.exit()
	generation += 1 -- stops the paint loop
	setActive(false)
	ContextActionService:UnbindAction(ACTION_ZOOM)
	ContextActionService:UnbindAction(ACTION_XRAY)
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	if overlay then
		overlay:Destroy()
		overlay = nil
	end
	if gui then
		gui:Destroy()
		gui, banner, sub, gridFrame, xrayBtn, recenterBtn = nil, nil, nil, nil, nil, nil
		card, crateHolder, colLabel, rowLabel, qtyLabel, progressLabel = nil, nil, nil, nil, nil, nil
		objectiveUi, statusUi = nil, nil
		cellBtns = {}
	end
	map, warehouse, status, resetToken = nil, nil, nil, nil
	occupied, solveCells, bayName, bayLevel, nextKey = {}, nil, "?", nil, nil
	activeBay = Config.LiveBay or 1
	zoom, panX, panZ = 1, 0, 0
	if savedCamera then
		local camera = savedCamera.camera
		if camera and camera.Parent then
			camera.FieldOfView = savedCamera.fov
			camera.CameraType = savedCamera.type
			camera.CFrame = savedCamera.cframe
		end
		savedCamera = nil
	end
end

return RobotView
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Player.ObjectiveHud", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Player.ObjectiveHud (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner and, read only, for spectators). Its ScreenGui carries ObbyView = true and goes
-- when the copy's Exiting attribute is set. Arcade addition: the run clock pill to the right of the order
-- board (ReplicatedStorage.Obby RunEndsAt / RunState; hidden between rounds). The win / lose screens are
-- ordinary Objective payloads from the server. Remotes live in ReplicatedStorage.Obby.Remotes; the old
-- DebugStatus feed is Remotes.Status (same payload plus extra fields).
--
-- ObjectiveHud -- what the bay wants, how long you have, and anything that just happened.
--
-- Driven entirely by the server: an obstacle fires Remotes.Objective with a payload when its
-- state changes, and firing nil clears the HUD so a player outside the bay isn't being told to
-- do anything.
--
-- Payload: {title, task, hint, tone, timer, timerLabel, timerTone, flash, steps, note}
--
-- THREE LAYERS, deliberately separated, because they answer different questions and used to
-- be crammed into one panel:
--
--   1. THE ORDER BOARD (top centre)  -- a standing statement of what this bay wants. It
--      changes rarely and you should be able to ignore it once you have read it.
--   2. TOASTS (under the board)      -- something JUST happened: a block was refused, a lever
--      threw, a screw was found. Transient, stacked, self-expiring.
--   3. THE STAMP (screen centre)     -- the big one. A bay was cleared, or you died. It
--      interrupts, it animates, and it gets out of the way on its own.
--
-- The old HUD had only layer 1, so a refused block was a line of text that appeared inside a
-- panel you had already stopped reading. Events need to move to be noticed.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")

local Obby = ReplicatedStorage:WaitForChild("Obby")
local Ui = require(Obby:WaitForChild("UiTheme"))

local Remotes = Obby:WaitForChild("Remotes")
local Objective = Remotes:WaitForChild("Objective")
local Status = Remotes:WaitForChild("Status")
local Toast = Remotes:WaitForChild("Toast")

local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")
-- Spectator copy (Views.PlayerView sets ReadOnly): it mirrors the runner and sends nothing.
local readOnly = script:GetAttribute("ReadOnly") == true
local connections = {}
local alive = true -- false once Exiting has run; delayed callbacks check it

local gui = Instance.new("ScreenGui")
gui.Name = "ObjectiveHud"
gui.ResetOnSpawn = false
gui.IgnoreGuiInset = true
gui.DisplayOrder = 10
gui:SetAttribute("ObbyView", true)
gui.Parent = playerGui

local PANEL_W = 500

----------------------------------------------------------------
-- 1. The order board
----------------------------------------------------------------
local board = Ui.panel({
	parent = gui,
	name = "OrderBoard",
	title = "",
	size = UDim2.fromOffset(PANEL_W, 140),
	position = UDim2.new(0.5, 0, 0, 16),
	anchor = Vector2.new(0.5, 0),
	tone = "danger",
	zindex = 2,
})
board.frame.Visible = false

local taskLabel = Ui.text(board.body, {style = "task", text = "", size = UDim2.new(1, 0, 0, 32)})
local hintLabel = Ui.text(board.body, {style = "hint", text = "",
	position = UDim2.fromOffset(0, 34), size = UDim2.new(1, 0, 0, 18), wrap = true})

-- Timer: a brass-framed readout, because a number floating in space reads as debug output.
local timerBox = Instance.new("Frame")
timerBox.Name = "TimerBox"
timerBox.AnchorPoint = Vector2.new(0.5, 0)
timerBox.Position = UDim2.new(0.5, 0, 0, 56)
timerBox.Size = UDim2.fromOffset(150, 40)
timerBox.BackgroundColor3 = Ui.C.ironDark
timerBox.BorderSizePixel = 0
timerBox.ZIndex = board.body.ZIndex + 1
timerBox.Visible = false
timerBox.Parent = board.body
Ui.corner(timerBox, 4)
Ui.stroke(timerBox, Ui.C.brassDim, 1.5)

local timerCaption = Ui.text(timerBox, {style = "caption", text = "", align = Enum.TextXAlignment.Center,
	size = UDim2.new(1, 0, 0, 12), position = UDim2.fromOffset(0, 3)})
local timerValue = Ui.text(timerBox, {style = "number", text = "", textSize = 24,
	size = UDim2.new(1, 0, 0, 24), position = UDim2.fromOffset(0, 14)})

local stepLabels = {}
for i = 1, 5 do
	stepLabels[i] = Ui.text(board.body, {style = "step", text = "",
		position = UDim2.fromOffset(8, 0), size = UDim2.new(1, -16, 0, 17)})
	stepLabels[i].Visible = false
end

local noteLabel = Ui.text(board.body, {style = "note", text = "", wrap = true,
	size = UDim2.new(1, -8, 0, 30)})
noteLabel.Visible = false

----------------------------------------------------------------
-- 2. Toasts
----------------------------------------------------------------
-- A stack under the board. Newest at the top, each one shoving the others down, each one
-- removing itself. Capped, because an obstacle that refuses ten blocks in a row should not
-- own the whole screen.
local TOAST_MAX = 3
local TOAST_LIFE = 4.5   -- long enough to actually read a sentence before it goes
local toasts = {}

local toastHolder = Instance.new("Frame")
toastHolder.Name = "Toasts"
toastHolder.AnchorPoint = Vector2.new(0.5, 0)
toastHolder.Position = UDim2.new(0.5, 0, 0, 170)
toastHolder.Size = UDim2.fromOffset(PANEL_W, 140)
toastHolder.BackgroundTransparency = 1
toastHolder.ZIndex = 4
toastHolder.Parent = gui

local function layoutToasts()
	for i, t in ipairs(toasts) do
		TweenService:Create(t.frame, TweenInfo.new(0.18, Enum.EasingStyle.Quad), {
			Position = UDim2.new(0.5, 0, 0, (i - 1) * 38),
		}):Play()
	end
end

local function dismissToast(entry)
	local idx = table.find(toasts, entry)
	if not idx then
		return
	end
	table.remove(toasts, idx)
	local out = TweenService:Create(entry.frame, TweenInfo.new(0.22, Enum.EasingStyle.Quad), {
		BackgroundTransparency = 1,
		Position = entry.frame.Position + UDim2.fromOffset(0, -10),
	})
	for _, d in ipairs(entry.frame:GetDescendants()) do
		if d:IsA("TextLabel") then
			TweenService:Create(d, TweenInfo.new(0.22), {TextTransparency = 1}):Play()
		elseif d:IsA("UIStroke") then
			TweenService:Create(d, TweenInfo.new(0.22), {Transparency = 1}):Play()
		end
	end
	out.Completed:Connect(function()
		entry.frame:Destroy()
	end)
	out:Play()
	layoutToasts()
end

local function showToast(text, tone)
	if not text or text == "" then
		return
	end
	-- Normalised to caps. These come from two different server paths -- a guard's rejection
	-- reason ("blades live") and an obstacle's own notice ("BLADES LIVE - CANNOT DROP
	-- THERE") -- and side by side in the same stack the mixed casing read like a bug. The
	-- toast is signage; signage shouts.
	text = text:upper()
	-- Repeat of the message already on top? Refresh it instead of stacking a duplicate --
	-- a guard refusing the same cell twice is one event the player needs to see, not two.
	local top = toasts[1]
	if top and top.text == text then
		top.expires = os.clock() + TOAST_LIFE
		return
	end

	local frame = Instance.new("Frame")
	frame.AnchorPoint = Vector2.new(0.5, 0)
	frame.Position = UDim2.new(0.5, 0, 0, -10)
	frame.Size = UDim2.fromOffset(PANEL_W - 40, 32)
	frame.BackgroundColor3 = Ui.C.iron
	frame.BackgroundTransparency = 0.08
	frame.BorderSizePixel = 0
	frame.ZIndex = 5
	frame.Parent = toastHolder
	Ui.corner(frame, 4)
	Ui.stroke(frame, Ui.tone(tone, Ui.C.brass), 1.5)
	Ui.sheen(frame, 0.25)

	-- a tone-coloured tab on the left edge, so the kind of event reads before the words
	local tab = Instance.new("Frame")
	tab.Size = UDim2.new(0, 4, 1, -10)
	tab.Position = UDim2.fromOffset(5, 5)
	tab.BackgroundColor3 = Ui.tone(tone, Ui.C.brass)
	tab.BorderSizePixel = 0
	tab.ZIndex = 6
	tab.Parent = frame
	Ui.corner(tab, 2)

	Ui.text(frame, {style = "step", text = text, textSize = 14,
		colour = Ui.C.parchment, position = UDim2.fromOffset(18, 0),
		size = UDim2.new(1, -26, 1, 0), zindex = 6})

	local entry = {frame = frame, text = text, expires = os.clock() + TOAST_LIFE}
	table.insert(toasts, 1, entry)
	while #toasts > TOAST_MAX do
		dismissToast(toasts[#toasts])
	end
	layoutToasts()
end

----------------------------------------------------------------
-- 3. The stamp
----------------------------------------------------------------
-- Centre screen, big, brief. Scales down onto the screen like a stamp hitting paper rather
-- than fading in, because the whole point is that you cannot miss it.
local stamp = Ui.panel({
	parent = gui,
	name = "Stamp",
	size = UDim2.fromOffset(440, 96),
	position = UDim2.new(0.5, 0, 0.36, 0),
	anchor = Vector2.new(0.5, 0.5),
	tone = "ok",
	zindex = 8,
})
stamp.frame.Visible = false
stamp.frame.BackgroundTransparency = 0.04

local stampTitle = Ui.text(stamp.body, {style = "big", text = "", size = UDim2.new(1, 0, 0, 40)})
local stampSub = Ui.text(stamp.body, {style = "hint", text = "", textSize = 14,
	position = UDim2.fromOffset(0, 42), size = UDim2.new(1, 0, 0, 18)})

local stampToken = 0
local function showStamp(title, sub, tone)
	stampToken += 1
	local mine = stampToken
	stamp.setTone(tone or "ok")
	stampTitle.Text = title
	stampTitle.TextColor3 = Ui.tone(tone, Ui.C.amber)
	stampSub.Text = sub or ""
	stamp.frame.Visible = true
	stamp.frame.Size = UDim2.fromOffset(560, 122)
	TweenService:Create(stamp.frame, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
		Size = UDim2.fromOffset(440, 96),
	}):Play()

	task.delay(2.4, function()
		if not alive or stampToken ~= mine then
			return
		end
		local out = TweenService:Create(stamp.frame, TweenInfo.new(0.3), {BackgroundTransparency = 1})
		TweenService:Create(stampTitle, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
		TweenService:Create(stampSub, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
		out.Completed:Connect(function()
			if stampToken == mine then
				stamp.frame.Visible = false
				stamp.frame.BackgroundTransparency = 0.04
				stampTitle.TextTransparency = 0
				stampSub.TextTransparency = 0
			end
		end)
		out:Play()
	end)
end

----------------------------------------------------------------
-- Wiring
----------------------------------------------------------------
local lastFlash = nil

table.insert(connections, Objective.OnClientEvent:Connect(function(p)
	if not p then
		board.frame.Visible = false
		lastFlash = nil
		return
	end

	board.frame.Visible = true
	board.setTone(p.tone)
	board.setTitle(p.title or "")
	taskLabel.Text = p.task or ""
	taskLabel.TextColor3 = Ui.tone(p.tone, Ui.C.amber)
	hintLabel.Text = p.hint or ""

	local y = 58
	if p.timer then
		timerCaption.Text = p.timerLabel or ""
		local secs = math.max(0, math.floor(p.timer + 0.5))
		timerValue.Text = string.format("%d:%02d", math.floor(secs / 60), secs % 60)
		timerValue.TextColor3 = (p.timerTone and Ui.tone(p.timerTone))
			or (secs <= 10 and Ui.C.danger)
			or Ui.C.parchment
		timerBox.Position = UDim2.new(0.5, 0, 0, y)
		timerBox.Visible = true
		y += 48
	else
		timerBox.Visible = false
	end

	local used = 0
	for idx, l in ipairs(stepLabels) do
		local text = p.steps and p.steps[idx]
		l.Visible = text ~= nil
		if text then
			used = idx
			l.Text = text
			l.TextColor3 = text:find("%[x%]") and Ui.C.ok
				or text:find("%[%-%]") and Ui.C.ghost
				or Ui.C.parchment
			l.Position = UDim2.fromOffset(8, y + (idx - 1) * 18)
		end
	end
	y += used * 18 + (used > 0 and 4 or 0)

	noteLabel.Visible = p.note ~= nil
	if p.note then
		noteLabel.Text = p.note
		noteLabel.Position = UDim2.fromOffset(4, y)
		y += 32
	end

	board.frame.Size = UDim2.fromOffset(PANEL_W, math.max(120, y + 34))
	toastHolder.Position = UDim2.new(0.5, 0, 0, 16 + board.frame.Size.Y.Offset + 10)

	-- `flash` is the server's refusal channel. It arrives merged into the next objective push
	-- and persists in the payload, so it has to be edge-detected or every subsequent push
	-- re-raises the same toast.
	if p.flash and p.flash ~= lastFlash then
		showToast(p.flash, "warn")
	end
	lastFlash = p.flash
end))

-- Direct event channel: obstacles announce things that are not a change of objective.
table.insert(connections, Toast.OnClientEvent:Connect(function(text, tone, big)
	if big then
		showStamp(text, nil, tone)
	else
		showToast(text, tone)
	end
end))

-- Bay cleared. Taken from the status feed rather than from the objective payload, because
-- `solved` is the authoritative edge and a bay may clear its objective on the same frame.
-- (Arcade: the feed is Remotes.Status, the old DebugStatus payload plus a few extra fields.)
local wasSolved = {}
table.insert(connections, Status.OnClientEvent:Connect(function(status)
	if type(status) ~= "table" then
		return
	end
	for i, b in pairs(status.bays or {}) do
		if b.solved and wasSolved[i] == false then
			showStamp("BAY " .. string.format("%02d", i) .. "  CLEARED",
				(b.obstacle or ""):upper(), "ok")
		end
		wasSolved[i] = b.solved or false
	end
end))

-- Death, worth a stamp of its own: the respawn is silent otherwise and in a dark room you
-- genuinely cannot tell you died. (Arcade: not on a spectator's copy -- the spectator's own
-- character is not the one running the course.)
local diedConn = nil
local function watchCharacter(ch)
	local hum = ch:WaitForChild("Humanoid", 5)
	if hum and alive then
		if diedConn then
			diedConn:Disconnect()
		end
		diedConn = hum.Died:Connect(function()
			showStamp("YOU DIED", "the machine resets", "danger")
		end)
	end
end
if not readOnly then
	table.insert(connections, player.CharacterAdded:Connect(watchCharacter))
	if player.Character then
		-- spawned, so the Humanoid wait can't hold up the rest of this script (the Exiting hook)
		task.spawn(watchCharacter, player.Character)
	end
end

-- Toast expiry.
table.insert(connections, RunService.Heartbeat:Connect(function()
	local now = os.clock()
	for i = #toasts, 1, -1 do
		if now >= toasts[i].expires then
			dismissToast(toasts[i])
		end
	end
end))

----------------------------------------------------------------
-- The run clock (arcade)
----------------------------------------------------------------
-- The whole course has one, and it is the win condition. A brass-framed readout in the same
-- style as the bay timer, sitting to the right of the order board's top edge so it never covers
-- the board or the toast stack under it, and is there even between bays when the board is hidden.
local CLOCK_W, CLOCK_H = 112, 46
local clock = Instance.new("Frame")
clock.Name = "RunClock"
clock.AnchorPoint = Vector2.new(0, 0)
clock.Position = UDim2.new(0.5, PANEL_W / 2 + 12, 0, 16)
clock.Size = UDim2.fromOffset(CLOCK_W, CLOCK_H)
clock.BackgroundColor3 = Ui.C.iron
clock.BackgroundTransparency = 0.06
clock.BorderSizePixel = 0
clock.ZIndex = 2
clock.Visible = false
clock.Parent = gui
Ui.corner(clock, 5)
Ui.sheen(clock, 0.3)
local clockEdge = Ui.stroke(clock, Ui.C.brass, 2)

Ui.text(clock, {style = "caption", text = "RUN", align = Enum.TextXAlignment.Center,
	size = UDim2.new(1, 0, 0, 12), position = UDim2.fromOffset(0, 4), zindex = 3})
local clockValue = Ui.text(clock, {style = "number", text = "", textSize = 24,
	size = UDim2.new(1, 0, 0, 26), position = UDim2.fromOffset(0, 16), zindex = 3})

local function refreshClock()
	local state = Obby:GetAttribute("RunState")
	local endsAt = Obby:GetAttribute("RunEndsAt")
	if state == nil then
		clock.Visible = false
		return
	end
	clock.Visible = true
	if state == "Won" then
		clockValue.Text = "CLEAR"
		clockValue.TextColor3 = Ui.C.ok
		clockEdge.Color = Ui.C.ok
		return
	end
	local left = type(endsAt) == "number" and math.max(0, endsAt - workspace:GetServerTimeNow())
		or (Obby:GetAttribute("RunSeconds") or 0)
	local secs = math.ceil(left)
	clockValue.Text = string.format("%d:%02d", secs // 60, secs % 60)
	local hot = state == "Lost" or left < 30
	clockValue.TextColor3 = hot and Ui.C.danger or Ui.C.parchment
	clockEdge.Color = hot and Ui.C.danger or Ui.C.brass
end

local sinceClock = 0
table.insert(connections, RunService.Heartbeat:Connect(function(dt)
	sinceClock += dt
	if sinceClock >= 0.2 then
		sinceClock = 0
		refreshClock()
	end
end))
table.insert(connections, Obby:GetAttributeChangedSignal("RunState"):Connect(refreshClock))
refreshClock()

-- Views.PlayerView sets Exiting on this copy before destroying it.
script:GetAttributeChangedSignal("Exiting"):Connect(function()
	alive = false
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	if diedConn then
		diedConn:Disconnect()
		diedConn = nil
	end
	stampToken += 1 -- any pending stamp fade-out is now stale
	table.clear(toasts)
	gui:Destroy()
end)

-- Ask for the status now (arcade): a HUD cloned in mid-run gets its solved baseline straight away, so the
-- first BAY CLEARED stamp is not missed waiting for the next push.
if not script:GetAttribute("ReadOnly") then
	Status:FireServer()
end

print("[ObjectiveHud] steampunk HUD online")
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Player.CellEditor", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Player.CellEditor (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner while ReplicatedStorage.Obby FeedMode == "solo"). Arcade copy of
-- lebot_obby/StarterPlayerScripts/DebugCellEditor.client.lua. In the arcade this grid is SOLO GAMEPLAY,
-- not a debug tool: with no robot connected the runner places the blocks here and the Sky Arm carries
-- them in. Clicking a cell (cycle colour, shift = level) is the game and is always on. The hotkeys are
-- not -- none of them places a block (1-9 teleport, N next bay, R clears the bay's cells and HazardManager
-- rebuilds every bay, T K H M are print stubs; see Server.DebugMode) -- so they only work while
-- ReplicatedStorage.Obby ArcadeDebug == true. Its ScreenGui carries ObbyView = true and goes when the
-- copy's Exiting attribute is set.
--
-- DebugCellEditor (Section 10.1) -- on-screen 4x3 grid: click cycles color, shift-click toggles level.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")

local Obby = ReplicatedStorage:WaitForChild("Obby")
local Config = require(Obby:WaitForChild("Config"))

local Remotes = Obby:WaitForChild("Remotes")
local CellEdit = Remotes:WaitForChild("CellEdit")
local CellsUpdated = Remotes:WaitForChild("CellsUpdated")
local DebugHotkey = Remotes:WaitForChild("DebugHotkey")

local connections = {}

local COLOR_SWATCH = {
	red = Color3.fromRGB(220, 60, 60),
	blue = Color3.fromRGB(70, 160, 230),
	yellow = Color3.fromRGB(230, 210, 60),
	green = Color3.fromRGB(80, 200, 100),
	orange = Color3.fromRGB(235, 140, 40),
	purple = Color3.fromRGB(160, 90, 210),
	teal = Color3.fromRGB(60, 200, 190),
}

local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local screenGui = Instance.new("ScreenGui")
screenGui.Name = "CellEditor"
screenGui.ResetOnSpawn = false
screenGui:SetAttribute("ObbyView", true)
screenGui.Parent = playerGui

-- This grid IS the operator in solo mode, so it is only on screen when it is actually the
-- crate source. In live the real arm owns the cells, and a clickable grid that silently does
-- nothing is worse than no grid at all. (PlayerView already clones this only in solo; the status
-- check still covers a debug-menu feed switch mid-round.)
local Status = Remotes:WaitForChild("Status")
screenGui.Enabled = Obby:GetAttribute("FeedMode") == "solo"
table.insert(connections, Status.OnClientEvent:Connect(function(status)
	if type(status) == "table" then
		screenGui.Enabled = (status.feedMode == "solo")
	end
end))

local title = Instance.new("TextLabel")
title.Size = UDim2.new(0, 280, 0, 24)
title.Position = UDim2.new(0, 16, 0, 462)
title.BackgroundTransparency = 0.3
title.BackgroundColor3 = Color3.fromRGB(20, 20, 25)
title.TextColor3 = Color3.fromRGB(255, 255, 255)
title.Font = Enum.Font.SourceSansBold
title.TextSize = 14
title.Text = "PLACE BLOCKS -- click=cycle color, shift+click=level"
title.Parent = screenGui

-- the grid reads as a map of the bay ahead of you, so say which end is which
local farLabel = Instance.new("TextLabel")
farLabel.Size = UDim2.new(0, 260, 0, 16)
farLabel.Position = UDim2.new(0, 16, 0, 488)
farLabel.BackgroundTransparency = 1
farLabel.TextColor3 = Color3.fromRGB(150, 150, 165)
farLabel.Font = Enum.Font.SourceSansBold
farLabel.TextSize = 12
farLabel.Text = "^ FAR END OF BAY"
farLabel.Parent = screenGui

local frame = Instance.new("Frame")
frame.Size = UDim2.new(0, 260, 0, 200)
frame.Position = UDim2.new(0, 16, 0, 506)
frame.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
frame.BackgroundTransparency = 0.2
frame.Parent = screenGui

local nearLabel = farLabel:Clone()
nearLabel.Position = UDim2.new(0, 16, 0, 708)
nearLabel.Text = "v ENTRANCE (where you came in)"
nearLabel.Parent = screenGui

local layout = Instance.new("UIGridLayout")
layout.CellSize = UDim2.new(0, 56, 0, 56)
layout.CellPadding = UDim2.new(0, 6, 0, 6)
layout.SortOrder = Enum.SortOrder.LayoutOrder
layout.Parent = frame

local padding = Instance.new("UIPadding")
padding.PaddingTop = UDim.new(0, 10)
padding.PaddingLeft = UDim.new(0, 10)
padding.Parent = frame

local buttons = {}
for row = 0, Config.BayRows - 1 do
	for col = 0, Config.BayCols - 1 do
		local btn = Instance.new("TextButton")
		btn.Name = string.format("Cell_%d_%d", col, row)
		-- Lay the grid out as a MAP OF WHAT THE PLAYER SEES, not in raw index order.
		-- Walking into a bay you face +Z, and a Roblox character facing +Z has its
		-- RightVector pointing at -X -- so low columns are on your right, not your left, and
		-- row 0 (the entrance) is behind you rather than ahead. Both axes therefore flip:
		-- far row on top, high column on the left. Printed index order put the grid in a
		-- mirror image of the bay.
		btn.LayoutOrder = (Config.BayRows - 1 - row) * Config.BayCols
			+ (Config.BayCols - 1 - col)
		btn.BackgroundColor3 = Color3.fromRGB(45, 45, 55)
		btn.Text = string.format("%d,%d", col, row)
		btn.TextColor3 = Color3.fromRGB(255, 255, 255)
		btn.Font = Enum.Font.SourceSansBold
		btn.TextSize = 14
		btn.Parent = frame

		table.insert(connections, btn.MouseButton1Click:Connect(function()
			local shiftHeld = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
			CellEdit:FireServer(col, row, shiftHeld and "toggleLevel" or "cycle")
		end))

		buttons[col .. "," .. row] = btn
	end
end

table.insert(connections, CellsUpdated.OnClientEvent:Connect(function(cellsList)
	for key, btn in pairs(buttons) do
		btn.BackgroundColor3 = Color3.fromRGB(45, 45, 55)
		btn.Text = key
	end
	for _, cell in ipairs(cellsList) do
		local btn = buttons[cell.col .. "," .. cell.row]
		if btn then
			btn.BackgroundColor3 = COLOR_SWATCH[cell.color] or Color3.fromRGB(80, 80, 80)
			btn.Text = string.format("%d,%d L%d", cell.col, cell.row, cell.level)
		end
	end
end))

-- Debug only (ReplicatedStorage.Obby ArcadeDebug): none of these places a block.
