table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Player.BackdropFx", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Player.BackdropFx (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner and for spectators). Arcade copy of
-- lebot_obby/StarterPlayerScripts/BackdropFx.client.lua. Only tagged parts inside workspace.ObbyMap are
-- animated: the tags are generic words and the arcade's other maps may use them too. It makes no GUI. On
-- the copy's Exiting attribute it disconnects, puts every spun part and flickered lamp back to its rest
-- state and destroys the emitters it grew.
--
-- BackdropFx (client) -- the hall moves: gears turn, lamps gutter, vents breathe steam.
--
-- ALL OF IT IS CLIENT-SIDE AND TAG-DRIVEN, which is the whole design. The backdrop is a few
-- hundred parts; animating them on the server would replicate a CFrame stream for scenery
-- nobody can touch, every frame, forever. Here it costs the server exactly nothing and the
-- generators in build/ stay pure geometry -- they tag parts, this decides what a tag means.
--
-- Tags (set by build/backdrop_props.lua and build/backdrop_hall.lua):
--   BackdropSpin    -- gears, flywheels, turbines, valve wheels. Attribute "SpinSpeed"
--                      (rad/s, default 0.6) sets rate and direction.
--   BackdropFlicker -- gas lamps, firebox glow, tesla orbs. Attribute "FlickerFast" gives
--                      the jittery electric variety instead of a slow gas gutter.
--   BackdropSteam   -- an invisible anchor that grows a steam ParticleEmitter.
--   BackdropEmber   -- an invisible anchor that grows a rising-ember emitter.
--
-- CollectionService signals mean a re-run of a generator is picked up live: parts added
-- while you are standing there start moving, and destroyed ones drop out of the loop.
--
-- WHY THE SPIN IS CFrame AND NOT A TWEEN OR A HINGE. These are anchored decorative parts
-- with no physics; a constraint would need them unanchored, and a tween per part would be
-- hundreds of TweenBase instances. One RenderStepped pass over a flat array is cheaper than
-- any of it, and it is trivially throttled by distance (below).
--
-- DISTANCE THROTTLING. Everything here is backdrop: if it is far away you cannot see a gear
-- tooth move. Parts beyond FAR_DISTANCE are skipped entirely each frame, which keeps the
-- per-frame cost proportional to what is actually on screen rather than to how much scenery
-- exists in total.

local CollectionService = game:GetService("CollectionService")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local player = Players.LocalPlayer

local MAP_NAME = "ObbyMap"
local connections = {}
local cleanups = {}  -- one per tag: puts that tag's parts back and drops its entries

-- The obby's own parts only. Checked as each part arrives, so a map cloned in after this script
-- started is picked up as it streams in.
local function inMap(inst)
	local map = Workspace:FindFirstChild(MAP_NAME)
	return map ~= nil and inst:IsDescendantOf(map)
end

local FAR_DISTANCE = 190        -- past this, nothing animates
local FAR_SQ = FAR_DISTANCE * FAR_DISTANCE

----------------------------------------------------------------
-- Tag bookkeeping: one array per tag, kept in step with the world.
----------------------------------------------------------------
local function track(tagName, onAdd, onRemove)
	local list = {}
	local index = {}

	local function add(inst)
		if not inst:IsA("BasePart") or index[inst] or not inMap(inst) then
			return
		end
		local entry = onAdd and onAdd(inst) or {part = inst}
		entry.part = inst
		list[#list + 1] = entry
		index[inst] = entry
	end

	local function remove(inst)
		local entry = index[inst]
		if not entry then
			return
		end
		index[inst] = nil
		for i, e in ipairs(list) do
			if e == entry then
				table.remove(list, i)
				break
			end
		end
		if onRemove then
			onRemove(entry)
		end
	end

	for _, inst in ipairs(CollectionService:GetTagged(tagName)) do
		add(inst)
	end
	table.insert(connections, CollectionService:GetInstanceAddedSignal(tagName):Connect(add))
	table.insert(connections, CollectionService:GetInstanceRemovedSignal(tagName):Connect(remove))
	table.insert(cleanups, function()
		for _, entry in ipairs(list) do
			if onRemove then
				onRemove(entry)
			end
		end
		table.clear(list)
		table.clear(index)
	end)
	return list
end

----------------------------------------------------------------
-- Spin
----------------------------------------------------------------
local spinners = track("BackdropSpin", function(p)
	-- The rest CFrame is captured once. Accumulating a rotation onto the live CFrame drifts
	-- and skews the part over a few minutes of floating-point error; rebuilding from a fixed
	-- base every frame cannot.
	return {base = p.CFrame, speed = p:GetAttribute("SpinSpeed") or 0.6}
end, function(entry)
	-- back to rest (the arcade: the view can exit while the map is still standing)
	if entry.part.Parent then
		entry.part.CFrame = entry.base
	end
end)

----------------------------------------------------------------
-- Flicker
----------------------------------------------------------------
local flickers = track("BackdropFlicker", function(p)
	return {
		baseT = p.Transparency,
		fast = p:GetAttribute("FlickerFast") == true,
		seed = math.random() * 100,          -- so they do not pulse in unison
		light = p:FindFirstChildOfClass("PointLight"),
		baseB = (p:FindFirstChildOfClass("PointLight") or {}).Brightness,
	}
end, function(entry)
	if entry.part.Parent then
		entry.part.Transparency = entry.baseT
	end
	if entry.light and entry.baseB and entry.light.Parent then
		entry.light.Brightness = entry.baseB
	end
end)

----------------------------------------------------------------
-- Particles. Built on the CLIENT, so the server never replicates them.
----------------------------------------------------------------
local function steamEmitter(parent)
	local e = Instance.new("ParticleEmitter")
	e.Name = "BackdropSteamFx"
	e.Texture = "rbxasset://textures/particles/smoke_main.dds"
	e.Color = ColorSequence.new(Color3.fromRGB(196, 186, 172), Color3.fromRGB(120, 112, 104))
	e.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.18, 0.62),
		NumberSequenceKeypoint.new(1, 1),
	})
	e.Size = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 2),
		NumberSequenceKeypoint.new(1, 11),
	})
	e.Lifetime = NumberRange.new(2.6, 4.2)
	e.Rate = 2.5                      -- deliberately low: haze, not a smoke screen
	e.Speed = NumberRange.new(3, 6)
	e.SpreadAngle = Vector2.new(14, 14)
	e.Rotation = NumberRange.new(0, 360)
	e.RotSpeed = NumberRange.new(-22, 22)
	e.LightEmission = 0.12
	e.Acceleration = Vector3.new(0.6, 2.2, 0)
	e.Parent = parent
	return e
end

local function emberEmitter(parent)
	local e = Instance.new("ParticleEmitter")
	e.Name = "BackdropEmberFx"
	e.Color = ColorSequence.new(Color3.fromRGB(255, 170, 70), Color3.fromRGB(190, 48, 20))
	e.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0.1),
		NumberSequenceKeypoint.new(1, 1),
	})
	e.Size = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0.5),
		NumberSequenceKeypoint.new(1, 0),
	})
	e.Lifetime = NumberRange.new(2.2, 4.0)
	e.Rate = 7
	e.Speed = NumberRange.new(9, 15)
	e.SpreadAngle = Vector2.new(26, 26)
	e.LightEmission = 1
	e.Acceleration = Vector3.new(0, 3, 0)
	e.Parent = parent
	return e
end

track("BackdropSteam", function(p)
	return {emitter = steamEmitter(p)}
end, function(entry)
	if entry.emitter then
		entry.emitter:Destroy()
	end
end)

track("BackdropEmber", function(p)
	return {emitter = emberEmitter(p)}
end, function(entry)
	if entry.emitter then
		entry.emitter:Destroy()
	end
end)

----------------------------------------------------------------
-- The one loop
----------------------------------------------------------------
local function viewerPosition()
	local cam = Workspace.CurrentCamera
	if cam then
		return cam.CFrame.Position
	end
	local ch = player.Character
	local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
	return hrp and hrp.Position or Vector3.zero
end

local t = 0
table.insert(connections, RunService.RenderStepped:Connect(function(dt)
	t += dt
	local eye = viewerPosition()

	for _, s in ipairs(spinners) do
		local p = s.part
		if p.Parent then
			if (p.Position - eye).Magnitude <= FAR_DISTANCE then
				-- A Cylinder's face is its X, so these wheels read as turning only when the
				-- rotation is about X. Rebuilt from the captured base, never accumulated.
				p.CFrame = s.base * CFrame.Angles(t * s.speed, 0, 0)
			end
		end
	end

	for _, f in ipairs(flickers) do
		local p = f.part
		if p.Parent and (p.Position - eye).Magnitude <= FAR_DISTANCE then
			local n
			if f.fast then
				-- electric: fast, jumpy, occasionally almost out
				n = math.noise(t * 7 + f.seed, f.seed) * 0.5 + math.noise(t * 23 + f.seed, 0) * 0.5
			else
				-- gas: a slow, shallow gutter
				n = math.noise(t * 1.6 + f.seed, f.seed)
			end
			-- BIASED UPWARD, NOT CENTRED. Every emissive part here sits at Transparency 0,
			-- so a symmetric wobble spends half its time clamped at 0 and the lamp reads as
			-- dead steady. Shifting the noise into 0..1 makes the flicker a dimming from
			-- full brightness, which is also what a real gas flame does.
			local amp = f.fast and 0.34 or 0.14
			p.Transparency = math.clamp(f.baseT + (n + 0.5) * amp, 0, 1)
			if f.light and f.baseB then
				f.light.Brightness = math.max(0, f.baseB * (1 + n * (f.fast and 0.5 or 0.22)))
			end
		end
	end
end))

-- Reported LATE on purpose. This script starts before the backdrop has finished replicating,
-- so counting at load prints "0 spinning, 0 flickering" every time and reads like the tags
-- are broken when they are simply not here yet -- GetInstanceAddedSignal picks them up as
-- they stream in. Two seconds in, the number means something.
task.delay(2, function()
	if #connections == 0 then
		return -- exited already
	end
	print(("[BackdropFx] %d spinning, %d flickering, %d steam, %d ember")
		:format(#spinners, #flickers,
			#CollectionService:GetTagged("BackdropSteam"),
			#CollectionService:GetTagged("BackdropEmber")))
end)

-- Views.PlayerView sets Exiting on this copy before destroying it.
script:GetAttributeChangedSignal("Exiting"):Connect(function()
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	for _, cleanup in ipairs(cleanups) do
		cleanup()
	end
	table.clear(cleanups)
end)
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Player.CameraPolish", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Player.CameraPolish (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner only). Arcade copy of lebot_obby/StarterPlayerScripts/CameraPolish.client.lua.
-- It makes no GUI. On the copy's Exiting attribute it stops its loops and connections and puts
-- player.CameraMaxZoomDistance back to what it found (the low-ceiling cap below lowers it). The camera
-- itself needs nothing: every aim hands it straight back to Custom in the same frame.
--
-- CameraPolish (client) -- the camera faces where you were just put, and the join shot is
-- not the inside of a wall.
--
-- Three problems, one script:
--
-- 1. A SERVER TELEPORT DOES NOT TURN THE CAMERA. Writing HumanoidRootPart.CFrame turns the
--    body; the default camera keeps whatever yaw the player left it at, because that yaw
--    lives in the client's camera module and nothing on the server can reach it. So jumping
--    to a bay spun the character to face the obstacle and left the player looking back down
--    the course at the bay they had just finished. DebugMenu fires `CameraFace` with the
--    direction it pointed the body, and this turns the view to match.
--
-- 2. THE JOIN SHOT. The course entrance sits three studs from the shell's end cap, so a
--    camera that starts pointing the wrong way starts inside a wall. Facing it down the
--    course makes the first frame of the game the view down the hall.
--
-- 3. RESPAWN TAKES THE CAMERA BACK. This is the one that is easy to get wrong: aiming once
--    on CharacterAdded LOOKS right and then silently loses. The engine runs its own
--    "put the camera behind the new character" a few frames later and overwrites us, so the
--    camera ends up facing back up the course again -- measured at lookZ -0.75 after an
--    ordinary death. The aim therefore HOLDS for a short window instead of firing once.
--
-- HOW YOU TURN THE DEFAULT CAMERA. You cannot just assign Camera.CFrame -- the camera module
-- overwrites it on the next RenderStep. The supported move is to take the camera, point it,
-- and hand it back: on the Scriptable -> Custom transition the module re-derives its yaw and
-- pitch from wherever the camera is actually looking, so the new facing sticks.
--
-- IT NEVER FIGHTS THE PLAYER. The hold stops the instant the player moves the mouse (or a
-- gamepad's right stick). Holding a camera against someone who is trying to look around is
-- worse than the bug it fixes.
--
-- IT YIELDS TO THE OVERSEER. OverseerCam holds CameraType = Scriptable for as long as its
-- view is up. If we are not in Custom, someone else is driving and this does nothing --
-- which is what stops a bay change from yanking player 2's top-down shot back to the runner.
-- (In the arcade the overseer is the robot role's own client, Views.RobotView, and this script
-- never runs there; the yield still keeps it off any other scripted camera.)

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")

local player = Players.LocalPlayer
local Remotes = ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Remotes")
local CameraFace = Remotes:WaitForChild("CameraFace")

local alive = true -- false once Views.PlayerView sets Exiting: every loop below stops on it
local connections = {}

-- How far back the shot sits while we are placing it. The camera module recomputes its own
-- distance from the player's zoom the moment we hand control back, so this only has to be
-- far enough to read as third person for the one frame it exists.
local PLACE_DISTANCE = 14
local PLACE_HEIGHT = 2.5

-- How long the aim is defended after a teleport or a spawn, and how far off it has to drift
-- before we correct it again. The tolerance is what keeps this from thrashing: once the
-- camera is pointing the right way we stop touching it entirely.
local HOLD_AFTER_SPAWN = 1.5
local HOLD_AFTER_TELEPORT = 1.0
local TOLERANCE_DOT = 0.985        -- about 10 degrees

local takenOver = false

-- Any real look input hands the camera back for good.
--
-- "Moved the mouse" is NOT the test. MouseMovement fires for every pixel of ordinary cursor
-- travel, so treating that as intent would hand the camera back before the hold had done
-- anything. The default camera only rotates while the right button is down, or while the
-- mouse is locked to the centre (first person and shift-lock) -- so that is the condition.
local function noteTakeover(input)
	local t = input.UserInputType
	if t == Enum.UserInputType.MouseMovement then
		local rotating = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
			or UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter
		if rotating and input.Delta.Magnitude > 0.5 then
			takenOver = true
		end
	elseif t == Enum.UserInputType.Touch then
		takenOver = true
	elseif input.KeyCode == Enum.KeyCode.Thumbstick2 then
		-- a gamepad's look stick reports through Position, not Delta
		if input.Position.Magnitude > 0.2 then
			takenOver = true
		end
	end
end
table.insert(connections, UserInputService.InputChanged:Connect(noteTakeover))

local function flatten(dir)
	local flat = Vector3.new(dir.X, 0, dir.Z)
	return (flat.Magnitude > 1e-3) and flat.Unit or nil
end

-- Returns: aimed (did we touch it), settled (is it already pointing the right way)
local function aimOnce(flat)
	local cam = Workspace.CurrentCamera
	local ch = player.Character
	local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
	if not cam or not hrp then
		return false, false
	end
	-- Someone else owns the camera (the overseer view). Leave it alone.
	if cam.CameraType ~= Enum.CameraType.Custom then
		return false, false
	end

	local look = flatten(cam.CFrame.LookVector)
	if look and look:Dot(flat) >= TOLERANCE_DOT then
		return false, true          -- already facing the right way; do not touch it
	end

	local focus = hrp.Position + Vector3.new(0, PLACE_HEIGHT, 0)
	cam.CameraType = Enum.CameraType.Scriptable
	cam.CFrame = CFrame.lookAt(focus - flat * PLACE_DISTANCE, focus)
	cam.Focus = CFrame.new(focus)
	cam.CameraType = Enum.CameraType.Custom

	local hum = ch:FindFirstChildOfClass("Humanoid")
	if hum then
		cam.CameraSubject = hum
	end
	return true, true
end

-- Hold the aim for `seconds`, correcting whenever something knocks it off, and giving up
-- immediately if the player starts looking around themselves.
local function holdAim(dir, seconds)
	local flat = flatten(dir)
	if not flat then
		return
	end
	takenOver = false
	task.spawn(function()
		local deadline = os.clock() + seconds
		while alive and os.clock() < deadline and not takenOver do
			aimOnce(flat)
			RunService.RenderStepped:Wait()
		end
	end)
end

table.insert(connections, CameraFace.OnClientEvent:Connect(function(dir)
	if typeof(dir) ~= "Vector3" then
		return
	end
	-- One frame of grace: the teleport and this event land together, and aiming at the
	-- character's OLD position leaves the camera facing the right way from the wrong place.
	task.defer(function()
		RunService.RenderStepped:Wait()
		holdAim(dir, HOLD_AFTER_TELEPORT)
	end)
end))

-- The join / respawn shot, pointed down the course (+Z). Held, because the engine's own
-- respawn camera reset lands a few frames after CharacterAdded and would otherwise win.
table.insert(connections, player.CharacterAdded:Connect(function()
	holdAim(Vector3.new(0, 0, 1), HOLD_AFTER_SPAWN)
end))
if player.Character then
	holdAim(Vector3.new(0, 0, 1), HOLD_AFTER_SPAWN)
end

----------------------------------------------------------------
-- Low ceilings: pull the camera in before it clips through one.
----------------------------------------------------------------
-- In the dark room the camera was ending up at y = 13.57 with the ceiling slab's underside
-- at 13.5 -- a tenth of a stud INSIDE it. Roblox's Popper pulls the camera closer to avoid
-- an occluder, but in a 14-stud-tall sealed box there is nowhere left to go, so it settles
-- flush against the roof and the near plane pokes out the far side. You then see straight
-- through the ceiling at whatever is above, which since the hall went in is a lit window.
-- In the one bay whose entire premise is that you cannot see, that is fatal.
--
-- Rather than special-case bay 4, measure: look up, and if there is a roof overhead, cap the
-- zoom at a fraction of the clearance so the camera physically cannot reach it. Open bays
-- find nothing above and keep the full range.
local DEFAULT_ZOOM = player.CameraMaxZoomDistance
local CEILING_SEARCH = 26          -- how far up we bother looking
local CLEARANCE_FRACTION = 0.7     -- measured: 0.7 * clearance sits the camera well clear
local MIN_ZOOM = 5

-- A ceiling is something broad enough to actually be over you. Without this the crane's
-- rail beams (1 x 1 x 134, at y = 18) and the roof trusses read as ceilings and squash the
-- camera in the middle of a perfectly open bay.
local function isCeiling(part)
	return part.Size.X > 8 and part.Size.Z > 8
end

local zoomParams = RaycastParams.new()
zoomParams.FilterType = Enum.RaycastFilterType.Exclude

task.spawn(function()
	while alive do
		task.wait(0.2)
		local ch = alive and player.Character
		local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
		if hrp then
			zoomParams.FilterDescendantsInstances = {ch}
			local hit = workspace:Raycast(hrp.Position, Vector3.new(0, CEILING_SEARCH, 0), zoomParams)
			local want = DEFAULT_ZOOM
			if hit and isCeiling(hit.Instance) then
				local clearance = hit.Position.Y - hrp.Position.Y
				want = math.clamp(clearance * CLEARANCE_FRACTION, MIN_ZOOM, DEFAULT_ZOOM)
			end
			if math.abs(player.CameraMaxZoomDistance - want) > 0.25 then
				player.CameraMaxZoomDistance = want
			end
		end
	end
end)

-- Views.PlayerView sets Exiting on this copy before destroying it.
script:GetAttributeChangedSignal("Exiting"):Connect(function()
	alive = false
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	player.CameraMaxZoomDistance = DEFAULT_ZOOM
end)

print("[CameraPolish] camera follows teleports and respawns; join shot faces down the course")
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Player.DarkRoom", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Player.DarkRoom (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner only). New in the arcade.
--
-- WHY THIS EXISTS. In the standalone obby the dark room (bay 4) dimmed the whole game through Lighting.
-- In the arcade Lighting belongs to the arcade: the Workshop, the other bays' games and the robot
-- operator's overseer view all share it, so dimming it would black out every one of them -- including
-- the operator, whose whole job in that bay is to see what the runner cannot. So the darkness moved to
-- the one screen it is for: HazardManager sets the attribute Dark = true on the bay model instead, and
-- this script puts a ColorCorrectionEffect named "ObbyDark" under this client's own camera while the
-- character stands inside that bay, and fades it out again when they leave. The sconces are PointLights,
-- so they still read; the screws stay hidden by the bay's own lighting logic regardless.
--
-- INSIDE means the bay's footprint: X 0..Config.BayWidth, Z from the bay's entrance edge
-- (RunControl.bayZStart: Config.OriginZ + (n - 1) * Config.BayPitch) to + Config.BayDepth, any Y. The
-- catwalks between bays are outside, so the dark starts at the door. Tunables: Config.DarkTint,
-- DarkBrightness, DarkContrast, DarkSaturation.
--
-- On the copy's Exiting attribute (Views.PlayerView) it disconnects and destroys the effect at once;
-- PlayerView also removes any "ObbyDark" left under the camera.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local Config = require(ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Config"))

local player = Players.LocalPlayer

local MAP_NAME = "ObbyMap"
local EFFECT_NAME = "ObbyDark"
local CHECK_EVERY = 0.1
local FADE = TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

local NEUTRAL = {
	TintColor = Color3.new(1, 1, 1),
	Brightness = 0,
	Contrast = 0,
	Saturation = 0,
}
local DARK = {
	TintColor = Config.DarkTint,
	Brightness = Config.DarkBrightness,
	Contrast = Config.DarkContrast,
	Saturation = Config.DarkSaturation,
}

local connections = {}
local effect = nil   -- the ColorCorrectionEffect while there is one
local tween = nil
local dark = false

-- The bay model the position stands in, if that bay is dark right now.
local function darkBayAt(pos)
	local map = workspace:FindFirstChild(MAP_NAME)
	local warehouse = map and map:FindFirstChild("Warehouse")
	if not warehouse or pos.X < 0 or pos.X > Config.BayWidth then
		return nil
	end
	local n = math.floor((pos.Z - Config.OriginZ) / Config.BayPitch) + 1
	if n < 1 or n > Config.NumBays then
		return nil
	end
	local zStart = Config.OriginZ + (n - 1) * Config.BayPitch
	if pos.Z < zStart or pos.Z > zStart + Config.BayDepth then
		return nil -- on the catwalk past this bay's far edge
	end
	local bay = warehouse:FindFirstChild(("Bay%02d"):format(n))
	if bay and bay:GetAttribute("Dark") == true then
		return bay
	end
	return nil
end

local function play(target, props, onDone)
	if tween then
		tween:Cancel()
	end
	tween = TweenService:Create(target, FADE, props)
	if onDone then
		local mine = tween
		mine.Completed:Connect(function(state)
			if state == Enum.PlaybackState.Completed and tween == mine then
				onDone()
			end
		end)
	end
	tween:Play()
end

local function setDark(on)
	local camera = workspace.CurrentCamera
	if on then
		-- (re)made whenever it is missing: a new CurrentCamera, or PlayerView's sweep
		if not (effect and effect.Parent == camera) then
			if effect then
				effect:Destroy()
			end
			effect = camera and camera:FindFirstChild(EFFECT_NAME)
			if not effect then
				effect = Instance.new("ColorCorrectionEffect")
				effect.Name = EFFECT_NAME
				for k, v in pairs(NEUTRAL) do
					effect[k] = v
				end
				effect.Parent = camera
			end
			dark = false
		end
		if not dark then
			dark = true
			play(effect, DARK)
		end
	elseif dark then -- (not dark: already neutral, or already fading out)
		dark = false
		local fading = effect
		if fading then
			play(fading, NEUTRAL, function()
				if not dark and effect == fading then
					fading:Destroy()
					effect = nil
				end
			end)
		end
	end
end

local since = 0
table.insert(connections, RunService.Heartbeat:Connect(function(dt)
	since += dt
	if since < CHECK_EVERY then
		return
	end
	since = 0
	local ch = player.Character
	local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
	setDark(hrp ~= nil and darkBayAt(hrp.Position) ~= nil)
end))

-- Views.PlayerView sets Exiting on this copy before destroying it.
script:GetAttributeChangedSignal("Exiting"):Connect(function()
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	if tween then
		tween:Cancel()
		tween = nil
	end
	if effect then
		effect:Destroy()
		effect = nil
	end
	dark = false
end)
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Debug.DebugMenu", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Debug.DebugMenu (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner only while ReplicatedStorage.Obby ArcadeDebug == true, so F1 / F2 and the panel
-- do not exist otherwise). Arcade copy of lebot_obby/StarterPlayerScripts/DebugMenu.client.lua: the panel
-- reads Remotes.Status (was DebugStatus) and asks for it with Status:FireServer(); the commands still go
-- through DebugCommand. Its ScreenGui carries ObbyView = true and goes when the copy's Exiting attribute
-- is set.
--
-- DebugMenu (client) -- the scenario picker: jump to any bay, start a clean run on it, and
-- choose whether a second player exists at all.
--
-- Everything shown here is pushed from the server (Status) rather than tracked locally,
-- so the panel cannot drift from what the game actually thinks. F1 hides it for screenshots.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")

local Obby = ReplicatedStorage:WaitForChild("Obby")
local Config = require(Obby:WaitForChild("Config"))
local Ui = require(Obby:WaitForChild("UiTheme"))

if Obby:GetAttribute("ArcadeDebug") ~= true then
	return
end

local Remotes = Obby:WaitForChild("Remotes")
local DebugCommand = Remotes:WaitForChild("DebugCommand")
local Status = Remotes:WaitForChild("Status")

local connections = {}

local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local INK = Ui.C.parchment
local PANEL = Ui.C.iron
local EDGE = Ui.C.brass
local LIVE = Ui.C.ok
local WARM = Ui.C.amber
local COLD = Ui.C.info
local DONE = Ui.C.ok

local FEED_LABEL = {
	live = "MODE: LIVE ARM",
	solo = "MODE: SOLO",
}
local FEED_HINT = {
	live = "connected to the real SO-101 -- only your hands place a block",
	solo = "you are the operator too: place on the grid below, the arm carries it",
}
local FEED_TINT = {live = LIVE, solo = WARM}

local gui = Instance.new("ScreenGui")
gui.Name = "DebugMenu"
gui.ResetOnSpawn = false
gui.IgnoreGuiInset = true
gui:SetAttribute("ObbyView", true)
gui.Parent = playerGui

local root = Instance.new("Frame")
root.Size = UDim2.new(0, 300, 0, 400)
root.Position = UDim2.new(0, 16, 0, 16)
root.BackgroundColor3 = PANEL
root.BackgroundTransparency = 0.08
root.BorderSizePixel = 0
root.Parent = gui
Instance.new("UICorner", root).CornerRadius = UDim.new(0, 5)
Ui.stroke(root, Ui.C.brass, 2)
Ui.sheen(root, 0.3)
-- NO rivetRow here. This panel lays its children out with a UIListLayout, so decorative
-- frames parented to it become LIST ITEMS: the rivets marched down the left edge as rows and
-- shoved every control out of place. Rivets belong on panels that position their own
-- children, which is what UiTheme.panel builds.
local stroke = Instance.new("UIStroke", root)
stroke.Color = EDGE
stroke.Thickness = 1

local pad = Instance.new("UIPadding", root)
pad.PaddingTop = UDim.new(0, 10)
pad.PaddingBottom = UDim.new(0, 10)
pad.PaddingLeft = UDim.new(0, 10)
pad.PaddingRight = UDim.new(0, 10)

local layout = Instance.new("UIListLayout", root)
layout.SortOrder = Enum.SortOrder.LayoutOrder
layout.Padding = UDim.new(0, 8)

local order = 0
local function nextOrder()
	order += 1
	return order
end

local function label(text, size, colour, parent)
	local l = Instance.new("TextLabel")
	l.Size = UDim2.new(1, 0, 0, size + 6)
	l.BackgroundTransparency = 1
	l.Font = Ui.F.label
	l.TextSize = size
	l.TextColor3 = colour or INK
	l.TextXAlignment = Enum.TextXAlignment.Left
	l.Text = text
	l.LayoutOrder = nextOrder()
	l.Parent = parent or root
	return l
end

local function button(text, parent, tint)
	local b = Instance.new("TextButton")
	b.Size = UDim2.new(1, 0, 0, 30)
	b.BackgroundColor3 = tint or Ui.C.ironLight
	b.BorderSizePixel = 0
	b.AutoButtonColor = true
	b.Font = Ui.F.label
	b.TextSize = 13
	b.TextColor3 = INK
	b.Text = text
	b.LayoutOrder = nextOrder()
	b.Parent = parent or root
	Instance.new("UICorner", b).CornerRadius = UDim.new(0, 4)
	Ui.stroke(b, Ui.C.brassDim, 1.5)
	return b
end

label("DEBUG  -  SCENARIOS", 14)
local hint = label("F1 hides this panel", 11, Ui.C.faded)
hint.Size = UDim2.new(1, 0, 0, 14)

-- Bay grid -------------------------------------------------------------
local grid = Instance.new("Frame")
grid.Size = UDim2.new(1, 0, 0, 96)
grid.BackgroundTransparency = 1
grid.LayoutOrder = nextOrder()
grid.Parent = root

local gl = Instance.new("UIGridLayout", grid)
gl.CellSize = UDim2.new(0, 88, 0, 28)
gl.CellPadding = UDim2.new(0, 6, 0, 6)
gl.SortOrder = Enum.SortOrder.LayoutOrder

local bayButtons = {}
for i = 1, Config.NumBays do
	local b = Instance.new("TextButton")
	b.Size = UDim2.new(0, 88, 0, 28)
	b.BackgroundColor3 = Ui.C.ironLight
	b.BorderSizePixel = 0
	b.Font = Ui.F.label
	b.TextSize = 11
	b.TextColor3 = INK
	b.Text = ("%d"):format(i)
	b.LayoutOrder = i
	b.Parent = grid
	Instance.new("UICorner", b).CornerRadius = UDim.new(0, 4)
	Ui.stroke(b, Ui.C.brassDim, 1.5)
	local st = Instance.new("UIStroke", b)
	st.Color = EDGE
	st.Thickness = 1
	b.MouseButton1Click:Connect(function()
		DebugCommand:FireServer("teleport", i)
	end)
	bayButtons[i] = {button = b, stroke = st}
end

local current = label("Bay 01  -  Saw", 12, COLD)

local startBtn = button("START RUN HERE  (fresh state)", root, Color3.fromRGB(30, 62, 44))
local resetBtn = button("RESET THIS BAY", root)
local resetAllBtn = button("RESET ALL BAYS", root)
-- Distinct from RESET ALL BAYS, which rebuilds the course and leaves you standing wherever
-- you were -- usually mid-bay, mid-hazard, sometimes dead. This one also puts you back on the
-- spawn with a fresh body, which is the state a demo wants to start from.
local fullResetBtn = button("RESET EVERYTHING  (F2)", root, Color3.fromRGB(78, 32, 22))

-- Player 2 ------------------------------------------------------------
local sep = label("WHO PLACES BLOCKS  (switching resets everything)", 11,
	Ui.C.faded)
sep.Size = UDim2.new(1, 0, 0, 16)

local feedBtn = button("P2: ...", root)
local feedHint = label("", 10, Ui.C.faded)
feedHint.Size = UDim2.new(1, 0, 0, 26)
feedHint.TextWrapped = true
feedHint.Font = Ui.F.body

local state = {activeBay = 1, feedMode = "solo", bays = {}}

local MODE_CYCLE = {solo = "live", live = "solo"}

startBtn.MouseButton1Click:Connect(function()
	DebugCommand:FireServer("startRun", state.activeBay)
end)
resetBtn.MouseButton1Click:Connect(function()
	DebugCommand:FireServer("resetBay")
end)
resetAllBtn.MouseButton1Click:Connect(function()
	DebugCommand:FireServer("resetAll")
end)
fullResetBtn.MouseButton1Click:Connect(function()
	DebugCommand:FireServer("fullReset")
end)
-- Switching is a hard reset of the whole course, so say so rather than surprising anyone.
feedBtn.MouseButton1Click:Connect(function()
	DebugCommand:FireServer("feedMode", MODE_CYCLE[state.feedMode] or "solo")
end)

local function render()
	for i, entry in ipairs(bayButtons) do
		local info = state.bays[i]
		local isActive = (i == state.activeBay)
		local solved = info and info.solved
		entry.button.Text = info and ("%d  %s"):format(i, info.obstacle) or tostring(i)
		entry.button.BackgroundColor3 = isActive and Color3.fromRGB(58, 42, 18)
			or Ui.C.ironLight
		entry.stroke.Color = isActive and COLD or (solved and DONE or EDGE)
		entry.stroke.Thickness = isActive and 2 or 1
		entry.button.TextColor3 = solved and DONE or INK
	end
	local info = state.bays[state.activeBay]
	if info then
		current.Text = ("Bay %02d  -  %s%s"):format(state.activeBay, info.obstacle,
			info.solved and "   [CLEARED]" or "")
		current.TextColor3 = info.solved and DONE or COLD
	end
	feedBtn.Text = FEED_LABEL[state.feedMode] or "P2: ?"
	feedBtn.BackgroundColor3 = Ui.C.ironLight
	local tint = FEED_TINT[state.feedMode]
	feedBtn.TextColor3 = tint or INK
	feedHint.Text = FEED_HINT[state.feedMode] or ""
end

table.insert(connections, Status.OnClientEvent:Connect(function(s)
	if type(s) ~= "table" then
		return
	end
	state = s
	render()
end))

table.insert(connections, UserInputService.InputBegan:Connect(function(input, processed)
	if processed then
		return
	end
	if input.KeyCode == Enum.KeyCode.F1 then
		root.Visible = not root.Visible
	elseif input.KeyCode == Enum.KeyCode.F2 then
		-- Reachable with the panel hidden, which is how you would actually be playing.
		DebugCommand:FireServer("fullReset")
	end
end))

-- Views.PlayerView sets Exiting on this copy before destroying it. (The buttons' connections go
-- with the GUI.)
script:GetAttributeChangedSignal("Exiting"):Connect(function()
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	gui:Destroy()
end)

render()
Status:FireServer()
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Obby.Views.Debug.GhostControl", class = "LocalScript", source = [=[
-- ReplicatedStorage.Obby.Views.Debug.GhostControl (LocalScript template; Views.PlayerView clones it into
-- PlayerGui for the runner only while ReplicatedStorage.Obby ArcadeDebug == true, so Q does not exist
-- otherwise). Arcade copy of lebot_obby/StarterPlayerScripts/GhostControl.client.lua. Its ScreenGui
-- carries ObbyView = true; on the copy's Exiting attribute it disconnects, drops the fly and destroys the
-- badge.
--
-- GhostControl -- Q toggles debug ghost mode: fly through the whole course, nothing can kill
-- you. WASD moves relative to the camera, Space rises, Shift drops, hold E for a speed boost.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local GhostToggle = ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Remotes"):WaitForChild("GhostToggle")
local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

local connections = {}

local BASE_SPEED = 55
local BOOST_SPEED = 130

local ghost = false

-- on-screen state readout
local gui = Instance.new("ScreenGui")
gui.Name = "GhostHud"
gui.ResetOnSpawn = false
gui:SetAttribute("ObbyView", true)
gui.Parent = playerGui

local badge = Instance.new("TextLabel")
badge.Size = UDim2.new(0, 330, 0, 26)
-- Below the debug scenario panel, which occupies the top-left corner.
badge.Position = UDim2.new(0, 16, 0, 428)
badge.BackgroundTransparency = 0.25
badge.BackgroundColor3 = Color3.fromRGB(20, 20, 26)
badge.Font = Enum.Font.SourceSansBold
badge.TextSize = 15
badge.TextColor3 = Color3.fromRGB(190, 190, 200)
badge.Text = "Q = GHOST MODE (fly + invincible)  -  OFF"
badge.Parent = gui

local function setBadge()
	if ghost then
		badge.Text = "GHOST ON  -  WASD fly, Space up, Shift down, E boost, Q off"
		badge.TextColor3 = Color3.fromRGB(120, 240, 150)
	else
		badge.Text = "Q = GHOST MODE (fly + invincible)  -  OFF"
		badge.TextColor3 = Color3.fromRGB(190, 190, 200)
	end
end

table.insert(connections, UserInputService.InputBegan:Connect(function(input, processed)
	if processed then
		return
	end
	if input.KeyCode == Enum.KeyCode.Q then
		GhostToggle:FireServer()
	end
end))

-- server confirms the authoritative state
table.insert(connections, GhostToggle.OnClientEvent:Connect(function(on)
	ghost = on
	setBadge()

	local char = player.Character
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if hum then
		-- PlatformStand stops the walk/fall state machine fighting the fly movement
		hum.PlatformStand = on
	end
end))

table.insert(connections, RunService.RenderStepped:Connect(function(dt)
	if not ghost then
		return
	end

	local char = player.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	local cam = workspace.CurrentCamera
	if not cam then
		return
	end

	local dir = Vector3.zero
	if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir += cam.CFrame.LookVector end
	if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir -= cam.CFrame.LookVector end
	if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir += cam.CFrame.RightVector end
	if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir -= cam.CFrame.RightVector end
	if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir += Vector3.new(0, 1, 0) end
	if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then dir -= Vector3.new(0, 1, 0) end

	-- hold still in the air rather than falling when no key is held
	hrp.AssemblyLinearVelocity = Vector3.zero
	if dir.Magnitude > 0 then
		local speed = UserInputService:IsKeyDown(Enum.KeyCode.E) and BOOST_SPEED or BASE_SPEED
		hrp.CFrame = hrp.CFrame + dir.Unit * speed * dt
	end
end))

-- Views.PlayerView sets Exiting on this copy before destroying it. The fly is dropped locally
-- only: the server's ghost state belongs to the round (Server.GhostMode) and ends with it, and a
-- toggle fired now could land in the next round instead.
script:GetAttributeChangedSignal("Exiting"):Connect(function()
	for _, c in ipairs(connections) do
		c:Disconnect()
	end
	table.clear(connections)
	if ghost then
		ghost = false
		local char = player.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.PlatformStand = false
		end
	end
	gui:Destroy()
end)

setBadge()
]=] })
table.insert(SOURCES, { path = "ReplicatedStorage.Core.Games.Obby", class = "ModuleScript", source = [=[
-- ReplicatedStorage.Core.Games.Obby
-- Robo Obby's GameRegistry entry. It is an arcade mode (ServerStorage.Modes.Obby) that knows nothing about
-- the registry: ServerScriptService.ArcadeActiveGame makes it the active game while its bay runs (the
-- bay's Mode attribute is "Obby"). The player's screen is Obby.Views.PlayerView (the objective HUD, the
-- solo cell grid, the dark room's camera tint); the robot gets Obby.Views.RobotView, the overseer camera
-- over the active bay with the objective and run status.

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local views = ReplicatedStorage:WaitForChild("Obby"):WaitForChild("Views")

return {
	id = "Obby",
	name = "Robo Obby",
	lobby = false,
	playerView = views:WaitForChild("PlayerView"),
	robotView = views:WaitForChild("RobotView"),
}
]=] })

local REMOTES = { "Objective", "CellEdit", "CellsUpdated", "DebugHotkey", "GhostToggle", "DebugCommand", "Status", "BayCells", "CameraFace", "Toast" }

for _, entry in ipairs(SOURCES) do
	put(entry.path, entry.class, entry.source)
end

-- The remotes Module would make when it first loads, made now so the tree is complete in Edit mode.
local remotes = folderAt("ReplicatedStorage.Obby.Remotes")
for _, name in ipairs(REMOTES) do
	local r = Instance.new("RemoteEvent")
	r.Name = name
	r.Parent = remotes
end

-- The standalone place's scripts, if someone pasted them in: off, so they cannot open a second robot
-- socket, set Lighting or run the course outside the mode.
local starterScripts = StarterPlayer:FindFirstChild("StarterPlayerScripts")
for _, pair in ipairs({
	{ ServerScriptService, { "HazardManager", "BridgeFeed", "DebugMode", "DebugMenu", "GhostMode", "ActiveBayTracker" } },
	{ starterScripts, { "OverseerCam", "ObjectiveHud", "DebugCellEditor", "DebugMenu", "GhostControl", "BackdropFx",
		"CameraPolish" } },
}) do
	local parent, names = pair[1], pair[2]
	for _, name in ipairs(parent and names or {}) do
		local old = parent:FindFirstChild(name)
		if old and old:IsA("BaseScript") then
			old.Enabled = false
			problem("disabled the standalone %s; delete it when you are sure", old:GetFullName())
		end
	end
end
for _, name in ipairs({ "RunControl", "BlockSync", "SkyArm", "ArmMirror" }) do
	if ServerScriptService:FindFirstChild(name) then
		problem("ServerScriptService.%s (a standalone obby module?) is still there; the mode never uses it", name)
	end
end
for _, name in ipairs({ "Config", "BayData", "CrateDefs", "Mapping", "UiTheme" }) do
	if ReplicatedStorage:FindFirstChild(name) then
		problem("ReplicatedStorage.%s exists: if it is the standalone obby's, it is unused now", name)
	end
end

-- The map: geometry from Place1, inserted by hand (places/ObbyMap.rbxm).
local Config = require(ReplicatedStorage.Obby.Config)
local mode = ServerStorage.Modes.Obby
local map = mode:FindFirstChild("Map")
if not map then
	problem("ServerStorage.Modes.Obby.Map is missing: insert places/ObbyMap.rbxm (docs/obby-mode-plan.md \"Getting the map in\")")
elseif not map:IsA("Model") then
	problem("ServerStorage.Modes.Obby.Map is a %s, not a Model", map.ClassName)
else
	if map.ModelStreamingMode ~= Enum.ModelStreamingMode.Persistent then
		map.ModelStreamingMode = Enum.ModelStreamingMode.Persistent
		print("[install_obby_mode] set Map.ModelStreamingMode = Persistent")
	end
	for _, name in ipairs({ "Warehouse", "Backdrop", "Start", "Finish", "LobbyPad" }) do
		if not map:FindFirstChild(name) then
			problem("Map.%s is missing", name)
		end
	end
	local pad = map:FindFirstChild("LobbyPad")
	if pad and not CollectionService:HasTag(pad, "LobbyTeleporter") then
		CollectionService:AddTag(pad, "LobbyTeleporter")
		print("[install_obby_mode] tagged Map.LobbyPad LobbyTeleporter")
	end
	for _, d in ipairs(map:GetDescendants()) do
		if d:IsA("SpawnLocation") then
			problem("%s is a SpawnLocation: arcade players could spawn into the obby", d:GetFullName())
		elseif d:IsA("BaseScript") then
			problem("%s is a script inside the map; maps hold no code", d:GetFullName())
		end
	end
	local warehouse = map:FindFirstChild("Warehouse")
	local bay1 = warehouse and warehouse:FindFirstChild("Bay01")
	local anchors = bay1 and bay1:FindFirstChild("CrateAnchors")
	local anchor = anchors and anchors:FindFirstChild("Cell_0_0")
	local expected = Config.OriginZ + Config.CellSize / 2
	if anchor and math.abs(anchor.Position.Z - expected) > 1 then
		problem("Bay01.CrateAnchors.Cell_0_0 is at Z %.1f; expected about %.1f (Config.OriginZ %d). Map not moved?",
			anchor.Position.Z, expected, Config.OriginZ)
	end
end

local workshop = workspace:FindFirstChild("Workshop")
local bays = workshop and workshop:FindFirstChild("Bays")
local cabinet = nil
for _, bay in ipairs(bays and bays:GetChildren() or {}) do
	if (bay:GetAttribute("Mode") or bay.Name) == "Obby" then
		cabinet = bay
	end
end
if not cabinet then
	problem("no Workspace.Workshop.Bays.* with Mode = \"Obby\": the arcade has no portal for it")
end

pcall(function()
	ChangeHistoryService:SetWaypoint("Installed Robo Obby")
end)
print(string.format("[install_obby_mode] installed %d scripts and %d remotes%s", #made, #REMOTES,
	cabinet and (" for " .. cabinet:GetFullName()) or ""))
for _, line in ipairs(problems) do
	warn("[install_obby_mode] " .. line)
end
